window.JASTROW_CHUNKS[11]={"4400":{"h":"בֵּנוֹנִי","r":"B00943","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּינוֹנִי\">בֵּינוֹנִי</a></div>","alt":[]},"4401":{"h":"בְּנֵי","r":"B00944","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"בני\">בָּנָה</a>. <span class=\"citation\">Targ. Deut. XXV, 9</span> (Y. <a href=\"#\" data-headword=\"יַבְנֶה\">יִבְנֶה</a>); a. fr.—Part. <a href=\"#\" data-headword=\"בְּנֵי\">בָּנֵי</a>. <span class=\"citation\">Targ. Gen. IV, 17</span>.—<span class=\"citation\">M. Kat. 10ᵇ</span> <span dir=\"rtl\">מִיבְנֵי</span> to erect; a. e.</div><div class=\"sense\"><b>Ithpe. אִתְבְּנֵי</b> <div class=\"sense\"> as h. Nif. </div><div class=\"sense\"><b>1)</b>  a. 2). <span class=\"citation\">Targ. I Kings III, 2</span>; a. fr.—<span class=\"citation\">Targ. Gen. XVI, 2</span>; a. e.—Y. Ber. II, 5ᵃ <span dir=\"rtl\">מִתְבַּנְיֵי</span> will be rebuilt; a. e.</div></div>","alt":["בְּנָא"]},"4402":{"h":"בִּנְיָאתָא","r":"B00945","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּנְיָיתָא\">בִּנְיָיתָא</a></div>","alt":[]},"4403":{"h":"*בְּנִיגְנֵי","r":"B00946","html":"<div class=\"sense\"> pl. (benignae, sub. interpretationes, opp. durae, v. Harper’s Lat. Dict. 1882) <i>favorable side, mitigating circumstances</i>. <span class=\"citation\">Ab. Zar. 4ᵃ</span> <span dir=\"rtl\">אבקש ב׳ שלהם</span> ed. (Ms. <span dir=\"rtl\">בנו׳</span>; Ar. <span dir=\"rtl\">בנינגי</span>, taking <a href=\"#\" data-headword=\"ב\">ב</a> for a servile letter as do the commentaries) I shall search for what can be found in their favor.</div>","alt":[]},"4404":{"h":"בַּנָּיָה","r":"B00947","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>builder</i>. <span class=\"citation\">Y. Yoma III, 40ᶜ</span>; <span class=\"citation\">Y. Gitt. VII, 48ᵈ</span> bot.; <span class=\"citation\">Y. B. Bath. VIII, 16ᶜ</span> top <span dir=\"rtl\">ב׳ דאורייתא</span> a builder of the law (forming ingenious conclusions).—Pl. <a href=\"#\" data-headword=\"בַּנָּאִים\">בַּנָּיִין</a>. <span class=\"citation\">Y. Ber. IX, 13ᵃ</span> top; v. <a href=\"#\" data-headword=\"אוּמַן\">אוּמַן</a>.</div>","alt":["בַּנָּיָיה I"]},"4405":{"h":"בַּנָּיָיה II","r":"B00948","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Bannayah</i>, an Amora. <span class=\"citation\">Y. Peah I, 15ᵇ</span> bot.; a. fr. (Bab. <span class=\"citation\">B. Bath. 57ᵇ</span> <a href=\"#\" data-headword=\"בַּנָּאָה\">בַּנָּאָה</a>, v. <a href=\"#\" data-headword=\"בַּנַּאי II\"><span dir=\"rtl\">בַּנַּאי</span> II</a>).</div>","alt":[]},"4406":{"h":"בֵּנַיִים","r":"B00949","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּין\">בֵּין</a></div>","alt":[]},"4407":{"h":"בִּנְיָינָא","r":"B00950","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּנְיָנָא\">בִּנְיָנָא</a></div>","alt":[]},"4408":{"h":"בניינות","r":"B00951","html":"<div class=\"sense\">, <span class=\"citation\">Y. Shek. VI, 49ᵈ</span> top, v. <a href=\"#\" data-headword=\"בֵּינוֹנִי\">בֵּינוֹנִי</a></div>","alt":[]},"4409":{"h":"בִּנְיָיתָא","r":"B00952","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בני\">בני</a>; cmp. <span dir=\"rtl\">ארב</span>, <span dir=\"rtl\">ארג</span> a. denom.) <i>net-work, veils, curtains</i> &amp;c. <span class=\"citation\">Ber. 61ᵃ</span>; <span class=\"citation\">Sabb. 95ᵃ</span>; <span class=\"citation\">Erub. 18ᵃ</span>; <span class=\"citation\">Nidd. 45ᵇ</span> <span dir=\"rtl\">שכן בכרכי הים קורין לקלעייתא ב׳</span> (v. Rabb. D. S. a. l. for vers.) at the sea-towns they call all net-works <i>binyatha</i>; <span class=\"citation\">Koh. R. to VII, 2</span> <a href=\"#\" data-headword=\"בִּנְיָאתָא\">בִּנְיָאתָא</a> (Var. <a href=\"#\" data-headword=\"בנאיתא\">בנאיתא</a>).</div>","alt":["בִּנְיָתָא"]},"4410":{"h":"בִּנְיָן","r":"B00953","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>building, structure; erection</i>. <span class=\"citation\">Succ. 51ᵇ</span> <span dir=\"rtl\">מי שלא ראה בה&quot;מ בבִנְיָנוֹ</span> whoever has not seen the Temple in its finished state, expl. <span class=\"citation\">ibid.</span> <span dir=\"rtl\">בִּנְיַן הורדוס</span> the Herodian Temple (Ms. M. … <span dir=\"rtl\">ראה בנין בה&quot;מ</span>; v. Rabb. D. S. a. l. note).—<span dir=\"rtl\">אַמַּת הב׳</span>, v. <a href=\"#\" data-headword=\"אַמָּה\">אַמָּה</a>.—<span class=\"citation\">Sabb. 102ᵇ</span> <span dir=\"rtl\">דרך ב׳ בכן</span> such kind of labor belongs to builders’ work. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דמי לב׳</span> it looks like builders’ work; a. fr.—בִּנְיַן אב <i>standard rule</i>, v. <a href=\"#\" data-headword=\"אַבָּא I\">אָב</a>; v. <span class=\"citation\">Ḥull. 78ᵇ</span>, <span class=\"citation\">B. Kam. 77ᵇ</span> <span dir=\"rtl\">זה בנה אב</span> this (<span class=\"citation\">Ex. XII, 5</span>) forms the rule, wherever <a href=\"#\" data-headword=\"שֶׂה\">שה</a> is used &amp;c. (v. Tosaf. a. l.).—<span class=\"citation\">Sabb. 114ᵃ</span> <span dir=\"rtl\">בִּנְיָנוֹ של עולם</span> the preservation of the (mental and moral) world.</div><div class=\"sense\"><b>—2)</b> <i>human frame, skeleton.</i> Ohol. II, 1 <span dir=\"rtl\">רוב בניינו</span> the greater portion of a corpse as to size of limbs, contrad. to <span dir=\"rtl\">רוב מניינו</span> the larger as to the number of joints and limbs.</div>","alt":["בִּינְיָן"]},"4411":{"h":"בִּנְיָנָא","r":"B00954","html":"<div class=\"sense\"><span class=\"citation\">Targ. Koh. III, 3</span>; a. e.</div>","alt":[]},"4412":{"h":"בְּנִיסָא","r":"B00955","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּנַס\">בנס</a>) <i>sour; angry, sad.</i> Pl. <span dir=\"rtl\">בְּנִיסִין</span>; f. <a href=\"#\" data-headword=\"בְּנִיסָא\">בְּנִיסָתָא</a>. <span class=\"citation\">Targ. Y. Gen. XL, 6</span> (O. <span dir=\"rtl\">נסיסין</span>). <span class=\"citation\">Targ. Prov. XXV, 23</span>. [Y. Shek. IV, 48ᵇ bot. <span dir=\"rtl\">בניסין</span>, read: <span dir=\"rtl\">בֵּינֵיהוֹן</span>, v. <a href=\"#\" data-headword=\"בֵּין\">בֵּין</a> ch.]</div>","alt":["בְּנִיסְתָּא"]},"4413":{"h":"בניסן","r":"B00956","html":"<div class=\"sense\">, <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> <span dir=\"rtl\">תמני … ב׳</span>, v. <a href=\"#\" data-headword=\"כְּנִישָׁא\">כְּנִישָׁא</a></div>","alt":[]},"4414":{"h":"בְּנִיפִיקִין","r":"B00957","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (beneficium, βενεφίκιον) <i>favor, grant, </i>esp<i>.</i> <i> the rights of a privileged person concerning the protection of his character</i>. Tanḥ. Korah (ed. Bub.) addit. 2 (cmp. Tanḥ. ib. 8) <span dir=\"rtl\">משל לשושבינה של בת המלך שביקש בני פיקון מן המלך</span> (corr. acc.) this is to be compared to a sponsor of the King’s daughter who claimed satisfaction of the King on the ground of his privileges. He said to the King <span dir=\"rtl\">אם אינך תובע ב׳ שלי</span> if thou wilt not stand up for my privileges &amp;c.; <span class=\"citation\">Num. R. s. 18</span> <span dir=\"rtl\">בנפקין שלך</span> (corr. acc.).</div>","alt":["(בנפיקין)"]},"4415":{"h":"בְּנִיפִיקָרִין","r":"B00958","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (beneficiarii, βενεφικάλιοι) <i>the commander’s attendants, orderlies</i>. Sifrè Deut. 317 (<span dir=\"rtl\">בני פיקרין</span>, <span dir=\"rtl\">בני פוקרים</span> corr. acc.); <span class=\"citation\">Yalk. Deut. 944</span> <span dir=\"rtl\">אלו ב׳ שלהם</span> those are their (the Roman) beneficiarii.</div>","alt":[]},"4416":{"h":"בִּנְיָתָא","r":"B00959","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּנְיָיתָא\">בִּנְיָיתָא</a></div>","alt":[]},"4417":{"h":"*בִּנְכֵּי","r":"B00960","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (√<span dir=\"rtl\">בך</span>, v. <a href=\"#\" data-headword=\"בכי\">בכי</a>) <i>cavities</i> dug around the vine to receive the water, = h. <a href=\"#\" data-headword=\"בָּדִיד\">בָּדִיד</a> 2). <span class=\"citation\">M. Kat. 4ᵇ</span></div>","alt":[]},"4418":{"h":"בְּנָן","r":"B00961","html":"<div class=\"sense\"> pl., v. <a href=\"#\" data-headword=\"בְּרַתָּא\">בְּרַתָּא</a>.—[V. also <a href=\"#\" data-headword=\"בֵּן\">בֵּן</a>.]</div>","alt":[]},"4419":{"h":"בְּנַס","r":"B00962","html":"<div class=\"sense\"> (sec. r. of <span dir=\"rtl\">בס</span>, v. <span dir=\"rtl\">בסם</span>) <i>to ferment, get sour;</i> trnsf. <i>to be angry, agitated.</i> <span class=\"citation\">Dan. II, 12</span>. <span class=\"citation\">Targ. Y. Gen. XL, 2</span>. <span class=\"citation\">Targ. Esth. II, 21</span> <span dir=\"rtl\">בנסו וקצפו</span> (ed. Vien. <span dir=\"rtl\">כְּנַסּוּ</span>, corr. acc.). <span class=\"citation\">Ib. IV, 17</span> <span dir=\"rtl\">ונסס וב׳</span> (ed. Vien. <span dir=\"rtl\">וכ׳</span>, corr. acc., h. text <span dir=\"rtl\">ויעבר</span>!); v. <a href=\"#\" data-headword=\"נְסַס\">נְסַס</a>.—Part. pass. <span dir=\"rtl\">בְּנִיס</span>, v. <a href=\"#\" data-headword=\"בְּנִיסָא\">בְּנִיסָא</a>. Denom. <a href=\"#\" data-headword=\"*בַּסִּין\">בַּסִּין</a>.</div>","alt":[]},"4420":{"h":"בְּנָסָא","r":"B00963","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּנַס\">preced.</a>) <i>anger, ill-humor</i>. <span class=\"citation\">Targ. Job XVI, 10</span> (Ms. <a href=\"#\" data-headword=\"כנסא\">כנסא</a>, some ed. <a href=\"#\" data-headword=\"בְּנָסָא\">בַּנָּסָא</a>).</div>","alt":[]},"4421":{"h":"בנפיקין","r":"B00964","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּנִיפִיקִין\">בְּנִיפִיקִין</a></div>","alt":["בנפקין"]},"4422":{"h":"בַּנְּרִיּוֹת","r":"B00965","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"בַּלְנְרִין\">בלנרין</a>; cmp. βανίαριν for βαλνιαρία, S.) <i>bathing apparel</i>. <span class=\"citation\">Gen. R. s. 45</span> <span dir=\"rtl\">דליים וב׳ וכ׳</span> (Ar. <a href=\"#\" data-headword=\"כנריות\">כנריות</a>, some ed. <span dir=\"rtl\">פנדיות</span>) buckets and bathing apparel did she make her carry &amp;c.; <span class=\"citation\">Yalk. Gen. 79</span> <a href=\"#\" data-headword=\"סנדלריאות\">סנדלריאות</a> (corr. acc.).</div>","alt":[]},"4423":{"h":"בַּנַּרְיָיתָא","r":"B00966","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"><span class=\"citation\">Y. B. Kam. VII, end 6ᵃ</span> אנא נסיב בַּנַּרְיָיתֵיה I will carry his bathing clothes (i.e. I will be his servant; cmp. <span class=\"citation\">B. Mets. 41ᵃ</span>; <span class=\"citation\">Erub. 27ᵇ</span>; <span class=\"citation\">Snh. 62ᵇ</span>).</div>","alt":[]},"4424":{"h":"בנרסיי","r":"B00967","html":"<div class=\"sense\">, <span class=\"citation\">Y. Kil. IX, 32ᵇ</span> top, v. <a href=\"#\" data-headword=\"דַּרְדְּסָא\">דַּרְדֵּסִין</a></div>","alt":[]},"4425":{"h":"בְּנָתָא","r":"B00968","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"בְּרַתָּא\">בְּרַתָּא</a>.</div>","alt":["בְּנָתָן"]},"4426":{"h":"בֵּנְתַּיִים","r":"B00969","html":"<div class=\"sense\">, v. <span dir=\"rtl\">בַּיִן</span>, <span dir=\"rtl\">בֵּין</span>.</div>","alt":[]},"4427":{"h":"בנתיקה","r":"B00970","html":"<div class=\"sense\">, <span class=\"citation\">Y. Snh. VII, 25ᵈ</span>, v. <a href=\"#\" data-headword=\"נְתִיקָה\">נְתִיקָה</a> ch.</div>","alt":[]},"4428":{"h":"בְּסָא","r":"B00971","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בסי\">בסי</a></div>","alt":[]},"4429":{"h":"*בסאטה","r":"B00972","html":"<div class=\"sense\">, Pesik. R. suppl. (p. 197ᵃ ed. Fr.), v. <a href=\"#\" data-headword=\"*הַסְטָא\">הַסְטָא</a></div>","alt":[]},"4430":{"h":"בסבסטי","r":"B00973","html":"<div class=\"sense\">, <span class=\"citation\">Num. R. s. 10</span>, v. <a href=\"#\" data-headword=\"סְבַסְטִי\">סְבַסְטִי</a></div>","alt":[]},"4431":{"h":"בס\"גר","r":"B00974","html":"<div class=\"sense\"> a mnemotechnical device, representing <span dir=\"rtl\">ב̇המה</span>, <span dir=\"rtl\">חס̇רון</span>, <span dir=\"rtl\">ג̇לודה</span> and <span dir=\"rtl\">חר̇ותא</span>. <span class=\"citation\">Ḥull. 42ᵃ</span>; <span class=\"citation\">42ᵇ</span></div>","alt":[]},"4432":{"h":"בסגר","r":"B00975","html":"<div class=\"sense\">, <span class=\"citation\">Lam. R. to III, 7</span> <span dir=\"rtl\">ב׳ של ערבייא</span> (Yalk. a. l. <span dir=\"rtl\"><span dir=\"rtl\">גנד</span> (<a href=\"#\" data-headword=\"גּוּנְדָּא I\">גונדא</a>) <span dir=\"rtl\">של ערביים</span>)</span> prob. to be read: <a href=\"#\" data-headword=\"הֶסְגֵּר\">הֶסְגֵּר</a> <i>the locking up</i> of Jerusalem by the Arabs, v. ib. to I, 5.—[For <span dir=\"rtl\">קסטרא של פרסיים</span> ibid., read <span dir=\"rtl\">רוֹמִיִּים</span>.]</div>","alt":[]},"4433":{"h":"בְּסוּמָא","r":"B00976","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בסם</span>) <i>sweet-meat, delicacy.</i> <i>—</i> Pl. <span dir=\"rtl\">בְּסוּמֵי</span>. <span class=\"citation\">Erub. 82ᵇ</span>; <span class=\"citation\">Meg. 7ᵇ</span> רווחא לב׳ וכ׳ Ms. M. (ed. sing., Var. in ed. <span dir=\"rtl\">בסימא</span>, <a href=\"#\" data-headword=\"בְּסִימָה\">בסימה</a>) for delicacies there is always room (appetite). V. <a href=\"#\" data-headword=\"בָּשׂוּם\">בָּשׂוּם</a>.</div>","alt":[]},"4434":{"h":"בסוס","r":"B00977","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"בָּסִיס\">בָּסִיס</a>.</div>","alt":[]},"4435":{"h":"בְּסוֹרָא","r":"B00978","html":"<div class=\"sense\">, v. <span dir=\"rtl\">בְּשׂו׳</span></div>","alt":["בְּסוֹרְתָא"]},"4436":{"h":"בְּסוֹרָה","r":"B00979","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">בְּסוֹרוֹת</span> (<span dir=\"rtl\">בסר</span>) <i>first-ripe fruits, first priestly gifts</i>. <span class=\"citation\">Keth. 16ᵇ</span> כוס של ב׳ Ar. (ed. <a href=\"#\" data-headword=\"בְּשׂוֹרָה\">בשורה</a>), expl. <span dir=\"rtl\">כוס יין של תרומה</span>. Y. ib. II, 26ᵇ top <span dir=\"rtl\">חבית של בסורות</span> (ed. Krot. <span dir=\"rtl\">בשורות</span>).</div>","alt":[]},"4437":{"h":"*בֶּסְטְיָא","r":"B00980","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (βέστια, pl. = vestes) <i>garments</i>. <span class=\"citation\">Num. R. s. 7</span> <span dir=\"rtl\">כלים וב׳</span>. [Prob. our w. was a gloss to <span dir=\"rtl\">כלים</span>.]</div>","alt":[]},"4438":{"h":"בסי","r":"B00981","html":"<div class=\"sense\"> (v. <span dir=\"rtl\">בסס</span>) <i>to trample upon;</i> hence (with <a href=\"#\" data-headword=\"ב\">ב־</a>) <i>to despise;</i> v. <a href=\"#\" data-headword=\"בְּזֵי ²\"><span dir=\"rtl\">בְּזֵי</span> I</a>; cmp. <a href=\"#\" data-headword=\"בְּטַשׁ\">בְּטַשׁ</a>.</div><div class=\"sense\"><b>Pa. בַּסֵּי</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"*בֶּסְטְיָא\">same</a>. Y. Ter. VIII, end, 46ᶜ <span dir=\"rtl\">לא מבסי לא ברומי וכ׳</span> (read <span dir=\"rtl\">תְבַסֵּי</span>) despise neither a Roman of low standing &amp;c.; (<span class=\"citation\">Gen. R. s. 63</span> <span dir=\"rtl\">לא תבזון</span>).—</div><div class=\"sense\"><b>*2)</b>  (Arab. <span dir=\"rtl\">בס</span>ّ) <i>to drive, instigate</i>. <span class=\"citation\">Gen. R. s. 79</span>, end, heard an Arab say to his neighbor <span dir=\"rtl\">מה את מְבַסֵּה בי וכ׳</span> (some ed. <span dir=\"rtl\">מכ׳</span>, corr. acc.) why art thou driving me? and he meant to say <span dir=\"rtl\">מה את מְעַשֶּׂה בי</span> (Var. <span dir=\"rtl\">מְעַסֶּה</span>) why wilt thou force me?—from which they learned the meaning of <span dir=\"rtl\">ועסותם</span>, <span class=\"citation\">Mal. III, 21</span>.</div></div>","alt":["בְּסָא"]},"4439":{"h":"בִּסְיָא","r":"B00982","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בסי\">preced.</a>; = h. <a href=\"#\" data-headword=\"פְּשִׁיעָה\">פְּשִׁיעָה</a>) <i>indifference, willful negligence</i>. <span class=\"citation\">Targ. Y. Ex. XXII, 8</span> <span dir=\"rtl\">בכו׳</span> (corr. acc.). Y. B. Mets. V, 10ᵇ bot. <span dir=\"rtl\">מתה בב׳</span> if the animal died through negligence; <span class=\"citation\">Tosef. ib. V, 10</span> <span dir=\"rtl\">בבוסיא</span> ed. Zuck. (Var. <span dir=\"rtl\">בכ׳</span>). <span class=\"citation\">B. Kam. 116ᵇ</span> <span dir=\"rtl\">בבו׳ וכ׳</span> (Var. <span dir=\"rtl\">בכ׳</span>; Ms. M. <span dir=\"rtl\">בבִיסְיָא</span>, <span dir=\"rtl\">בבו׳</span>).</div>","alt":["בּוּסְיָא"]},"4440":{"h":"בסיג׳","r":"B00983","html":"<div class=\"sense\">, v. <span dir=\"rtl\">פסיג׳</span></div>","alt":[]},"4441":{"h":"בסילגוס","r":"B00984","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"בָּסִילְיוֹס\">בָּסִילְיוֹס</a>.</div>","alt":["בסילוגוס"]},"4442":{"h":"בָּסִילֵיאוֹס","r":"B00985","html":"<div class=\"sense\"> (βασιλέως, Genit. of βασιλεύς); v. <a href=\"#\" data-headword=\"בָּסִילְיוֹס\">בָּסִילְיוֹס</a>. <span class=\"citation\">Y. R. Hash. I, 57ᵃ</span> bot., v. <a href=\"#\" data-headword=\"*אַגְרָפוֹס\">אַגְרָפוֹס</a>.</div>","alt":[]},"4443":{"h":"בָּסִילְיוֹן","r":"B00986","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  ( m. (βασίλειον, τὸ) <i>royal seat, palace</i>. <span class=\"citation\">Y. Snh. II, 20ᶜ</span> <span dir=\"rtl\">מלכא יתיב על ב׳ דידיה וכ׳</span> (read <span dir=\"rtl\">בי ב׳</span>) the King sits in his palace, and thou sayest thou art the King?</div><div class=\"sense\"><b>—2)</b>  (genit. of βασίλεια, τὰ) <i>of the palace</i>, or <i>of the royal affairs</i>. <span class=\"citation\">Gen. R. s. 93</span> <span dir=\"rtl\">פטרון ב׳</span> (πάτρων τῶν βασιλείων) <i>superintendent of</i></div>","alt":[]},"4444":{"h":"בָּסִילְיוֹס","r":"B00987","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (βασιλεύς) <i>king</i>. <span class=\"citation\">Y. Ber. IX, 12ᵈ</span> bot.; <span class=\"citation\">Gen. R. s. 8</span> (corr. acc.).</div>","alt":["בָּסִילְייוֹס"]},"4445":{"h":"בָּסִילְקִי","r":"B00988","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (βασιλική, sub. στοά) <i>basilica, a building with colonnades</i> for holding courts, also <i>meeting place for merchants, exchange, forum</i>. <span class=\"citation\">Yoma 25ᵃ</span> <span dir=\"rtl\">כמין ב׳ גדולה</span> was built in the style of a large basilica (semicircular). <span class=\"citation\">Tosef. Succ. IV, 6</span> (describing the Alexandrian Synagogue); <span class=\"citation\">Succ. 51ᵇ</span>. <span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">עולים לב׳ וכ׳</span> one goes up to the basil. and finds the King holding court. <span class=\"citation\">Ex. R. s. 15</span>; Tanḥ. Ḥaye 3 <span dir=\"rtl\">שמא אצל ב׳ וכ׳</span> perhaps he wanted me to wait for him near the basilica (on the forum). <span class=\"citation\">Esth. R. to I, 3</span>. <span class=\"citation\">Toh. VI, 8</span>; <span class=\"citation\">Tosef. ib. VII, 12</span>; a. fr. [<span class=\"citation\">Y. B. Bath. IV, 14ᶜ</span> bot. <a href=\"#\" data-headword=\"בסלקי\">בסלקי</a>, v. <a href=\"#\" data-headword=\"*כַּלְכּוּס\">כַּלְכּוֹס</a>.]—Pl. <span dir=\"rtl\">בָּסִילְקָאוֹת</span>. <span class=\"citation\">Ab. Zar. 16ᵇ</span> <span dir=\"rtl\">שלש ב׳ הן וכ׳</span> there are three kinds of basilicas, for Kings (holding court), for baths, and royal treasuries (τὸ βασιλικόν, sub. ταμεῖον, S.). <span class=\"citation\">Tosef. Ohol. XVIII, 18</span> selling wheat <span dir=\"rtl\">בב׳ שלהן</span> in their (the gentiles’) exchanges. [<span class=\"citation\">Lev. R. s. 34</span> <a href=\"#\" data-headword=\"בסלקי\">בסלקי</a>, read <span dir=\"rtl\">בפִילָקִי</span>.]</div>","alt":["(בסלקי)"]},"4446":{"h":"בְּסִים","r":"B00989","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּסַם\">בְּסַם</a></div>","alt":[]},"4447":{"h":"בָּסִים","r":"B00990","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בסם</span>) <i>boiled, ripe</i>, whence </div><div class=\"sense\"><b>1)</b>  (Var. <a href=\"#\" data-headword=\"בְּסִים\">בְּסִים</a>, <a href=\"#\" data-headword=\"בָּסִים\">בַּסִּים</a>, <a href=\"#\" data-headword=\"בְּסִימָא\">בַּסִּימָא</a>) <i>sweet, pleasant, well-seasoned</i> &amp;c. (= h. <span dir=\"rtl\">ערב</span>). <span class=\"citation\">Targ. Ps. CXLI, 2</span> (h. text <span dir=\"rtl\">ערב</span>, translated in both senses); a. fr.—<span class=\"citation\">Keth. 104ᵃ</span> top <span dir=\"rtl\">דמדליא וב׳ אוירא</span> which lies high and whose air is pleasant (temperate). <span class=\"citation\">R. Hash. 21ᵃ</span> <span dir=\"rtl\">ב׳ תבשילא וכ׳</span> (Ms. M. 2 margin <span dir=\"rtl\">כמה ב׳</span>; v. Rabb. D. S. a. l. note 80) how well tastes the food of the Babylonians on the day when in Palestine they observe the Day of Atonement! <span class=\"citation\">B. Mets. 60ᵃ</span> <span dir=\"rtl\">לא הוה ב׳</span> (the wine) was not good. <span class=\"citation\">Ib. 69ᵇ</span> <span dir=\"rtl\">דאיכא דב׳ וכ׳</span> that there is good and bad wine. <span class=\"citation\">Ber. 56ᵃ</span> <span dir=\"rtl\">ב׳ חמרך</span> thy wine will be good.—Pl. <span dir=\"rtl\">בְּסִימִין</span>, fem. <a href=\"#\" data-headword=\"בְּסִימָא\">בְּסִימָן</a>, <a href=\"#\" data-headword=\"בָּסִים\">בְּסִימָתָא</a> (also as nouns, as h. <span dir=\"rtl\">נעימים</span>, <span dir=\"rtl\">נעימית</span>). <span class=\"citation\">Targ. Y. Num. XXXIII, 28</span> sq.; a. e.—V. <a href=\"#\" data-headword=\"בַּסִּימַיָּא\">בַּסִּימַיָּא</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"חַלָּא\">חַלָּא</a>) <i>fermenting, sour</i>. <span class=\"citation\">Y. Maas. Sh. IV, 55ᶜ</span> top <span dir=\"rtl\">חמרא … מיפוק בסים</span> this man’s (thy) wine shall turn sour (ferment); v. <a href=\"#\" data-headword=\"*בַּסִּין\">בַּסִּין</a>. <span class=\"citation\">Lam. R. to I, 1</span> (חד מאתינס 7) <span dir=\"rtl\">וחד דבסים</span> and one bag with sour wine. Ib. <span dir=\"rtl\">דבסימא תסיס</span> the dripping of the sour wine bubbles. Ib. <span dir=\"rtl\">(<span dir=\"rtl\">חד כותאי</span>) <span dir=\"rtl\">ונפיק כוליה בסים</span></span> and it will all turn sour.</div>","alt":["בְּסִימָא","בְּסִימָא","בְּסִימְתָּא"]},"4448":{"h":"בְּסִימָא","r":"B00991","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בָּסִים\">preced.</a></div><div class=\"sense\"><b>2)</b> <i>fermenting wine, wine turned into vinegar</i>. <span class=\"citation\">Lam. R. to III, 40</span> אין דעולית׳ מרירן בסימא חמיע Ar. (ed. <span dir=\"rtl\">אית כרנבי ב׳ דסימא חמיע</span>; read <span dir=\"rtl\">אין דכר׳</span>, strike out <span dir=\"rtl\">דסימא</span>) when the endive (the cabbage) is bitter, the fermenting wine turns sour (sin begets sin). Cant. R. end, if the vineyard is cut before its time, <span dir=\"rtl\">אפי׳ בִסְמֵיה וכ׳</span> even its vinegar is not good.</div>","alt":["בִּסְמָא"]},"4449":{"h":"בְּסִימָה","r":"B00992","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"בְּסִימָא\">same</a>. <span class=\"citation\">Y. Pes. III, beg. 29ᵈ</span> formerly … the wine (in Judæa) never turned sour, and they put in barley to make it sour, whence it was called <span dir=\"rtl\">ב׳ דרומיא</span> Southern vinegar (fermentation, = h. <span dir=\"rtl\">חומץ האדומי</span>).</div>","alt":[]},"4450":{"h":"בְּסִימוּתָא","r":"B00993","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בסם</span>) <i>sweetness</i>. <span class=\"citation\">Targ. Ps. XXVII, 4</span>; a. e.</div>","alt":[]},"4451":{"h":"בַּסִּימַיָּא","r":"B00994","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">בסם</span>; = h. <span dir=\"rtl\">חֲנֻטִים</span>) <i>embalming process</i>. <span class=\"citation\">Targ. Y. Gen. L, 3</span>.</div>","alt":[]},"4452":{"h":"*בַּסִּין","r":"B00995","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּנַס\">בנס</a>) <i>vinegar</i>. <span dir=\"rtl\">את מינסב חסין וצבע בב׳</span> thou wilt take lettuce and dip in vinegar. [Prob. <span dir=\"rtl\">בסים</span>.]</div>","alt":[]},"4453":{"h":"בְּסִיס","r":"B00996","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּסַס\">בְּסַס</a></div>","alt":[]},"4454":{"h":"בָּסִיס","r":"B00997","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בּוּס\">בוס</a>, <span dir=\"rtl\">בסס</span>; formed like <a href=\"#\" data-headword=\"עָצִיץ\">עָצִיץ</a>) <i>anything to tread upon; footstool, stand, base</i> (= b. h. <a href=\"#\" data-headword=\"כַּן\">כַּן</a>, <a href=\"#\" data-headword=\"מְכוֹנָה\">מְכוֹנָה</a>). <span class=\"citation\">Kel. XI, 7</span> <span dir=\"rtl\">הפרח והב׳</span> the bud (receptacle of the candlestick) and the stand. <span class=\"citation\">Lev. R. s. 25</span>; <span class=\"citation\">Cant. R. to V, 15</span> like a column which has <span dir=\"rtl\">ב׳ מלמטן וכ׳</span> a base beneath &amp;c.; Tanḥ. B’har 1. <span class=\"citation\">Y. Ab. Zar. III, 42ᵈ</span> top <span dir=\"rtl\">בשאין עליהן ב׳</span> when there is upon them (the idolatrous emblems) no stand (indicating that they were intended for practical use). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כוס בסוס לדרקון וכ׳</span> (corr. acc.) if the cup serves as a stand for the dragon (idolatrous emblem), it (the cup) is forbidden; a. fr.—Trnsf. (in Sabbath law) <i>whatever is subservient to another object</i>, e.g. the case in which a book is kept, the table upon which a lamp is placed. <span class=\"citation\">Sabb. 117ᵃ</span> <span dir=\"rtl\">ב׳ לדבר האסור</span> subservient to an object which must not be handled on the Sabbath; a. fr.—V. <a href=\"#\" data-headword=\"בְּסִיסַי\">בְּסִיסַי</a>, <a href=\"#\" data-headword=\"בְּסִיסַי\">בְּסִיסִית</a>.</div>","alt":[]},"4455":{"h":"בְּסִיס ²","r":"B00998","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. I Kings VII, 30</span>; a. fr.—<span class=\"citation\">Y. Sabb. XVII, 16ᵇ</span> top <span dir=\"rtl\">ב׳ דידיה</span> its (the delphica’s) pedestal. <span class=\"citation\">Y. Succ. V, 55ᵇ</span> bot. whatever (structure) stands isolated being one hundred feet high <span dir=\"rtl\">בעי ב׳ וכ׳</span> requires a buttress (in the shape of an ascent) of thirty three cubits on each side.—Pl. <span dir=\"rtl\">בְּסִיסַיָּא</span>. <span class=\"citation\">Targ. I Kings VII, 27</span>; a. e.</div>","alt":["בְּסִיסָא"]},"4456":{"h":"בְּסִיסַי","r":"B00999","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"בָּסִיס\">בָּסִיס</a>; <span dir=\"rtl\">בסס</span>) <i>foot-stool, base, stand, step.</i> <i>—</i> Pl. <span dir=\"rtl\">בְּסִיסָאוֹת</span> Ar., <span dir=\"rtl\">בְּסִיסִיּוֹת</span>, <span dir=\"rtl\">בְּסָסִיּוֹת</span>. <span class=\"citation\">Kel. XXIV, 6</span> <span dir=\"rtl\">שלש בְּסָ׳ הן</span> (Ar. <span dir=\"rtl\">בסי׳</span>) there are three stands, one before the bed (step) &amp;c. <span class=\"citation\">Num. R. s. 10</span>, beg. <span dir=\"rtl\">בסיסיות</span>, v. <a href=\"#\" data-headword=\"בָּסִיס\">בָּסִיס</a>.</div>","alt":["בְּסִיסִית","בְּסָסִית"]},"4457":{"h":"בְּסִיר","r":"B01000","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  (<span dir=\"rtl\">בַּסִּ׳</span>) (<span dir=\"rtl\">בסר</span>) <i>contemned, contemptible</i>. <span class=\"citation\">Targ. Ps. XV, 4</span>; a. fr.—Pl. <span dir=\"rtl\">בְּסִירִין</span>, fem. <a href=\"#\" data-headword=\"בְּסִיר\">בְּסִירָן</a>. <span class=\"citation\">Targ. Mal. II, 9</span>; <span class=\"citation\">I, 12</span>. <span class=\"citation\">Targ. Jud. IX, 4</span>, v. <a href=\"#\" data-headword=\"*בַּקָּרָא II\"><span dir=\"rtl\">בַּקָּרָא</span> II</a>.</div><div class=\"sense\"><b>—2)</b> <i>ripening</i>, v. <a href=\"#\" data-headword=\"בְּשַׂר ²\"><span dir=\"rtl\">בְּסַר</span> II</a>.</div>","alt":["בְּסִירָא"]},"4458":{"h":"בְּסִירוּתָא","r":"B01001","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּסִיר\">preced.</a>) <i>contempt.</i> <span class=\"citation\">Targ. Ps. CXXIII, 3</span>.</div>","alt":[]},"4459":{"h":"בסלקי","r":"B01002","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּסִילְקִי\">בָּסִילְקִי</a></div>","alt":[]},"4460":{"h":"בָּסֵם","r":"B01003","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בס</span>, <span dir=\"rtl\">בש</span>, cmp. <a href=\"#\" data-headword=\"בָּשַׁל\">בָּשַׁל</a>, <i>to boil, ripen, be warm, ferment</i>) <i>to be sweet, pleasant, pleasing</i>. <span class=\"citation\">Lam. R. to I, 9</span> <span dir=\"rtl\">יערב לך ויִבְסַם לך</span> may (the sacrifice) be sweet unto thee (Moloch), may it be pleasing unto thee. <span class=\"citation\">Gen. R. s. 85</span> <span dir=\"rtl\">יערב לכם יבושם וכ׳</span> (<span class=\"citation\">Yalk. Gen. 144</span>, Josh. 35 <span dir=\"rtl\">יבסם</span>) may (the wine you drank) be sweet to you, may it well agree with you.—Denom. <span dir=\"rtl\">בּוֹסֶם</span>.</div><div class=\"sense\"><b>Pi. בִּסֵּם  בִּיסֵּם</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"בִּישֵּׂם\">בִּישֵּׂם</a> <i>to make a person look well</i>, esp. (denom. of <span dir=\"rtl\">בּוֹסֶם</span>) <i>to perfume with oil</i> &amp;c. <span class=\"citation\">Ex. R. s. 23</span> a bride <span dir=\"rtl\">מקשטין אותה ומְבַסְּמִין אותה</span> is adorned and made handsome (her toilet is attended to).—Part. pass. <span dir=\"rtl\">מְבוּסָּם</span>, f. <span dir=\"rtl\">מְבוּסֶּמֶת</span>, <span dir=\"rtl\">מְבוּשּׂ׳</span> <i>perfumed, sweet</i> &amp;c. <span class=\"citation\">Num. R. s. 20</span> <span dir=\"rtl\">מקושטת ומב׳</span> in full toilet. <span class=\"citation\">Tosef. Ber. VI</span> (<span class=\"citation\">V), 5</span> it is not becoming for a scholar <span dir=\"rtl\">שיצא מבוסם</span> to go out with perfumed oil on his head; <span class=\"citation\">Ber. 43ᵇ</span> <span dir=\"rtl\">מבוש׳</span>. <span class=\"citation\">B. Bath. VI, 3</span> <span dir=\"rtl\">יין מב׳</span> sweet wine (guaranteed as not sour). [<span class=\"citation\">Pesik. R. s. 21</span> <span dir=\"rtl\">בישם העולם</span>; Ruth. R. beg. <span dir=\"rtl\">ביסם</span>, read <a href=\"#\" data-headword=\"בָּסַס\">בִּיסֵּס</a>, v. <a href=\"#\" data-headword=\"בָּסַס\">בָּסַס</a>.]</div></div><div class=\"sense\"><b>Hithpa. הִתְבַּסֵּם  הִתְבַּשֵּׂ׳</b> <div class=\"sense\">; <i>Nithpa</i>. <a href=\"#\" data-headword=\"בָּסַס\">נִתְבַּסֵּם</a>, <a href=\"#\" data-headword=\"בָּשַׂר\">נִתְבַּשֵּׂ׳</a> </div><div class=\"sense\"><b>1)</b> <i>to perfume one’s self with oil</i> &amp;c. <span class=\"citation\">Gen. R. s. 17</span>. &amp;c. <span class=\"citation\">Gen. R. s. 17</span>.</div><div class=\"sense\"><b>—2)</b> <i>to become exhilarated, to feel the wine</i>. <span class=\"citation\">Koh. R. to XI, 9</span> <span dir=\"rtl\">אכל ושתה ונת׳</span> he ate and drank and felt well.</div><div class=\"sense\"><b>—3)</b>  trnsf. <i>to grow better, improve</i>. <span class=\"citation\">Gen. R. s. 67</span>, end <span dir=\"rtl\">נִתְבַּסְּמָה דעתו עליו</span> his character grew better (play on <span dir=\"rtl\">בשמת</span> <span class=\"citation\">Gen. XXVI, 34</span>).—[<span class=\"citation\">Gen. R. s. 66</span> <span dir=\"rtl\">נתבשם העולם</span>, v. <a href=\"#\" data-headword=\"בָּסַס\">בָּסַס</a>.]</div></div>","alt":["בָּשֵׂם"]},"4461":{"h":"בְּסַם","r":"B01004","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ex. XV, 25</span>; a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"בְּסִים\">בְּסִים</a>, v. <a href=\"#\" data-headword=\"בָּסִים\">בָּסִים</a>.</div><div class=\"sense\"><b>Pa. בַּסֵּים</b> <div class=\"sense\"><b>1)</b> <i>to sweeten, season;</i> trnsf. <i>to make happy, to delight</i>. <span class=\"citation\">Targ. Y. Num. XVIII, 19</span>. <span class=\"citation\">Targ. Ps. CXIX, 122</span>; a. e.—<span class=\"citation\">Succ. 51ᵃ</span>; <span class=\"citation\">Arakh. 11ᵃ</span> <span dir=\"rtl\">לבַסּוּמֵי קלא</span> to sweeten the sound (by means of instrumental accompaniment).</div><div class=\"sense\"><b>—2)</b> <i>to embalm</i>. <span class=\"citation\">Targ. Y. Gen. L, 2</span>; <span class=\"citation\">26</span>.—Part. pass. <span dir=\"rtl\">מְבַסַּם</span>. Targ. O. XXX, 25.</div></div><div class=\"sense\"><b>Ithpa. אִיתְבַּסֵּם</b> </div><div class=\"sense\"><b>Ithpe. אִיתְבְּסַם</b> <div class=\"sense\">, contr. <span dir=\"rtl\">אִיבְּסִים</span> </div><div class=\"sense\"><b>1)</b> <i>to be sweet, well-seasoned, prepared</i>. <span class=\"citation\">Targ. Job XXIV, 20</span>. <span class=\"citation\">Targ. Y. Ex. XXX, 25</span> <span dir=\"rtl\">מִתְבַּשֵּׂם</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to be embalmed</i>. <span class=\"citation\">Targ. Y. Gen. L, 3</span>.</div><div class=\"sense\"><b>—3)</b> <i>to be cheerful, feel the wine;</i> cmp. <a href=\"#\" data-headword=\"*בְּלוּזְמָא\">בְּלוּזְמָא</a>. <span class=\"citation\">Snh. 38ᵃ</span> <span dir=\"rtl\">כיון דאִיבְּסוּם</span> when they were feeling the wine. <span class=\"citation\">Sabb. 66ᵇ</span>. <span class=\"citation\">B. Bath. 73ᵇ</span> bot.—<span class=\"citation\">Meg. 7ᵇ</span> <span dir=\"rtl\">מיחייב אינש לִבְּסוּמֵי וכ׳</span> (= <span dir=\"rtl\">לאיבסומי</span>, v. Rashi a. l.) one must cheer himself up with wine &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">איבסום</span> they were feeling the wine (v. Rabb. D. S. a. l. note). [<span class=\"citation\">Targ. Cant. II, 5</span> <span dir=\"rtl\">אתבסם</span>, v. <a href=\"#\" data-headword=\"בְּסַס\">בְּסַס</a>.]</div></div>","alt":[]},"4462":{"h":"בַּסָּם","r":"B01005","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּסַם\">preced.</a>) <i>dealer in</i>, or <i>manufacturer of, spices, perfumes</i> &amp;c.; <i>druggist</i>. <span class=\"citation\">Kidd. 82ᵇ</span>. <span class=\"citation\">Tosef. ib. II, 2</span>; <span class=\"citation\">4</span>. Y. Ber. IX, 13ᶜ bot. <span class=\"citation\">B. Mets. 56ᵇ</span> if one sells his (cancelled) notes <span dir=\"rtl\">לב׳</span> to a druggist (for wrapping paper); a. fr.—[<span class=\"citation\">Tosef. Ber. VI</span> (<span class=\"citation\">V), 8</span> ed. Zuck. <a href=\"#\" data-headword=\"בֹּוסַם\">בושם</a>.]—Pl. <span dir=\"rtl\">בַּסָּמִים</span>, <span dir=\"rtl\">בַּסָּמִין</span>, <a href=\"#\" data-headword=\"בֹּוסַם\">בַּשָּׂ׳</a>. <span class=\"citation\">Sabb. 81ᵃ</span></div>","alt":["בַּשָּׂם"]},"4463":{"h":"בִּסְמָא","r":"B01006","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּסִימָא\">בְּסִימָא</a></div>","alt":[]},"4464":{"h":"בָּסַס","r":"B01007","html":"<div class=\"sense\"> (sec. r. of b. h. <i>to tread, stamp, pile up</i>. <span class=\"citation\">Ukts. I, 5</span> stalks of eatable plants (straw &amp;c.) <span dir=\"rtl\">שבְּסָסָן בגרן</span> which the owner packed in the barn; <span class=\"citation\">Succ. 14ᵃ</span> <span dir=\"rtl\">מאי בססן</span> what does this <i>b’sasan</i> mean? R. … says <span dir=\"rtl\">ב׳ ממש</span> he really stamped them (threshed); R. … says <span dir=\"rtl\">התיר אגדן</span> he untied them (for the purpose of piling the stalks closer by treading upon them). [Pesik. Haḥod. p. 45ᵃ; <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">היו בוססות</span>, read with <span class=\"citation\">Num. R. s. 11</span> <span dir=\"rtl\">כּוֹסְסוֹת</span>, v. <a href=\"#\" data-headword=\"כָּסַס\">כָּסַס</a>.]</div><div class=\"sense\"><b>Pi. בִּיסֵּס</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"בָּסִיס\">בָּסִיס</a>) <i>to establish firmly, to found, to put on a secure basis</i>. <span class=\"citation\">Cant. R. to I, 9</span> <span dir=\"rtl\">ומי ב׳ העולם</span> and who gave the world a firm basis?; (ibid. VII, 1; Ruth. R. beg.; <span class=\"citation\">Pesik. R. s. 21</span> <span dir=\"rtl\">ביסם</span>, <a href=\"#\" data-headword=\"בִּישֵּׂם\">בישם</a> corr. acc.).—Part. pass. <span dir=\"rtl\">מְבוּסָּס</span> <i>firmly established</i>. <span class=\"citation\">Num. R. s. 15</span>; Tanḥ. B’haal. 11 <span dir=\"rtl\">כסאו מב׳ למעלן</span> (not <span dir=\"rtl\">מבוסם</span></div></div><div class=\"sense\"><b>Nithpa. נִתְבַּסֵּס</b> <div class=\"sense\"><i>to be firmly established, to rest safely</i>. <span class=\"citation\">Num. R. s. 12</span> after the Sanctuary was erected <span dir=\"rtl\">נתב׳ העולם</span> the world became firm. Ib. as soon as they made a third leg for the table (v. <span dir=\"rtl\">טרסקל</span>), <span dir=\"rtl\">נתב׳</span> it stood firm; Tanḥ. T’rum. 9. <span class=\"citation\">Gen. R. s. 66</span> <span dir=\"rtl\">נתבשם העולם</span> (corr. acc.); <span class=\"citation\">Yalk. Ps. 811</span>.</div></div>","alt":[]},"4465":{"h":"בְּסַס","r":"B01008","html":"<div class=\"sense\"> Part. pass. <a href=\"#\" data-headword=\"בְּסִיס\">בְּסִיס</a> <i>based, firm</i>. <span class=\"citation\">Targ. Cant. V, 15</span>.</div><div class=\"sense\"><b>Pa. בַּסֵּיס</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"בָּסַס\">preced.</a> Pi. <span class=\"citation\">Targ. II Chr. III, 3</span>.</div></div><div class=\"sense\"><b>Ithpa. אִתְבַּסֵּס</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"בָּסַס\">preced.</a> Nithpa. <span class=\"citation\">Targ. Cant. II, 5</span> (not <span dir=\"rtl\">אתבסם</span>).</div></div>","alt":[]},"4466":{"h":"בְּסָסִית","r":"B01009","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּסִיסַי\">בְּסִיסִית</a></div>","alt":[]},"4467":{"h":"בָּסַר I","r":"B01010","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בס</span>, v. <span dir=\"rtl\">בסס</span>) <i>to tread upon;</i> trnsf. (v. <a href=\"#\" data-headword=\"בְּעַט\">בעט</a>) <i>to contemn</i> (with <span dir=\"rtl\">על</span>); <i>to be overbearing</i> (with <a href=\"#\" data-headword=\"ב\">ב</a>). <span class=\"citation\">Ex. R. s. 42</span>, end <span dir=\"rtl\">כך היתה בוֹסֶרֶת עלי</span> so did she slight me. <span class=\"citation\">Ex. R. s. 3</span> beg.; s. 45 <span dir=\"rtl\">בּוֹסֵר הוא על וכ׳</span> he will treat his prophetic mission lightly. Tanḥ. Ekeb 1 <span dir=\"rtl\">בָּסַרְתִּי בהן</span> have I become overbearing because I observed thy commands? (Tanḥ. ed. Bub. 2 <span dir=\"rtl\">כפרתי</span>, v. note a. l.). Ib. Mikkets 10 <span dir=\"rtl\">לא תהא בוסר בשעת וכ׳</span> be not haughty in happiness, so as to refuse to pray. Ib. (ed. Bub.) Emor 29 <span dir=\"rtl\">בוסר עליהן</span>; Tanḥ. ib. 20 (some ed. <span dir=\"rtl\">בוחר</span>, corr. acc.) thinks lightly of them.—Part. pass. <span dir=\"rtl\">בָּסוּר</span>, fem. <a href=\"#\" data-headword=\"בְּסוֹרָה\">בְּסוּרָה</a> <i>contemptible</i>. Tanḥ. Sh’moth 11.</div><div class=\"sense\"><b>Pi. בִּיסֵּר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"בְּסָסִית\">same</a>. <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">וב׳ עליה</span> (some ed. <span dir=\"rtl\">וכופר</span>) and he despised it (idolatry). Tanḥ. Ekeb 1 some ed. <span dir=\"rtl\">ביסרתי</span>, v. supra.</div></div>","alt":[]},"4468":{"h":"בְּסַר","r":"B01011","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ps. LXIX, 34</span>; a. fr.</div><div class=\"sense\"><b>Pa. בַּסֵּיר  בַּסַּר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"בָּסַר I\">same</a>. <span class=\"citation\">Targ. O. Num. XV, 31</span> ed. Berl.; a. fr.; [in ed. sometimes <span dir=\"rtl\">בשר</span>].—<span class=\"citation\">Targ. I Sam. XI, 12</span> <span dir=\"rtl\">מבסר למימר</span> spoke sneeringly.—Y. Ber. II, 5ᶜ bot. <span dir=\"rtl\">בר נש דאימיה מְבַסְּרָא ליה</span> one whom his mother (Palestine) despises and his stepmother (Babylon) honors; v. <a href=\"#\" data-headword=\"אֵם\">אֵם</a>. Y. Snh. I, 19ᵃ top; Y. Ned. VI, 40ᵃ <span dir=\"rtl\">בעא מבסרתהון</span> (<span dir=\"rtl\">מבסרתון</span>; read <span dir=\"rtl\">מבסר בהון</span>) he wanted to despise them (reject their authority).</div></div>","alt":[]},"4469":{"h":"בָּסַר II","r":"B01012","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בס</span>, v. <span dir=\"rtl\">בסם</span>) <i>to begin to boil, to be in the first stage of ripening;</i> v. next w.—Denom. <a href=\"#\" data-headword=\"בֹּוסֶר\">בּוֹסֶר</a>, <a href=\"#\" data-headword=\"בְּסוֹרָה\">בְּסוֹרָה</a>.—Trnsf. (v. <a href=\"#\" data-headword=\"בָּשַׂר\">בָּשַׂר</a>) <i>to be glad</i>. <span class=\"citation\">Gen. R. s. 34</span> end (play on <span dir=\"rtl\">לב בשר</span>, <span class=\"citation\">Ezek. XXXVI, 26</span>), [read as] <span class=\"citation\">Yalk. Gen. 61</span> <span dir=\"rtl\">לב בוסר בחלקו של חבירו</span> a heart rejoicing in the good fortune of his neighbor.—V. <a href=\"#\" data-headword=\"בָּשַׂר\">בָּשַׂר</a>.</div>","alt":[]},"4470":{"h":"בְּסַר ²","r":"B01013","html":"<div class=\"sense\"><b>1)</b>  Part. <a href=\"#\" data-headword=\"בְּסִיר\">בְּסִיר</a> m., <a href=\"#\" data-headword=\"בְּסִיר\">בְּסִירָא</a> f., pl. <a href=\"#\" data-headword=\"בְּסִיר\">בְּסִירָן</a> <i>in the early stage of ripening</i>. <span class=\"citation\">Targ. Y. Ex. IX, 34</span> סערייא … בסירן Ar. (ed. <span dir=\"rtl\">סרתא … כסידא</span>, <a href=\"#\" data-headword=\"כסירא\">כסירא</a>, read <a href=\"#\" data-headword=\"בְּסִיר\">בסירא</a>; h. text <span dir=\"rtl\">אביב</span>).</div><div class=\"sense\"><b>—2)</b> <i>to be cheerful;</i> v. <a href=\"#\" data-headword=\"בְּשַׂר\">בְּשַׂר</a>.</div>","alt":[]},"4471":{"h":"בְּסַר III","r":"B01014","html":"<div class=\"sense\"><i>flesh</i>, v. <a href=\"#\" data-headword=\"בְּשַׂר\">בְּשַׂר</a>, <a href=\"#\" data-headword=\"בִּשְׂרָא\"><a href=\"#\" data-headword=\"בִּשְׂרָא\">בִּשְׂרָא</a>.</a></div>","alt":["בִּסְרָא"]},"4472":{"h":"בסרייא","r":"B01015","html":"<div class=\"sense\">, Pesik. Baḥod. p. 154ᵇ, read <span dir=\"rtl\">קיסרייא</span>.</div>","alt":[]},"4473":{"h":"בַּסְרָנוּתָא","r":"B01016","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (בסר I) <i>contempt</i>. <span class=\"citation\">Targ. Job XII, 21</span>; a. e.</div>","alt":[]},"4474":{"h":"*בִּסְתַּיָּיר","r":"B01017","html":"<div class=\"sense\"> (read <span dir=\"rtl\">בִּסְטַ׳</span>) m. (vestiarius, βεστιάριος S.) <i>the keeper of the</i> (<i>royal</i>) <i>wardrobe</i>. <span class=\"citation\">Pesik. R. s. 10</span>.</div>","alt":[]},"4475":{"h":"בִּסְתְּקָא","r":"B01018","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (reduplic. of <span dir=\"rtl\">בסק</span> = <span dir=\"rtl\">בזק</span>; cmp. Mand. <a href=\"#\" data-headword=\"עִסְקָא\">עסקא</a> = <a href=\"#\" data-headword=\"עִזְקָא\">עזקא</a>, Nöld. Mand. Gr. p. 62; Syr. <span dir=\"rtl\">ביסתא</span> = <span dir=\"rtl\">ביזתא</span>, P. Sm. 520) <i>jug, pitcher;</i> cmp. <a href=\"#\" data-headword=\"בָּזָךְ\">בָּזָךְ</a>. <span class=\"citation\">Ḥull. 49ᵇ</span></div>","alt":["*(בוס׳)"]},"4476":{"h":"בִּסְתַּרְקָא","r":"B01019","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּיסְתַּרְקָא\">בִּיסְ׳</a></div>","alt":[]},"4477":{"h":"בְּעָא","r":"B01020","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בעי\">בעי</a></div>","alt":[]},"4478":{"h":"בָּעָאתָא","r":"B01021","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּעֲתָא I\">בַּעֲתָא</a></div>","alt":[]},"4479":{"h":"בִּעְבּוּעַ","r":"B01022","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בִּעְבֵּעַ\">next w.</a>) <i>casting bubbles, bulging, bulge.</i> <span class=\"citation\">Mikv. X, 4</span> (of garments dipped in water until they are soaked through) <span dir=\"rtl\">וינוחו מבִּעְבּוּעָן</span> and cease from bulging. <span class=\"citation\">T’bul Yom II, 8</span> <span dir=\"rtl\">ב׳ שבחבית</span> (an imperfection in an earthen jug) <i>a protuberance</i></div>","alt":[]},"4480":{"h":"בִּעְבֵּעַ","r":"B01023","html":"<div class=\"sense\"> (Pilp. of <a href=\"#\" data-headword=\"בּוּעַ\">בּוּעַ</a>; cmp. <a href=\"#\" data-headword=\"בִּצְבֵּץ\">בִּצְבֵּץ</a>) </div><div class=\"sense\"><b>1)</b> <i>to cast bubbles, to form protuberances, to bulge</i>. <span class=\"citation\">Mikv. X, 4</span> <span dir=\"rtl\">עד שיְבַעְבְּעוּ</span> until they (the garments dipped in water) form bulges; v. <a href=\"#\" data-headword=\"בִּעְבּוּעַ\">preced.</a> <span class=\"citation\">Yalk. Sam. 157</span>; <span class=\"citation\">Midr. Till. to Ps. XVIII, 3</span> (read:) <span dir=\"rtl\">שהיה שמן המשחה מְבַעְבֵּעַ ויורד עליו</span> the oil of anointment came bubbling down upon him.</div><div class=\"sense\"><b>—2)</b> <i>to struggle in the water, swim</i>. <span class=\"citation\">Y. Sabb. XIII, 14ᵇ</span> top.; <span class=\"citation\">Y. Sot. III, 19ᵃ</span> top. <span dir=\"rtl\">תינוק מב׳ וכ׳</span> a child struggling in the river. <span class=\"citation\">Y. Yoma III, 41ᵃ</span> <span dir=\"rtl\">התחיל מב׳ וכ׳</span> commenced casting up bubbles from under the ship (Bab. <span class=\"citation\">ib. 38ᵃ</span> <span dir=\"rtl\">מבצבצת</span>).</div>","alt":[]},"4481":{"h":"*בַּעְבַּע","r":"B01024","html":"<div class=\"sense\">(v. <a href=\"#\" data-headword=\"בעי\">בעי</a>) <i>to ask entrance, knock at the door</i>. <span class=\"citation\">Lev. R. s. 21</span>; Pesik. Aḥare, p. 177ᵃ <span dir=\"rtl\">הוה מבעבע</span> used to knock. [Ar. reads <a href=\"#\" data-headword=\"כעכע\">כעכע</a>, quoting Lev. R. l. c. also for a Hebrew verb <span dir=\"rtl\">לכעכע</span>; Rashb. to <span class=\"citation\">Pes. 112ᵃ</span> quotes <span dir=\"rtl\">נענע</span>.]</div>","alt":[]},"4482":{"h":"בעד","r":"B01025","html":"<div class=\"sense\"> (Arab.) <i>to keep off</i>. Imper. IV <a href=\"#\" data-headword=\"אַבְעַד\">אַבְעִד</a>. <span class=\"citation\">Cant. R. to IV, 1</span> (ref. to <span dir=\"rtl\">מבעד</span> ib.) <span dir=\"rtl\">ל׳ ערבי וכ׳</span> it is Arabic; if one desires to say to one, Make room for me (or, Let me alone), he says <span dir=\"rtl\">אבעד לי</span> (some ed. <span dir=\"rtl\">מבעד</span>).</div>","alt":[]},"4483":{"h":"בָּעָה","r":"B01026","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בעי\">בעי</a></div>","alt":[]},"4484":{"h":"בָּעוּ","r":"B01027","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בעי\">בעי</a>) <i>prayer</i>. <span class=\"citation\">Targ. Jer. VII, 16</span>. <span class=\"citation\">Targ. II Sam. VII, 20</span>; a. fr.—<a href=\"#\" data-headword=\"בְּבָעוּ\">בְּבָעוּ</a> (in prayer) <i>I pray</i> (h. <a href=\"#\" data-headword=\"בִּדּוּר\">בִּי</a>, <a href=\"#\" data-headword=\"נָא I\">נָא</a>). <span class=\"citation\">Targ. Gen. XIX, 7</span>. <span class=\"citation\">Ib. XLIV, 18</span>; a. v. fr. [<span class=\"citation\">Targ. Ps. XLIII, 4</span>, v. <a href=\"#\" data-headword=\"בּוּעֲתָא II\"><span dir=\"rtl\">בּוּעֲתָא</span> II</a>.]</div>","alt":["בָּעוּתָא"]},"4485":{"h":"בְּעוֹד","r":"B01028","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"עוֹד\">עוֹד</a></div>","alt":[]},"4486":{"h":"בְּעוֹט","r":"B01029","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּעַט\">בְּעַט</a>) </div><div class=\"sense\"><b>1)</b> <i>treading grapes</i>, or <i>trodden grapes</i>. <span class=\"citation\">Targ. Is. X, 33</span>; <span class=\"citation\">Targ. Joel IV, 13</span> (ed. <a href=\"#\" data-headword=\"בְּעוֹט\">בָּעוּט</a>); <span class=\"citation\">Targ. Is. LXIII, 3</span> <a href=\"#\" data-headword=\"בִּיעוּט\">בִּיעוּט</a>.</div><div class=\"sense\"><b>—2)</b> <i>a kick with the foot</i>. <span class=\"citation\">Y. Taan. IV, 68ᵈ</span> bot. <span dir=\"rtl\">יהב ליה חד ב׳ וכ׳</span> he gave him one kick and killed him; <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">חד בעיטא ברגליה</span>.</div>","alt":[]},"4487":{"h":"בָּעוּר","r":"B01030","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּעַר I\">בער</a>) <i>torch, fire</i> (h. <a href=\"#\" data-headword=\"לַפִּיד\">לַפִּיד</a>). <span class=\"citation\">Targ. O. Gen. XV, 17</span> (Y. <a href=\"#\" data-headword=\"מַבְעִיר\">מבעיר</a>); a. e.—Pl. <span dir=\"rtl\">בָּעוּרִין</span>, <span dir=\"rtl\">בְּעוּרַיָּא</span>. <span class=\"citation\">Targ. Nah. II, 5</span> <span dir=\"rtl\">בְּעוּ׳</span> (ed. Vien.). <span class=\"citation\">Targ. Job XLI, 11</span>; a. e.—<span class=\"citation\">B. Mets. 85ᵇ</span> <span dir=\"rtl\">ב׳ דאשא</span> (Ms. M. <span dir=\"rtl\">דנור</span>).</div>","alt":["בָּעוֹרָא","(בָּעֵיר)"]},"4488":{"h":"בָּעוּתָא","r":"B01031","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּעוּ\">בָּ֗עוּ</a>.</div>","alt":[]},"4489":{"h":"בָּעַט I","r":"B01032","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בע</span>, v. <a href=\"#\" data-headword=\"בּוּעַ\">בוע</a>) <i>to swell, bulge.</i> <span class=\"citation\">Midd. III, 8</span> <span dir=\"rtl\">שלא יִבְעֲטוּ</span> marg. vers. (or <span dir=\"rtl\">יִבָּעֲטוּ</span> Nif.; text <span dir=\"rtl\">יבעט</span> sing.) that the walls should not bulge.</div>","alt":[]},"4490":{"h":"בָּעַט II","r":"B01033","html":"<div class=\"sense\"><i>to trample, strike, kick</i>. <span class=\"citation\">Y. Yoma VIII, 45ᵇ</span> top <span dir=\"rtl\">בְּעָטָתוֹ פרדה</span> a mule kicked him. <span class=\"citation\">Ex. R. s. 30</span> <span dir=\"rtl\">ב׳ בפילקי</span> knocked against the prison door (burst it open). <span class=\"citation\">Ab. Zar. IV, 8</span> <span dir=\"rtl\">גת בְּעוּטָה</span> a wine press packed with stamped grapes.—Trnsf. (with <a href=\"#\" data-headword=\"ב\">ב</a>) <i>to resist, reject</i>. <span class=\"citation\">Sabb. 104ᵃ</span>, v. <a href=\"#\" data-headword=\"אח\">אח&quot;ס</a>.</div><div class=\"sense\"><b>Pi. בִּיעֵט</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"בָּעַט I\">same</a>. <span class=\"citation\">B. Kam. II, 1</span>. <span dir=\"rtl\">היתה מְבָעֶטֶת</span> if the animal kicked. <span class=\"citation\">Ber. 32ᵃ</span>; a. e.—Trnsf. <i>to kick against, rebel, be contumacious</i>. <span class=\"citation\">Sot. 22ᵃ</span>. Y. Ber. IX, 14ᵇ bot., a. e. <span dir=\"rtl\">מְבָעֵט בייסורין</span> bearing suffering with contumacy (instead of showing repentance). <span class=\"citation\">Pesik. R. s. 47</span>; <span class=\"citation\">Yalk. Job 908</span> <span dir=\"rtl\">התחיל מב׳</span> (sub. <span dir=\"rtl\">בייסורין</span>) began to be contumacious (challenging the Lord).</div></div>","alt":[]},"4491":{"h":"בְּעַט","r":"B01034","html":"<div class=\"sense\"><span class=\"citation\">Targ. Hos. IV, 16</span>; a. e.—Y. Sabb. VII, 11ᵃ bot.; <span class=\"citation\">Y. Shek. III, 47ᶜ</span> <span dir=\"rtl\">ב׳ ביה</span> rejected his authority.</div><div class=\"sense\"><b>Pa. בַּעֵט  בַּעֵיט</b> <div class=\"sense\"><i>to tread</i> (<i>grapes</i>). <span class=\"citation\">Targ. Lam. I, 15</span>.</div></div><div class=\"sense\"><b>Ithpe. אִתְבְּעִיט</b> <div class=\"sense\"><i>to be trodden</i>. <span class=\"citation\">Targ. Joel IV, 13</span>; <span class=\"citation\">Targ. Is. LXIII, 3</span>; a. e.</div></div>","alt":["בְּעֵיט"]},"4492":{"h":"בַּעֲטָן","r":"B01035","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּעַט\">preced.</a>) <i>habitual kicker, butting</i>. <span class=\"citation\">B. Mets. 80ᵃ</span>; <span class=\"citation\">Tosef. B. Bath. IV, 6</span>.</div>","alt":["בַּעֲטָנִית"]},"4493":{"h":"בעי","r":"B01036","html":"<div class=\"sense\"> <a href=\"#\" data-headword=\"א\">א</a>, a) <i>to enter into, split;</i> b) <i>to be empty, bare</i>). Part. <span dir=\"rtl\">בּוֹעֶה</span>, v. infra.</div><div class=\"sense\"><b>Hif. הִבְעָה</b> <div class=\"sense\"><i>to lay bare, destroy the crop</i>. <span class=\"citation\">B. Kam. I, 1</span> <span dir=\"rtl\">המַבְעֶה</span> damaging the crop (ref. to <span class=\"citation\">Ex. XXII, 4</span>). Ib. 3ᵇ Rab says <span dir=\"rtl\">מבעה זה אדם</span> the damaging force in the Mishnah means that of a human being (ransacking, searching); for we read (<span class=\"citation\">Is. XXI, 12</span>) <span dir=\"rtl\">אם תבעיון בעיו</span> if ye desire to enter &amp;c. (where <span dir=\"rtl\">בעה</span> refers to human action); Samuel says, <span dir=\"rtl\">מבעה זה השן</span> the <i>mabeh</i> of the Mishnah refers to the tooth, i.e. to an animal’s eating up the crop, for it says (<span class=\"citation\">Ob. I, 6</span>) <span dir=\"rtl\">נבעו מצפניו</span> its hidden treasures were laid bare (made empty,—which refers to eating up). Ib. (argument against Samuel) <span dir=\"rtl\">מי קתני נִבְעָה</span> the Mishnah does not use the Nifal (which may mean <i>eaten up</i>); (argument against Rab) <span dir=\"rtl\">מי קתני בּוֹעֶה</span> the Mishnah does not use the Kal (which may refer to human action) but the Hifil “to cause damage”—through the animal.—Tosef. ib. IX, 1.</div></div>","alt":["בָּעָה"]},"4494":{"h":"בְּעֵי I","r":"B01037","html":"<div class=\"sense\">(v. <a href=\"#\" data-headword=\"בעי\">preced.</a>; cmp. <span dir=\"rtl\">בין</span>) </div><div class=\"sense\"><b>1)</b> <i>to search, inquire, ask, examine</i>. <span class=\"citation\">Targ. Jud. VI, 29</span> (h. text <a href=\"#\" data-headword=\"בָּקַשׁ\">בקש</a>); a. fr.—<span class=\"citation\">Ber. 2ᵇ</span> <span dir=\"rtl\">ובעו לה מבעיא האי וכ׳</span> and put it as a question (not as an argument), Does this <i>uba hash-shemesh</i> mean &amp;c.? (opposed to preceding <span dir=\"rtl\">וממאי דהאי וכ׳</span> how can it be proven that &amp;c.). <span class=\"citation\">Y. Ḥall. I, 57ᵇ</span> <span dir=\"rtl\">רבנן … בעיין</span> the Rabbis of … asked. <span class=\"citation\">B. Kam. 33ᵃ</span> בעא … מרב וכ׳ R. asked R. N.; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>to ask, pray</i>, frequ. <span dir=\"rtl\">ב׳ רחמין</span> <i>to ask for mercy, pray</i>. <span class=\"citation\">Targ. Y. Num. XII, 13</span>; a. fr.—<span class=\"citation\">Ber. 8ᵃ</span> <span dir=\"rtl\">לבעי אינש רחמי</span> man should pray &amp;c., v. <a href=\"#\" data-headword=\"זִיבּוּלָא\">זיבולא</a>. <span class=\"citation\">Ib. 10ᵃ</span> <span dir=\"rtl\">בְּעִי רחמי עלויהו וכ׳</span> pray thou for them that they may repent; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to ask, want, desire; to require</i>. <span class=\"citation\">Targ. Ex. II, 15</span>; a. fr.—<span class=\"citation\">Pes. 9ᵃ</span> <span dir=\"rtl\">ובָעֵי בדיקה</span> and it (the house) requires searching over again. <span class=\"citation\">Keth. 39ᵇ</span> לא בעינא לך I do not want thee. <span class=\"citation\">B. Kam. 102ᵇ</span> לא יקרייכו בעינא וכ׳ I want neither your honor nor your disrespect; a. fr.—<span class=\"citation\">Pes. 2ᵃ</span> בעו שבוחי <i>must</i> give praise.—<span dir=\"rtl\">אי בעית אימא</span>, usu. <span dir=\"rtl\">איבעית אימא</span>, v. <a href=\"#\" data-headword=\"אִיבָּעִית\">אִיבָּעִית</a>. [<span class=\"citation\">Y. Yeb. XII, 13ᵃ</span> top <span dir=\"rtl\">בְּעֵא תתן לנו</span>, please, give us.]</div><div class=\"sense\"><b>—4)</b>  (ellipt.) <i>to beg leave to say; to remark, assert</i>. <span class=\"citation\">Y. Ber. I, 2ᵇ</span> top. <span class=\"citation\">Y. Peah II, beg. 16ᵈ</span>; a. fr.</div><div class=\"sense\"><b>Ithpe. אִתְבְּעִי</b> <div class=\"sense\"><b>1)</b> <i>to be searched for, to be wanted</i>. <span class=\"citation\">Targ. Jer. L, 20</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be urged, hurried</i>. <span class=\"citation\">Targ. I Sam. XXIII, 26</span>. <span class=\"citation\">Targ. II Sam. IV, 4</span> <span dir=\"rtl\">בְּאִתְבָּעֲיוּתָהּ</span> when she was hurried; v. <a href=\"#\" data-headword=\"בְּעַע\">בְּעַע</a>.</div></div><div class=\"sense\"><b>Ithpa. אִיבָּעֵי</b> <div class=\"sense\"><b>1)</b> <i>to be asked</i>. <span class=\"citation\">Pes. 4ᵇ</span>, a. v. fr. <span dir=\"rtl\">אִיבָּעְיָא להו</span> it was asked by them (the scholars), i.e. the argument came up.</div><div class=\"sense\"><b>—2)</b> <i>to be required; it ought to</i>. Ib. 7ᵇ <span dir=\"rtl\">יצא בו מיבעי ליה</span> it ought to read <i>yatsa bo</i> (he <i>has</i> done his duty). Ib. 15ᵃ <span dir=\"rtl\">מדבריו מ׳ ליה</span> it ought to be <i>midd’barav</i> (not <i>middibrehem</i>); a. fr.—<span class=\"citation\">B. Kam. 21ᵇ</span> <span dir=\"rtl\">א׳ ליה לאסוקי דעתא</span> he ought to have borne in mind; a. fr.—לא מיבעיא <i>there is no question</i>. <span dir=\"rtl\">לא מ׳ … אלא אפילו</span> there is no question as to …, but even …; <i>not only … but</i>. <span class=\"citation\">Pes. 4ᵇ</span> <span dir=\"rtl\">לא מ׳ באתרא … אלא וכ׳</span> not only in a place where they pay no wages for searching, but do it themselves, (is there no cause for withdrawing from the agreement,) because a man likes to perform a religious duty: but even in a place where they pay wages, (there is no cause &amp;c.,) for a man likes &amp;c. <span class=\"citation\">B. Kam. 54ᵇ</span> <span dir=\"rtl\">לא מ׳ קאמר לא מ׳ שור וכ׳</span> the Mishnah states a case of ‘not only’; not only for an ox … is he responsible, but even &amp;c.; a. v. fr.—מִיבָּעְיָא <i>is there any question?;</i> v. <a href=\"#\" data-headword=\"הַשְׁתָּא\">הַשְׁתָּא</a>.</div></div><div class=\"sense\"><b>Af. אַבְעֵי</b> <div class=\"sense\"><i>to let burst forth</i>, v. <a href=\"#\" data-headword=\"יְעָא\">יְעָא</a> a. <a href=\"#\" data-headword=\"נְבַע\"><a href=\"#\" data-headword=\"נְבַע\">נְבַע</a>.</a></div></div>","alt":["בְּעָא"]},"4495":{"h":"בְּעֵי II","r":"B01038","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בעי\">בעי</a>, <a href=\"#\" data-headword=\"בָּעָה\"><a href=\"#\" data-headword=\"בָּעָה\">בָּעָה</a>)</a><i>to open wide</i> (the mouth), <i>to yawn</i> (of leopards). Targ. II Esth. I, 2 <span dir=\"rtl\">נמרין בעיין</span>.</div>","alt":[]},"4496":{"h":"בַּעְיָא","r":"B01039","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  (<a href=\"#\" data-headword=\"בְּעֵי II\">preced.</a>) <i>yawn, gap</i>. Constr. <a href=\"#\" data-headword=\"בְּעֵי I\">בְּעֵי</a>. <span dir=\"rtl\">ב׳ לבא</span> <i>greed</i>. <span class=\"citation\">Targ. Prov. XXI, 4</span> (h. text <span dir=\"rtl\">רחב לב</span>).</div><div class=\"sense\"><b>—2)</b>  (בעי I) <i>question.</i> Pl. <span dir=\"rtl\">בַּעְיֵי</span>. <span class=\"citation\">Snh. 106ᵇ</span> <span dir=\"rtl\">ד׳ מאות ב׳</span> four hundred questions. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">רבותא למבעי ב׳</span> is there any greatness in asking questions?</div>","alt":[]},"4497":{"h":"*בָּעְיָא","r":"B01040","html":"<div class=\"sense\"> (<span dir=\"rtl\">מעין</span>) pr. n. m. <i>Baya</i> (Mayan), name of a publican. <span class=\"citation\">Snh. 44ᵇ</span> <span dir=\"rtl\">ב׳ מוכסא</span> (not <a href=\"#\" data-headword=\"מִכְסָא\">מיכ׳</a>); Y. Ḥag. II, 77ᵈ <span dir=\"rtl\">מ׳ מיכס</span>.</div>","alt":[]},"4498":{"h":"בָּעְיָיא","r":"B01041","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (part. of <a href=\"#\" data-headword=\"בעי\">בעי</a>) <i>desirous</i>. <span class=\"citation\">Y. Taan. I, 64ᵇ</span> bot. <span dir=\"rtl\">אנא ב׳ וכ׳</span> I want to see what I can do to relieve him.—Pl. m. <span dir=\"rtl\">בָּעְיֵי</span>. Ib.ᵃ top <span dir=\"rtl\">אימת דאתון בעיי הוא בָעֵי</span> whenever ye are desirous (that he should come), he is willing to.</div>","alt":[]},"4499":{"h":"בֵּעַיָּיא","r":"B01042","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּיעָא\">בֵּיעָא</a></div>","alt":[]},"4500":{"h":"בְּעֵיט","r":"B01043","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּעַט\">בְּעַט</a></div>","alt":[]},"4501":{"h":"בְּעִיטָא","r":"B01044","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּעוֹט\">בְּעוֹט</a></div>","alt":[]},"4502":{"h":"בְּעִיטָה","r":"B01045","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּעַט\">בעט</a>) </div><div class=\"sense\"><b>1)</b> <i>kicking</i>. <span class=\"citation\">Y. B. Kam. I, beg. 2ᵃ</span> (of animals). Bab. <span class=\"citation\">B. Kam. 27ᵇ</span> <span dir=\"rtl\">לב׳ חמש</span> for kicking with one’s foot &amp;c. </div><div class=\"sense\"><b>2)</b> <i>beating</i> (with one’s fist). <span class=\"citation\">Men. VI, 5</span> (<span class=\"citation\">76ᵃ</span>) <span dir=\"rtl\">שיפה וב׳ בחטין</span> rubbing and beating refer to the preparation of the wheat of the meat-offering (prior to grinding); R. Y. says <span dir=\"rtl\">בבצק</span> (Mish. <a href=\"#\" data-headword=\"אַף I\">אף</a> incorr.) beating refers to the dough. Ib. Ib. Var. <span dir=\"rtl\">שיפה בחיטים וב׳ בבצק</span>; Tosef. ib. VIII, 14.</div>","alt":[]},"4503":{"h":"בְּעֵיל","r":"B01046","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּעַל\">בְּעַל</a> a. <a href=\"#\" data-headword=\"בַּעֲלָא\"><a href=\"#\" data-headword=\"בַּעֲלָא\">בַּעֲלָא</a>.</a></div>","alt":[]},"4504":{"h":"בְּעִילָה","r":"B01047","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּעַל\">בָּעַל</a>) <i>sexual intercourse</i>. <span class=\"citation\">Keth. 3ᵃ</span> <span dir=\"rtl\">שויוה רבנן לבְעִילָתוֹ בְּעִילַת זנות</span> the Rabbis (in this case) have declared his coition (by which he wanted to establish marriage), a mere act of prostitution (annulled his marriage). <span class=\"citation\">Ib. 73ᵃ</span>, a. e. <span dir=\"rtl\">אין אדם עושה בעילתו בעילת זנות</span> the presumption is that nobody wants to make his intercourse with a woman one of prostitution (but wants to make her his wife thereby).—<span class=\"citation\">Ib. 4ᵃ</span> <span dir=\"rtl\">בעילת מצוה</span> the marital duty, i.e. first coition; frequ. <span dir=\"rtl\">ב׳ ראשונה</span>. Y. Macc. II, 31ᵈ; a. fr.—Pl. <span dir=\"rtl\">בְּעִילוֹת</span>. <span class=\"citation\">Sabb. 72ᵃ</span>; a. fr.</div>","alt":[]},"4505":{"h":"בְּעִיץ I","r":"B01048","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"בַּעֲצָא\">בַּעֲצָא</a></div>","alt":[]},"4506":{"h":"*בְּעִיץ II","r":"B01049","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (part. pass. of a verb <span dir=\"rtl\">בעץ</span>, denom. of <a href=\"#\" data-headword=\"בַּעֲצָא\">בעצא</a>) <i>tinned, wrapt in tin-foil</i>. <span class=\"citation\">Targ. Jer. XXXII, 11</span> (a. 14, in some ed.) <span dir=\"rtl\">כתיב ב׳ וחתים</span> written, wrapt in tinfoil and tied up (v. <span dir=\"rtl\">חתם</span>) with a seal, opp. to <span dir=\"rtl\">שטרא פתיחא</span>.</div>","alt":[]},"4507":{"h":"בְּעֵיר","r":"B01050","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּעַר I\">בְּעַר</a></div>","alt":[]},"4508":{"h":"בְּעִיר","r":"B01051","html":"<div class=\"sense\">c. (b. h. <a href=\"#\" data-headword=\"בְּעִיר\">בְּעִיר</a>; <a href=\"#\" data-headword=\"בְּעַר I\">בער</a>; cmp. also <a href=\"#\" data-headword=\"בָּעָה\">בָּעָה</a>) <i>grazing animal, cattle</i>. <span class=\"citation\">Targ. Gen. I, 24</span> sq.; a. fr.—<span class=\"citation\">Y. B. Mets. II, 8ᶜ</span> bot.; <span class=\"citation\">Lev. R. s. 27</span>, a. e. <span dir=\"rtl\">ב׳ דקיקא</span> <i>small cattle;</i> v. <a href=\"#\" data-headword=\"בְּהֵמָה\">בְּהֵמָה</a>.—Pesik. B’shall. p. 93ᵃ <span dir=\"rtl\">אתקן לי ב׳</span> get an animal ready for me (for travel). <span class=\"citation\">Snh. 105ᵃ</span> (in Hebr. dict., play on <a href=\"#\" data-headword=\"בָּעוּר\">בְּעוֹר</a>).</div>","alt":["בְּעִירָא"]},"4509":{"h":"בְּעֵית","r":"B01052","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּעֵת\">בְּעֵת</a></div>","alt":[]},"4510":{"h":"בָּעַל","r":"B01053","html":"<div class=\"sense\"> , v. <a href=\"#\" data-headword=\"בָּעָה\">בָּעָה</a>, <i>to enter into, take possession</i>) [in b. h. <i>to be master, protect;</i>] <i>to have sexual intercourse</i> (both legal or illicit), <i>to embrace a woman</i>. <span class=\"citation\">Kidd. 9ᵇ</span> וּבְעָלָהּ מלמד וכ׳ ‘and he embraced her’ (<span class=\"citation\">Deut. XXIV, 1</span>), this intimates that woman can be acquired as wife by intercourse, v. <a href=\"#\" data-headword=\"בִּיָּא\">בִּיאָה</a>.—בּוֹעֵל <i>lover, adulterer</i>, contrad. to <a href=\"#\" data-headword=\"בַּעַל\">בַּעַל</a> <i>husband</i>. <span class=\"citation\">Sot. V, 1</span>, a. fr. <span dir=\"rtl\">כשם שאסורה לַבַּעַל … לַבּוֹעֵל</span> as well as the woman suspected of adultery is forbidden to her husband (who must separate himself from her), so is she forbidden to the lover (who cannot marry her after leaving her husband). <span class=\"citation\">Yeb. 103ᵃ</span> <span dir=\"rtl\">שבע בעילות ב׳ וכ׳</span> that wicked man had seven sexual connections &amp;c.; a. fr.—Part. pass. f. <a href=\"#\" data-headword=\"בְּתוּלָה\">בְּעוּלָה</a> <i>one no longer a virgin</i>, opp. to <a href=\"#\" data-headword=\"בְּתוּלָה\">בתולה</a>; <i>married woman</i>, opp. to <span dir=\"rtl\">ארוסה</span>, v. <a href=\"#\" data-headword=\"אָרַס\">אָרַס</a>. <span class=\"citation\">Keth. 10ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">בְּעוּלוֹת</span>. <span class=\"citation\">Y. Kidd. I, 58ᵇ</span> bot.; a. fr.</div><div class=\"sense\"><b>Nif. נִבְעֲלָה</b> <div class=\"sense\"><i>she had intercourse</i>. <span class=\"citation\">Keth. 5ᵃ</span> <span dir=\"rtl\">נישאת … ונִבְעֶלֶת וכ׳</span> is married on the fourth day and embraced in the night of the fifth day of the week. <span class=\"citation\">Ib. 3ᵇ</span> <span dir=\"rtl\">תִּיבָּעֵל לטפסר וכ׳</span> must first be surrendered to the (Roman) officer (jus primæ noctis); a. fr.—Masc. <span dir=\"rtl\">נִבְעַל</span> (of the hermaphrodite). <span class=\"citation\">Tosef. Bicc. II, 5</span>; Y. Yeb. VIII, 9ᵈ bot.</div></div>","alt":[]},"4511":{"h":"בְּעַל","r":"B01054","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Deut. XXI, 13</span>; a. fr.—<span class=\"citation\">Keth. 6ᵇ</span> <span dir=\"rtl\">דבעי למִיבְעַל</span> because he is anxious to perform his marital duty. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">דטריד דלא בעיל</span> he is excited because he has not &amp;c.; a. fr.</div><div class=\"sense\"><b>Pa. בַּעֵל</b> <div class=\"sense\">, part. pass. f. <span dir=\"rtl\">מְבַעֲלָא</span> <i>married, having had intercourse</i>. <span class=\"citation\">Targ. Ruth I, 12</span>; a. e.</div></div><div class=\"sense\"><b>Ithpe. אִיבְּעֲלָא</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"בָּעַל\">preced.</a> Nif. <span class=\"citation\">Yoma 19ᵇ</span> <span dir=\"rtl\">ואִבְּעוּל כמה וכ׳</span>, (Ms. M. <span dir=\"rtl\">ואיבעיל</span>) and how many virgins have been seduced (to-day) in Nahardea!</div></div>","alt":["בְּעֵיל"]},"4512":{"h":"בַּעַל","r":"B01055","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"בְּעַל\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>husband</i>. <span class=\"citation\">Kidd. I, 1</span> and she becomes her own master <span dir=\"rtl\">בגט ובמיתת הב׳</span> through a letter of divorce or on the husband’s death; a. v. fr.</div><div class=\"sense\"><b>—2)</b> <i>the idol Baal</i>. <span class=\"citation\">Y. Ab. Zar. III, 43ᵃ</span> bot. <span dir=\"rtl\">ב׳ ראש גוייה הוה וכ׳</span> the Baal was the phallus and had the shape of a bean [read <span dir=\"rtl\">וכאפון</span>].</div><div class=\"sense\"><b>—3)</b>  [<i>the fructifier</i>,] <i>rain</i> (v. <span class=\"citation\">Taan. 6ᵇ</span>; cmp. <span class=\"citation\">Is. LV, 10</span>). <a href=\"#\" data-headword=\"פַּגֵּי\">בֵּית בַּ׳</a> <i>a field sufficiently watered by rain</i> and requiring no artificial irrigation. <span class=\"citation\">Tosef. M. Kat. I, 1</span> <span dir=\"rtl\"><span dir=\"rtl\">שדה</span> (<span dir=\"rtl\">בית</span>) <span dir=\"rtl\">הב׳</span></span>. <span class=\"citation\">B. Bath. III, 1</span>. <span class=\"citation\">Tosef. Succ. II, 7</span> <span dir=\"rtl\">ערבה של ב׳</span> (sub. <span dir=\"rtl\">בית</span>) a willow in a naturally watered field. Ib. <span class=\"citation\">Shebi. II, 4</span> <span dir=\"rtl\">בשל ב׳</span> (= <span dir=\"rtl\">בשדה של ב׳</span>), opp. <span dir=\"rtl\">של שוקי</span>. <span class=\"citation\">Num. R. s. 16</span> the Egyptian gods <span dir=\"rtl\">של שקר הם</span> (read <a href=\"#\" data-headword=\"שקי\">שקי</a>) are gods of artificial drainage, but those of Canaan <span dir=\"rtl\">של ב׳ הם</span> are gods of rain; (Tanḥ. Sh’laḥ 13, through misunderstanding, <span dir=\"rtl\">שקר … בעליכח</span>.</div><div class=\"sense\"><b>—4)</b>  (mostly in compounds) <i>owner of, master of, possessed of, given to</i> &amp;c.; e.g. <span dir=\"rtl\">ב׳ אבידה</span> owner of a lost object; <span dir=\"rtl\">ב׳ אגדה</span> master of Agadah, lecturer; <span dir=\"rtl\">ב׳ דין</span> opponent in court; v. infra. <span class=\"citation\">Pes. 86ᵇ</span> ב׳ השם אני I am so named.—Pl. <span dir=\"rtl\">בְּעָלִים</span>, <span dir=\"rtl\">בְּעָלִין</span> <i>owners;</i> mostly as sing. <i>owner</i>. <span class=\"citation\">B. Mets. VIII, 1</span>; a. fr. [<span class=\"citation\">Y. Dem. III, 23ᵇ</span> bot. <span dir=\"rtl\">לבלעין</span>, read <span dir=\"rtl\">לבעלין</span>.]</div><div class=\"sense\"><b>Compounds: . ב׳ מחשבות</b> <div class=\"sense\"><i>He who knows man’s thoughts</i>. <span class=\"citation\">Snh. 19ᵇ</span>.—<span class=\"citation\">Ib.</span> <span dir=\"rtl\">בעלי מ׳</span> <i>those entertaining considerations</i> (of fear), <i>hesitating to do justice</i>.—ב׳ שיבה <i>gray-haired</i>. <span class=\"citation\">Ned. III, 8</span>.—ב׳ תשובה <i>repentant sinner</i>. <span class=\"citation\">Succ. 53ᵃ</span>; a. fr.—ב׳ תשובות <i>a man of many objections or excuses</i>. <span class=\"citation\">Gen. R. s. 20</span> beg.—[For other compounds, not self-evident, see the respective determinants.]</div></div>","alt":[]},"4513":{"h":"בַּעֲלָא","r":"B01056","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"בְּעֵיל\">בְּעֵיל</a>, <a href=\"#\" data-headword=\"בְּעַל\">בְּעַל</a> ch. same. </div><div class=\"sense\"><b>1)</b> <i>husband</i>. <span class=\"citation\">Targ. O. Ex. XXI, 3</span>; a. fr.—<span class=\"citation\">Taan. 6ᵇ</span> <span dir=\"rtl\">מטרא ב׳ וכ׳</span> the rain is the husband (fructifier) of the field; v. <a href=\"#\" data-headword=\"בַּעַל\">preced.</a> 3).</div><div class=\"sense\"><b>—2)</b> <i>Baal</i>. <span class=\"citation\">Targ. Jud. VI, 25</span>; a. e.—Pl. <span dir=\"rtl\">בַּעֲלַיָּא</span>. <span class=\"citation\">Ib. II, 11</span>; a. fr.</div>","alt":[]},"4514":{"h":"בַּעֲלָה","r":"B01057","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בַּעֲלָא\">preced.</a>) <i>mistress, owner</i> &amp;c. <span class=\"citation\">Gen. R. s. 52</span> (rendering <span dir=\"rtl\">בְּעֻלַת</span>, <span class=\"citation\">Gen. XX, 3</span>, as though <span dir=\"rtl\">בּעֲלַת</span>) <span dir=\"rtl\">מרתא דבעלה</span> her husband’s mistress.—Compounds are mostly self-evident, e.g. <span dir=\"rtl\">בעלת הגט</span> the woman receiving the letter of divorce;—<span dir=\"rtl\">ב׳ איברים</span> an animal of large build. <span class=\"citation\">Ber. 32ᵃ</span>; v. <a href=\"#\" data-headword=\"בַּעַל\">בַּעַל</a>.</div>","alt":[]},"4515":{"h":"בְּעַע","r":"B01058","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בָּעָה\">בָּעָה</a>; cmp. <span dir=\"rtl\">בהל</span>) <i>to be excited.</i> <i>—Af</i>. <a href=\"#\" data-headword=\"נְבַע\">אַבַּע</a> <i>to hurry</i>. <span class=\"citation\">Targ. I Kings XXII, 9</span> א׳ מיכיה Ar. (ed. <span dir=\"rtl\">תבע</span>, h. text <a href=\"#\" data-headword=\"מְהֵרָה\">מהרה</a>) bring … quickly. <span class=\"citation\">Targ. Ezek. XXIV, 5</span>.—Part. pass. <a href=\"#\" data-headword=\"מַבַּע\">מַבַּע</a>, (<a href=\"#\" data-headword=\"מַבַּע\">מִבְ׳</a>) <a href=\"#\" data-headword=\"מַבַּע\">מַבְּעָא</a> <i>quick</i>. <span class=\"citation\">Targ. Deut. XXXII, 35</span>.—Pl. <span dir=\"rtl\">מַבְּעִין</span>. <span class=\"citation\">Targ. Num. XXXII, 17</span>.</div><div class=\"sense\"><b>Ittaf. אִתַּבַּע</b> <div class=\"sense\"><i>to be in a hurry, be anxious</i>. <span class=\"citation\">Targ. Ps. XXXI, 23</span> באִתַּבָּעוּתִי Ms. (ed. <span dir=\"rtl\">באִתְבָּעוּתִי</span>). <span class=\"citation\">Targ. II Kings VII, 15</span>; <span class=\"citation\">Targ. II Sam. IV, 4</span>, v. <a href=\"#\" data-headword=\"בְּעֵי I\"><span dir=\"rtl\">בְּעֵי</span> I</a>.</div></div>","alt":[]},"4516":{"h":"*בְּעַץ","r":"B01059","html":"<div class=\"sense\"><b>1)</b>  (dialectic for (dialectic for <a href=\"#\" data-headword=\"בְּעַט\">בְּעַט</a>) <i>to tread</i>. <span class=\"citation\">Targ. Ps. XCI, 13</span> <span dir=\"rtl\">תבעוץ</span> some ed. (oth. <span dir=\"rtl\">תבעוט</span>).</div><div class=\"sense\"><b>—2)</b> <i>to wrap in tin</i>, v. <a href=\"#\" data-headword=\"בַּעֲצָא\">בְּעִיץ</a>.</div>","alt":[]},"4517":{"h":"בַּעַץ","r":"B01060","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"בּוּץ\">בּוּץ</a>, v. <a href=\"#\" data-headword=\"*עֲבַץ I\">עבץ</a> a. <a href=\"#\" data-headword=\"אֲבָצָא\"><a href=\"#\" data-headword=\"אֲבָצָא\">אבצא</a>)</a><i>tin, plumbum album.</i> <span class=\"citation\">Kel. XXX, 3</span> <span dir=\"rtl\">עשאו בין בב׳</span> if he mended it either with &amp;c. <span class=\"citation\">B. Bath. 89ᵇ</span> (diff. fr. <a href=\"#\" data-headword=\"אבר\">אבר</a>, a. <a href=\"#\" data-headword=\"גִּיסְטְרָא\">גיסטרא</a>, cassiterum, v. Sm. Ant. s. v. Plumbum). <span class=\"citation\">Men. 28ᵇ</span>; a. fr.</div>","alt":[]},"4518":{"h":"בַּעֲצָא","r":"B01061","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ezek. XXII, 18</span>. <span class=\"citation\">Targ. Y. Num. XXXI, 22</span> Ar. a. Levita (ed. <a href=\"#\" data-headword=\"קַסִּיטְרָא\">קסיטרא</a>, O. <a href=\"#\" data-headword=\"אֲבָצָא\">אבצא</a>).</div>","alt":["בְּעִיץ"]},"4519":{"h":"בָּעַר","r":"B01062","html":"<div class=\"sense\"> , v. <a href=\"#\" data-headword=\"בָּעָה\">בָּעָה</a>; cmp. <a href=\"#\" data-headword=\"בָּאַר\">בָּאֵר</a>) [<i>to clear</i>,] </div><div class=\"sense\"><b>1)</b> <i>to burn</i> (act. a. neut.). <span class=\"citation\">Ex. R. s. 2</span> <span dir=\"rtl\">אש בּוֹעֶרֶת</span> burning fire. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כשם שהסנה בּוֹעֵר וכ׳</span> as the bush is burning &amp;c. [<span class=\"citation\">Num. R. s. 9</span>, end <span dir=\"rtl\">לבוערים בע&quot;ז</span>, read <span dir=\"rtl\">לבוסרים</span>, v. <a href=\"#\" data-headword=\"בָּסַר I\"><span dir=\"rtl\">בָּסַר</span> I</a>, Var. <span dir=\"rtl\">לכיפרים</span>.]</div><div class=\"sense\"><b>—2)</b> <i>to be empty</i>. Denom. <a href=\"#\" data-headword=\"בְּעַר I\">בַּעַר</a>.</div><div class=\"sense\"><b>—3)</b> <i>to eat up</i>. Denom. <a href=\"#\" data-headword=\"בְּעִיר\">בְּעִיר</a>.</div><div class=\"sense\"><b>Pi. בִּיעֵר</b> <div class=\"sense\"><b>1)</b> <i>to clear, remove</i> (out of existence or out of possession). <span class=\"citation\">Pes. 6ᵃ</span> <span dir=\"rtl\">זקוק לבָעֵר</span> is bound to remove (the leaven by burning or otherwise); a. fr.—<span class=\"citation\">Shebi. VII, 7</span> <span dir=\"rtl\">חייב לב׳</span> is bound to remove (dispose of the fruits of the Sabbath year in due time). [<span class=\"citation\">Num. R. s. 9</span> (p. 230ᵇ ed. Amst.) <span dir=\"rtl\">מבערים את העון</span>, read with <span class=\"citation\">Yalk. Num. 708</span>, <span class=\"citation\">Sifré Num. 11</span> <span dir=\"rtl\">מערערין</span>; oth. vers. <span dir=\"rtl\">מבררין</span>, v. <a href=\"#\" data-headword=\"בָּרַר\">בָּרַר</a>.] </div><div class=\"sense\"><b>2)</b> <i>to clear, eat up</i>. <span class=\"citation\">B. Kam. 2ᵇ</span> וּבִעֵר זו השן ‘and it clears’ (<span class=\"citation\">Ex. XXII, 4</span>) this refers to injury by the tooth (animal’s eating). [</div><div class=\"sense\"><b>3)</b>  (b. h.) <i>to start a fire, enkindle</i>. V. <a href=\"#\" data-headword=\"בְּעֵרָה\">בְּעֵרָה</a>.] </div></div><div class=\"sense\"><b>Hif. הִבְעִיר</b> <div class=\"sense\"><i>to start</i> or <i>entertain a fire, to clear a field</i>. <span class=\"citation\">Sabb. 20ᵃ</span> (ref. to <span dir=\"rtl\">לא תבערו וכ׳</span> <span class=\"citation\">Ex. XXXV, 3</span>) <span dir=\"rtl\">בכל … אי אתה מַבְעִיר</span> ‘in all your dwellings’ thou art not permitted to start a fire; v. <a href=\"#\" data-headword=\"הַבְעָרָה\">הַבְעָרָה</a>. <span class=\"citation\">B. Kam. 60ᵇ</span> <span dir=\"rtl\">הַבְּעֵרָה שהִבְעַרְתִּי</span> the fire which I set (to Zion). <span class=\"citation\">Ib. 55ᵇ</span> (ref. to Ex. l. c. 5) <span dir=\"rtl\">עד דעביד כעין מבעיר</span> only when he acts like the one setting fire (to clear the field, i.e. criminal negligence); a. e.</div></div><div class=\"sense\"><b>Hof. הוּבְעָר</b> <div class=\"sense\"><i>to be rekindled, to burn again</i>. <span class=\"citation\">Sabb. 37ᵃ</span>; <span class=\"citation\">37ᵇ</span></div></div>","alt":[]},"4520":{"h":"בְּעַר I","r":"B01063","html":"<div class=\"sense\"><b>1)</b> <i>to burn</i>. <span class=\"citation\">Targ. O. Ex. III, 2</span> <a href=\"#\" data-headword=\"בָּעַר\">בָּעַר</a> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"בְּעַר I\">בָּעֵר</a>, Part). <span class=\"citation\">Targ. Is. LXII, 1</span>. <span class=\"citation\">Targ. Ps. XVIII, 9</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to remove; to dispose of</i>. <span class=\"citation\">Pes. 5ᵇ</span> <span dir=\"rtl\">בְּעִירוּ חמירא וכ׳</span> dispose ye of the leavened bread of the (gentile) soldiers (deposited with you).</div><div class=\"sense\"><b>Pa. בַּעֵר</b> <div class=\"sense\"><i>to enkindle, ignite</i>. <span class=\"citation\">Targ. Ex. XXXV, 3</span>. <span class=\"citation\">Targ. O. Lev. VI, 5</span> (Mss. a. some ed. <span dir=\"rtl\">יַבְעֵר</span> Af.).</div></div><div class=\"sense\"><b>Af. אַבְעֵר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"בָּעַר\">same</a>. <span class=\"citation\">Targ. O. Lev. VI, 5</span> (v. supra). *<span class=\"citation\">Targ. Y. I Gen. XV, 17</span> <span dir=\"rtl\">מַבְעִיר שביבין</span>.</div></div>","alt":["בְּעֵיר"]},"4521":{"h":"*בְּעַר II","r":"B01064","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"בְּעֵי II\"><span dir=\"rtl\">בְּעֵי</span> II</a>) <i>to open the mouth wide, to low</i> (of oxen; cmp. <span dir=\"rtl\">פער</span>). Targ. II Eth. I, 2 <span dir=\"rtl\">בוערין</span> (some edit. <span dir=\"rtl\">געיין</span>).</div>","alt":[]},"4522":{"h":"בְּעֵרָה","r":"B01065","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>fire, conflagration</i>. <span class=\"citation\">B. Kam. VI, 4</span> <span dir=\"rtl\">השולח את הב׳ ביד וכ׳</span> he who sends out a deaf and dumb, an idiot or a minor with burning materials (live coal &amp;c.) thus causing or ordering a conflagration. Ib. <span dir=\"rtl\">השולח את הב׳</span> he who starts a fire (himself). Ib. 60ᵇ, v. <a href=\"#\" data-headword=\"בָּעַר\">בָּעַר</a>.</div>","alt":[]},"4523":{"h":"בְּעַשׁ","r":"B01066","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"בְּאֵישׁ\">בְּאַשׁ</a> <i>to displease</i> (in Targ. Y. II). <span class=\"citation\">Targ. Y. II, Deut. XV, 10</span> (ed. Vien. <span dir=\"rtl\">באש</span>). <span class=\"citation\">Ib. XXVIII, 54</span> <span dir=\"rtl\">תַּבְעַשׁ</span> (read <span dir=\"rtl\">תִּבְעַשׁ</span>); <span class=\"citation\">56</span>.</div>","alt":[]},"4524":{"h":"בָּעַת","r":"B01067","html":"<div class=\"sense\"> ; interch. with <a href=\"#\" data-headword=\"בְּהַת\">בָּהַת</a> q. v.) <i>to startle</i>. [Not used in Kal.]</div><div class=\"sense\"><b>Nif. נִבְעַת</b> <div class=\"sense\"><i>to be startled, frightened, confounded</i>. <span class=\"citation\">Num. R. s. 18</span>; Tanḥ. Korah 6 נזדעזע אהרן ונ׳ Aaron trembled and was alarmed. Y. Shek. I, beg. Bab. ed. <span dir=\"rtl\">נִבָּעֵית</span>, v. <a href=\"#\" data-headword=\"בְּהַת\">בָּהַת</a>.</div></div><div class=\"sense\"><b>Hif. הִבְעִית</b> <div class=\"sense\"><i>to frighten, bewilder.</i> <span class=\"citation\">Yoma V, 1</span> (<span class=\"citation\">52ᵇ</span>) <span dir=\"rtl\">שלא להַבְעִית וכ׳</span> in order not to alarm the people (by a long delay). Ib. 39ᵇ <span dir=\"rtl\">למה אתה מבעית עצמך</span> why wilt thou be the alarmer thyself (predicting thine own destruction; Ms. M. a. <span class=\"citation\">Yalk. Zech. 578</span> <span dir=\"rtl\">את עצמך</span>, incorr.; Ms. Oxf. <span dir=\"rtl\">בעצמך</span>; Y. ib. VI, 43ᶜ bot. <span dir=\"rtl\">מבהלינו</span>, v. Rabb. D. S. a. l. note).</div></div><div class=\"sense\"><b>Hithpa. הִתְבָּעֵת</b> <div class=\"sense\"><i>to be agitated, excited</i>. Y. Sabb. VI, 8ᵇ top <span dir=\"rtl\">שהוא מִתְבָּעֵת</span> for he is excited.</div></div>","alt":[]},"4525":{"h":"בְּעֵת","r":"B01068","html":"<div class=\"sense\">(v. <a href=\"#\" data-headword=\"בָּעַת\">preced.</a>) <i>to be excited</i>. <span class=\"citation\">Nidd. 66ᵇ</span> <span dir=\"rtl\">משום דבעיתא</span> because she is excited (afraid of falling down).</div><div class=\"sense\"><b>Pa. בַּעֵית  בַּעֵת</b> <div class=\"sense\"><i>to frighten</i>. <span class=\"citation\">Targ. Ps. XVIII, 5</span> (Ms. <span dir=\"rtl\">בְּעֵיתַת</span> Pe.).—<span class=\"citation\">Keth. 77ᵇ</span> <span dir=\"rtl\">דילמא מְבַעֲתַת לי</span> lest thou frighten me. <span class=\"citation\">Ḥull. 53ᵃ</span> sq. <span dir=\"rtl\">בַּעוּתֵי קא מְבַעֲתֵי אהדדי</span> they frighten each other. <span class=\"citation\">Nidd. 66ᵃ</span> <span dir=\"rtl\">זיל בַּעֲתָהּ</span> go and frighten her (by a sudden noise).</div></div><div class=\"sense\"><b>Ithpe. אִתְבְּעֵית  אִיבְּעֵית</b> <div class=\"sense\"><i>to be afraid; to be agitated, anxious, in haste</i> (cmp. b. h. <a href=\"#\" data-headword=\"חָרֵד\">חָרַד</a>). <span class=\"citation\">Targ. I Sam. XXI, 2</span>. <span class=\"citation\">Targ. Is. XXII, 4</span>. <span class=\"citation\">Targ. II Kings VII, 15</span> באִתְבְּעָתוּתְהוֹן Regia (ed. <span dir=\"rtl\">באתבעותהון</span>); v. <a href=\"#\" data-headword=\"בְּעַע\">בְּעַע</a> a. <a href=\"#\" data-headword=\"בְּעֵי I\"><span dir=\"rtl\">בְּעֵי</span> I</a>. Y. Ab. Zar. V, 44ᵈ bot. <span dir=\"rtl\">והוא מתבעת</span> and he is afraid (to touch the wine).—<span class=\"citation\">Meg. 3ᵃ</span> <span dir=\"rtl\">האי מאן דמִיבְּעִית</span> when one is suddenly seized with fright. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">איבעיתו</span>. <span class=\"citation\">Keth. 106ᵃ</span> <span dir=\"rtl\">הוה מיבעית ליה בעותי</span> he ran anxiously to meet him; cmp. Targ. I Sam. l. c.; a. fr.</div></div>","alt":["בְּעִית"]},"4526":{"h":"בַּעֲתָא I","r":"B01069","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּעֵת\">preced.</a>) <i>terror</i>.—Pl. <span dir=\"rtl\">בַּעֲתַיָּא</span>. <span class=\"citation\">Targ. Ps. LXXXVIII, 17</span>, v. <a href=\"#\" data-headword=\"בִּיעוּתָא\">בִּיעוּתָא</a>.</div>","alt":[]},"4527":{"h":"בַּעֲתָא II","r":"B01070","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּעַע\">בעע</a>) <i>urging, stimulation</i>. <span class=\"citation\">Targ. Prov. XIII, 1</span>; a. e. (h. text <span dir=\"rtl\">גערה</span>).—<span class=\"citation\">Ib. XVII, 10</span> some ed. <a href=\"#\" data-headword=\"בָּעָאתָא\">בָּעָאתָא</a>.</div>","alt":[]},"4528":{"h":"בפה","r":"B01071","html":"<div class=\"sense\">, Y. Meg. I, 72ᵃ top, v. <a href=\"#\" data-headword=\"כִּיפָה\">כִּיפָה</a></div>","alt":[]},"4529":{"h":"בְּצָא","r":"B01072","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בץ</span> = <span dir=\"rtl\">בק</span>, <span dir=\"rtl\">בע</span>; cmp. <span dir=\"rtl\">בצע</span>) [<i>to split, break through;</i>] (cmp. <a href=\"#\" data-headword=\"בְּעֵי I\"><span dir=\"rtl\">בְּעֵי</span> I</a>) <i>to search, ransack</i>. <span class=\"citation\">Targ. Prov. II, 4</span> (ed. Wil. <span dir=\"rtl\">תצביה</span>, read <span dir=\"rtl\">תבציה</span>). <span class=\"citation\">Ib. XXV, 27</span>. <span class=\"citation\">Ib. XX, 27</span> (Var. <span dir=\"rtl\">בעיא</span>).—<i>Part.</i> <span dir=\"rtl\">בָּצֵי בָּאצֵי</span>. <span class=\"citation\">Ib. XXV, 2</span>.</div><div class=\"sense\"><b>Ithpe. אִתְבְּצֵי</b> <div class=\"sense\">, contr. <span dir=\"rtl\">אִיבְּצֵי</span> <i>to be searched, found out</i>. Ib. 3. Ib. XXVIII, 12 <span dir=\"rtl\">מִבְּצֵי</span>.</div></div>","alt":["בְּצֵי"]},"4530":{"h":"בִּצָּא","r":"B01073","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"בִּיצָּה\">בִּיצָּה</a>) <i>swamp, pond</i>. <span class=\"citation\">Targ. Job VIII, 11</span> (Var. <span dir=\"rtl\">כיסנא</span>). <span class=\"citation\">Targ. Ps. LXIX, 3</span> בוצא דמצולתא Ms. (ed. <span dir=\"rtl\">מיא</span>).—Pl. <a href=\"#\" data-headword=\"בִּצִּים\">בִּצִּין</a>, <span dir=\"rtl\">בִּצַּיָּא</span>, <a href=\"#\" data-headword=\"בִּדּוּר\">בִּי׳</a>. <span class=\"citation\">Targ. Is. XIV, 23</span>. <span class=\"citation\">Targ. Y. II, Ex. VIII, 1</span> (ed. Vien. <span dir=\"rtl\">בֵּיצַיָּא</span>). <span class=\"citation\">Targ. Ezek. XLVII, 11</span>.</div>","alt":["בִּיצָּא","(בּוּצָא)"]},"4531":{"h":"בִּצְבּוּץ","r":"B01074","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>hemp</i>, v. <a href=\"#\" data-headword=\"בִּטְבּוּט\">בִּטְבּוּט</a>.</div>","alt":[]},"4532":{"h":"בִּצְבֵּץ","r":"B01075","html":"<div class=\"sense\"> (Pilp. of <a href=\"#\" data-headword=\"בּוּץ\">בוץ</a> or <a href=\"#\" data-headword=\"בָּצַץ\">בצץ</a>; v. <a href=\"#\" data-headword=\"בְּצָא\">בְּצָא</a>) <i>to break through, bubble forth, burst forth</i>. <span class=\"citation\">Sot. 11ᵇ</span>; <span class=\"citation\">Ex. R. s. 1</span> <span dir=\"rtl\">היו מְבַצְבְּצִין וכ׳</span> they burst forth and came out of the ground. <span class=\"citation\">Keth. 111ᵇ</span> the righteous (dead) <span dir=\"rtl\">שמבצבצין וכ׳</span> will break through (the ground) and rise in Jerusalem.—<span class=\"citation\">Pes. 13ᵃ</span> <span dir=\"rtl\">היה חמץ מב׳</span> the leavened bread crumbled through the bag. <span class=\"citation\">Num. R. s. 18</span>, end; <span class=\"citation\">Gitt. 56ᵇ</span> <span dir=\"rtl\">דם מב׳ ויוצא</span> blood bubbled forth. <span class=\"citation\">Ḥull. 56ᵃ</span> <span dir=\"rtl\">אם מב׳</span> if the brains bubble through the hole in the scull.</div>","alt":[]},"4533":{"h":"בַּצְבֵּץ","r":"B01076","html":"<div class=\"sense\"><span class=\"citation\">Ḥull. 46ᵇ</span> <span dir=\"rtl\">אי מבצבצא</span> if the lungs (on being put in water, or water being put on the diseased spot) cast bubbles when blown up.</div>","alt":[]},"4534":{"h":"בֵּצָה","r":"B01077","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּיצָה\">בֵּיצָה</a></div>","alt":["בֵּצִים"]},"4535":{"h":"בִּצָּה","r":"B01078","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> ; cmp. <a href=\"#\" data-headword=\"בִּצְעָה\">בִּצְעָה</a>, a. <span dir=\"rtl\">בִּצְאֹת</span> Ezek. <span class=\"citation\">Ezek. XLVII, 11</span>) <i>channel, marsh, pond.—</i> Pl. <a href=\"#\" data-headword=\"בִּצִּים\">בִּצִּים</a>, <a href=\"#\" data-headword=\"בִּדּוּר\">בִּי׳</a>. <span class=\"citation\">Par. VIII, 10</span>. <span class=\"citation\">Tosef. Mikv. I, 14</span>. <span class=\"citation\">Snh. 5ᵇ</span> a teacher spoke of <span dir=\"rtl\">מי בֵיצִים</span> the liquid of eggs, and the students understood <a href=\"#\" data-headword=\"בִּצִּים\">בִּצִּים</a> Ar. (Ms. F. <span dir=\"rtl\">ביצים</span>, ed. <span dir=\"rtl\">בצעים</span>, v. <a href=\"#\" data-headword=\"בִּצְעָה\">בִּצְעָה</a>). V. <a href=\"#\" data-headword=\"בִּיצִּית\">בִּיצִּית</a>.</div>","alt":["בִּיצָּה"]},"4536":{"h":"בְּצוֹצְטְרָא","r":"B01079","html":"<div class=\"sense\"> f., pl. <span dir=\"rtl\">בְּצוֹצְטְרָאוֹת</span> (reduplic. of <span dir=\"rtl\">בצר</span>) = <a href=\"#\" data-headword=\"גִּזְרָה\">גִּיזְרָה</a> a. <a href=\"#\" data-headword=\"גְּזוּזְטְרָא\">גְּזוּזְטְרָא</a>; cmp. <a href=\"#\" data-headword=\"בְּצוּרְתָא\">בְּצוֹרְתָא</a>. Y. B. Bath. III, end, 14ᵇ (for which <span class=\"citation\">Tosef. ib. II, 17</span> <span dir=\"rtl\">גזוזטראות</span>). V. <a href=\"#\" data-headword=\"בְּצוֹצְרָה\">next w.</a></div>","alt":[]},"4537":{"h":"בְּצוֹצְרָה","r":"B01080","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (reduplic. of <span dir=\"rtl\">בצר</span>; cmp. <a href=\"#\" data-headword=\"חֲצוֹצְרָה\">חצוצרה</a>) <i>a compartment surrounded with bars, balustrade, balcony.</i> <span class=\"citation\">Midd. II, 5</span> <span dir=\"rtl\">והקיפוה ב׳ וכ׳</span> and they surrounded the cell (<a href=\"#\" data-headword=\"לִשְׁכָּה\">לשכה</a>) with a balcony so that the women could sit above, while the men were seated beneath it; [<span class=\"citation\">Succ. 51ᵇ</span> <a href=\"#\" data-headword=\"גְּזוּזְטְרָא\">גזוזטרא</a>, Ms. M. <span dir=\"rtl\">גזוזטראות</span>; <span class=\"citation\">Tosef. ib. IV, 1</span> <span dir=\"rtl\">שלש גז׳</span>]. [The variations <span dir=\"rtl\">כצוצרא</span>, <span dir=\"rtl\">כצוצטרא</span> &amp;c., v. Rabb. D. S. to <span class=\"citation\">Sabb. 96ᵃ</span>, <span class=\"citation\">Erub. 78ᵇ</span> notes, a. Ar. s. v. <a href=\"#\" data-headword=\"גְּזוּזְטְרָא\">גזוזטרא</a>, are clerical errors induced by assonance with the synonymous <a href=\"#\" data-headword=\"גְּזוּזְטְרָא\">גזוזטרא</a>. Ἔξώστρα as <i>balcony</i>, for h. <a href=\"#\" data-headword=\"עֲלִיָּה\">עליה</a>, Symm. <span class=\"citation\">II Kings I, 2</span>, is itself an adaptation of <a href=\"#\" data-headword=\"גְּזוּזְטְרָא\">גזוזטרא</a>.]</div>","alt":[]},"4538":{"h":"בְּצוֹצְרִיּוֹת","r":"B01081","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">בצר</span>, v. <a href=\"#\" data-headword=\"בְּצוֹצְרָה\">preced.</a>) <i>engines of siege</i> or <i>defence</i> (v. <a href=\"#\" data-headword=\"אָהֳלִית\">אָהֳלִית</a>). Pesik. Haḥod. p. 47ᵃ; Shub. p. 163ᵇ (for Var. Lect., v. Bub. notes a. l.); <span class=\"citation\">Pesik. R. s. 15</span>. <span class=\"citation\">Midr. Till. to Ps. II</span>, end <span dir=\"rtl\">שמא אהליות וב׳ אני צריך</span> do I need camps and engines (for demolishing the world)?; <span class=\"citation\">Yalk. Ps. 623</span> <a href=\"#\" data-headword=\"צוצריות\">צוצריות</a> (corr. acc.). V. <span dir=\"rtl\">קַסְטְרִיּוֹת</span>.</div>","alt":["בְּצַרְצְרִיּוֹת"]},"4539":{"h":"בַּצּוֹרֶת","r":"B01082","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>scarcity of provision, dearth.</i> <span class=\"citation\">Ab. V, 8</span> <span dir=\"rtl\">רעב של ב׳ וכ׳</span> a famine in consequence of high prices, when some are hungry, others are satisfied, <span dir=\"rtl\">רעב של מהומה ושל ב׳</span> a famine through political disturbances and through dearth. <span class=\"citation\">Gen. R. s. 33</span> <span dir=\"rtl\">שנת ב׳</span> a year of dearth. <span class=\"citation\">Taan. III, 1</span> <span dir=\"rtl\">מכת ב׳</span>, expl. <span class=\"citation\">ib. 19ᵇ</span> <span dir=\"rtl\">מכה המביאה לידי ב׳</span> a calamity which will produce dearth (want of rain in season).</div>","alt":[]},"4540":{"h":"בַּצּוֹרְתָא","r":"B01083","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. XVII, 8</span> (ed. Wil. <a href=\"#\" data-headword=\"בְּצוּרְתָא\">בְּצוּרְתָא</a>); a. fr.—<span class=\"citation\">Taan. 19ᵃ</span>; <span class=\"citation\">19ᵇ</span> <span dir=\"rtl\">נהרא אנהרא ב׳ וכ׳</span> when provision has to be imported on rivers (canals), it is called <a href=\"#\" data-headword=\"ב׳\">ב׳</a>, when from one country to another it is called <a href=\"#\" data-headword=\"כְּפַן II\">כפנא</a>. <span class=\"citation\">Keth. 97ᵃ</span>.—Pl. <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בַּצּוֹרָתָא</a>. <span class=\"citation\">Targ. Jer. XIV, 1</span> (some ed. <a href=\"#\" data-headword=\"בֹּוצְרָתָא\">בּוּצְרָתָא</a>).</div>","alt":["(בִּיצּוּרְתָּא","בִּיצַּרְתָּא","בּוּ׳)"]},"4541":{"h":"בְּצוּרְתָא","r":"B01084","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"גִּזְרָה\">גִּזְרָה</a>, <i>balcony</i> (v. <a href=\"#\" data-headword=\"בְּצוֹצְרָה\">בְּצוֹצְרָה</a>). <span class=\"citation\">Targ. Ezek. XLI, 13</span> sq.; a. fr.—</div>","alt":["(בצירתא","ביצורתא)"]},"4542":{"h":"בֵּצִים","r":"B01085","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּיצָה\">בֵּיצָה</a></div>","alt":[]},"4543":{"h":"בִּצִּים","r":"B01086","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּצָּה\">בִּצָּה</a></div>","alt":[]},"4544":{"h":"בָּצִיר I","r":"B01087","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>vintage, harvesting.</i> <span class=\"citation\">Peah VII, 7</span>; a. fr.—<span class=\"citation\">Y. B. Bath. III, 14ᵃ</span> top <span dir=\"rtl\">ג׳ שנים … ב׳ וכ׳</span> three undisturbed grain crops, three grape harvests &amp;c.; v. Bab. <span class=\"citation\">B. Bath. 36ᵇ</span>.  v. <a href=\"#\" data-headword=\"בְּצִירָה\">בְּצִירָה</a>.</div>","alt":[]},"4545":{"h":"בָּצִיר II","r":"B01088","html":"<div class=\"sense\"> ch. m. (<span dir=\"rtl\">בצר</span>) <i>diminished, small;</i> (adv.) <i>less, least</i>. <span class=\"citation\">Targ. Y. Gen. I, 16</span>; a. e.—<span class=\"citation\">Snh. 108ᵇ</span>. <span class=\"citation\">B. Mets. 21ᵇ</span> <span dir=\"rtl\">ב׳ מהכי</span> less than this; a. fr.—V. <a href=\"#\" data-headword=\"*בִּיצִירְתָּא\">בִּיצִירְתָּא</a>.</div>","alt":["בְּצִיר"]},"4546":{"h":"בְּצִיר","r":"B01089","html":"<div class=\"sense\"><i>to be less</i>, v. <a href=\"#\" data-headword=\"בְּצַר\">בְּצַר</a>.</div>","alt":[]},"4547":{"h":"בַּצִּירָא","r":"B01090","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּצַר\">בְּצַר</a>, end.</div>","alt":[]},"4548":{"h":"בְּצִירָה","r":"B01091","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"בָּצִיר I\"><span dir=\"rtl\">בָּצִיר</span> I</a>. <span class=\"citation\">Sabb. 17ᵃ</span> <span dir=\"rtl\">בשעת הב׳</span> when they are cut; a. fr.—Pl. <span dir=\"rtl\">בְּצִירוֹת</span>. <span class=\"citation\">B. Bath. 36ᵇ</span> <span dir=\"rtl\">עד שיבצור ג׳ ב׳</span>, v. <a href=\"#\" data-headword=\"בָּצִיר I\">בָּצִיר</a>.</div>","alt":[]},"4549":{"h":"בְּצִירְתָּא","r":"B01092","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּצוּרְתָא\">בְּצוּרְתָא</a></div>","alt":[]},"4550":{"h":"בְּצַל","r":"B01093","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בץ</span>, cmp. <span dir=\"rtl\">פצל</span>) <i>to peel; to split, branch off</i>. Lam. R. introd.; <span class=\"citation\">Koh. R. to XII, 7</span> (interpret. <span dir=\"rtl\">אם הדרך</span> <span class=\"citation\">Ezek. XXI, 26</span>) <span dir=\"rtl\">(<span dir=\"rtl\">אם</span>) <span dir=\"rtl\">אמה דבצלית</span></span> an arm which branches off (direction post on the cross-road).</div><div class=\"sense\"><b>Ithpe. אִיבְּצִיל</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"בָּצְלָא\">בָּצְלָא</a>) <i>to grow bulbous</i>. <span class=\"citation\">Erub. 29ᵇ</span> top <span dir=\"rtl\">אי׳ זירתא</span> (ed. Pesaro a. Ar. <span dir=\"rtl\">אפציל</span>, Var. <span dir=\"rtl\">אבציל</span>) the bulb has grown to the length of a span.</div></div>","alt":[]},"4551":{"h":"בָּצֵל","r":"B01094","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"בְּצַל\">preced.</a>) <i>onion</i>. <span class=\"citation\">Nidd. 17ᵃ</span>; a. fr.—<span class=\"citation\">Maasr. V, 7</span> (<span class=\"citation\">8</span>) <span dir=\"rtl\">ב׳ של רכפה</span>, expl. in Y. ib. 52ᵃ ‘the stalk of which is pressed inward’; oth. opin. ‘which has no acerbity’, v. <a href=\"#\" data-headword=\"אֶרֶס\">אֶרֶס</a>.—Pl. <a href=\"#\" data-headword=\"בְּצָלִים\">בְּצָלִים</a>. <span class=\"citation\">Shebi. II, 9</span> <span dir=\"rtl\">הב׳ הסריסים</span> which produce no seeds. <span class=\"citation\">Ib. V, 4</span> <span dir=\"rtl\">ב׳ הקיצונים</span> summer onions; a. fr.—<span class=\"citation\">Ukts. II, 8</span> <span dir=\"rtl\">עלי ב׳ ובני ב׳</span> the leek-like sprouts, and the central sprouts of onions. <span class=\"citation\">Gen. R. s. 82</span> (ref. to <span class=\"citation\">Ob. I, 6</span>) <span dir=\"rtl\">קליפת ב׳</span> (not <span dir=\"rtl\">בצליא</span>) like peeling onions (laying bare Esau’s shame).</div>","alt":[]},"4552":{"h":"בָּצְלָא","r":"B01095","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּצְלָא\">בּוּצְלָא</a></div>","alt":[]},"4553":{"h":"בְּצַלְאֵל","r":"B01096","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (b. h.) <i>Bezaleel</i>; </div><div class=\"sense\"><b>1)</b>  the artificer of the Tabernacle. <span class=\"citation\">Ber. 55ᵃ</span>. <span class=\"citation\">Ex. R. s. 48</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  R. B., an Amora. <span class=\"citation\">Cant. R. to III, 11</span> <span dir=\"rtl\">ר׳ ברכיה בשם ר׳ ב׳</span> (<span class=\"citation\">Num. R. s. 12</span> <a href=\"#\" data-headword=\"בצלה\">בצלה</a>; Pesik. Vayhi, p. 4ᵇ <a href=\"#\" data-headword=\"לוי\">לוי</a>; <span class=\"citation\">Yalk. Ex. 369</span> only <span dir=\"rtl\">בשם ר׳</span>).</div>","alt":[]},"4554":{"h":"בצלה","r":"B01097","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּצַלְאֵל\">preced.</a></div>","alt":[]},"4555":{"h":"בְּצָלִים","r":"B01098","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ăle B’tsalim</i> (Onion Leaves). <span class=\"citation\">Y. Snh. VI, 23ᶜ</span> bot.; <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> bot. Miriam, the daughter of A. B. (prob. a nickname).</div>","alt":["עֲלֵי ב׳"]},"4556":{"h":"בְּצַלְצוּל","r":"B01099","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (dimin. of <a href=\"#\" data-headword=\"בָּצֵל\">בָּצֵל</a>) <i>dwarf-onion</i>, (<i>pallacana</i>). <span class=\"citation\">Kil. I, 3</span>; v. Y. ib. 27ᵃ. [Maim.: <i>desert onion</i>.]</div>","alt":[]},"4557":{"h":"בָּצַע","r":"B01100","html":"<div class=\"sense\"><b>1)</b> <i>to cut, break</i>, esp. <i>to break bread and say the blessing</i>. <span class=\"citation\">Ḥull. 7ᵇ</span> <span dir=\"rtl\">מימיו לא ב׳ על וכ׳</span> never said grace over a piece of bread which was not his own (never accepted an invitation). <span class=\"citation\">Ber. 46ᵃ</span> <span dir=\"rtl\">בע&quot;הב בּוֹצֵעַ וכ׳</span> the host breaks the bread and the guest says grace after meal. <span class=\"citation\">Ib. 47ᵃ</span> <span dir=\"rtl\">אין הבוצע רשאי לִבְצוֹעַ וכ׳</span> he who is chosen to break the bread, must not begin to break until the Amen of those that respond (to the blessing) is finished; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to split the difference, to adjust, compromise</i>. <span class=\"citation\">Snh. 6ᵇ</span> top <span dir=\"rtl\">נגמר … לבצוע</span> after the legal proceedings are closed, thou must not act as an arbiter in a compromise. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אסור לב׳</span> the court is forbidden to attempt a settlement (you must let the law take its course). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מצוה לב׳</span> it is a meritorious act to bring about a settlement. <span class=\"citation\">Ib.</span> (before having formed an opinion the judge may say) <span dir=\"rtl\">צאו ובִצְעוּ</span> go out and settle; a. fr.</div><div class=\"sense\"><b>Pi. בִּצַּע</b> <div class=\"sense\"><i>to adjust</i>. Y. Snh. I, 18ᵇ top <span dir=\"rtl\">המְבַצֵּעַ חוטא</span> the judge who settles a case is a sinner. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לְבַצֵּעַ</span> (interch. with <span dir=\"rtl\">לבצוע</span>). V. <a href=\"#\" data-headword=\"בִּיצּוּעַ\">בִּיצּוּעַ</a>.</div></div>","alt":[]},"4558":{"h":"בְּצַע","r":"B01101","html":"<div class=\"sense\"><b>1)</b> <i>to break</i>. <span class=\"citation\">B. Bath. 91ᵇ</span> <span dir=\"rtl\">כד הוה ב׳ ינוקא וכ׳</span> when a child broke apart a piece of St. John’s bread. <span class=\"citation\">Sabb. 140ᵇ</span>, v. <a href=\"#\" data-headword=\"בִּיצּוּעָא\">בִּיצּוּעָא</a>.—</div><div class=\"sense\"><b>*2)</b> <i>to tear away, rescue</i> (cmp. <a href=\"#\" data-headword=\"פְּצֵי\">פצי</a>). <span class=\"citation\">Targ. Job XXXIII, 18</span> יבצע Ms. (ed. <span dir=\"rtl\">ימנע</span>).</div><div class=\"sense\"><b>Pa. בַּצַּע</b> <div class=\"sense\"><i>to break</i>. <span class=\"citation\">Targ. O. Lev. II, 6</span> (Var. <a href=\"#\" data-headword=\"בְּצַע\">בְּצַע</a> Pe.). [Y. Taan. IV, 69ᵇ; Y. Meg. I, 70ᵃ bot. <span dir=\"rtl\">מבצע</span> (<span class=\"citation\">Cant. R. to I, 16</span> <span dir=\"rtl\">מצנעה</span>) read: <span dir=\"rtl\">מנצב</span>, <span dir=\"rtl\">מנצבה</span>, v. <a href=\"#\" data-headword=\"נְצַב\">נְצַב</a>.]</div></div>","alt":[]},"4559":{"h":"בִּצְעָה","r":"B01102","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בצע</span>, cmp. <a href=\"#\" data-headword=\"בִּצָּה\">בִּצָּה</a>) <i>ditch, dike, pond.</i> <i>—</i> Pl. <span dir=\"rtl\">בִּצְעִים</span>, <a href=\"#\" data-headword=\"בִּיצְעֵי\">בִּצְעִין</a>, <a href=\"#\" data-headword=\"בִּדּוּר\">בִּי׳</a>. <span class=\"citation\">Tosef. Snh. III, 4</span> <span dir=\"rtl\">שתי בצעין</span> ed. Zuck. (Var. <span dir=\"rtl\">ביצועין</span>); <span class=\"citation\">Shebu. 16ᵃ</span> שני בצעים וכ׳ Ar. (read <a href=\"#\" data-headword=\"שתי\">שתי</a>, ed. <a href=\"#\" data-headword=\"בִּיצְעֵי\">ביצעין</a>, Ms. M. <span dir=\"rtl\">בצעי׳</span>) there were two ponds (reservoirs) in Jerusalem, the upper &amp;c. <span class=\"citation\">Sabb. 31ᵃ</span> <span dir=\"rtl\">בין בִּצְעֵי המים</span> between the dykes (of the Nile). <span class=\"citation\">Snh. 96ᵃ</span> <span dir=\"rtl\">בִּיצְעֵי וכ׳</span>. <span class=\"citation\">Ib. 5ᵇ</span>, v. <a href=\"#\" data-headword=\"בִּצָּה\">בִּצָּה</a>.</div>","alt":[]},"4560":{"h":"בָּצַץ","r":"B01103","html":"<div class=\"sense\"> (v. <span dir=\"rtl\">בצבץ</span>) <i>to break through, divide; to ooze, trickle, drip</i>. <span class=\"citation\">Y. Pes. VII, beg. 34ᵃ</span> <span dir=\"rtl\">כל העצים בּוֹצְצִין משקין</span> all other sorts of wood (used for roasting spits) will drip moisture. Y. M. Kat. I, beg. 80ᵃ; <span class=\"citation\">Tosef. Mikv. I, 13</span> <span dir=\"rtl\">ההרים בוצצין</span> (ed. Zuck. <span dir=\"rtl\">ביצין</span>) the mountains are trickling (sending the rain water into the rivers; cmp. <a href=\"#\" data-headword=\"בִּצְעָה\">preced.</a>).</div>","alt":[]},"4561":{"h":"בָּצֵק","r":"B01104","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>dough</i>. <span class=\"citation\">Pes. III, 2</span> (<span class=\"citation\">46ᵃ</span>) <span dir=\"rtl\">ב׳ הַחֵרֵשׁ</span> deaf dough, i.e. having no indications of rising (which makes it doubtful whether or not fermentation has set in); [oth. reading <span dir=\"rtl\">ב׳ הַחֶרֶשׂ</span> hard and smooth as a potsherd]. Ib. 4; a. fr.—Pl. <span dir=\"rtl\">בְּצֵקוֹת</span>. Ib. 40ᵃ</div>","alt":[]},"4562":{"h":"בָּצַר","r":"B01105","html":"<div class=\"sense\"><i>to cut</i> grapes. <span class=\"citation\">Pes. 3ᵇ</span> <span dir=\"rtl\">בּוֹצְרִין בטהרה</span> one must cut grapes under the rules of levitical cleanness. <span class=\"citation\">Gitt. 57ᵃ</span> <span dir=\"rtl\">בָּצְרוּ … את כרמיהן וכ׳</span> the gentiles held vintage in vineyards soaked with Israel’s blood; a. fr.</div><div class=\"sense\"><b>Nif. נִבְצַר</b> <div class=\"sense\"><b>1)</b> <i>to be cut</i>. <span class=\"citation\">Ex. R. s. 30</span>, beg. <span dir=\"rtl\">עד שתגיע עונתן לִיבָּצֵר</span> until their (the nations’) time has arrived to be cut (ripe for punishment). </div><div class=\"sense\"><b>2)</b> <i>to be cut off, diminished</i>. Tanḥ. Noah 18 <span dir=\"rtl\">נִבְצָרִים מן וכ׳</span> cut off from the world (destroyed). <span class=\"citation\">Gen. R. s. 38</span> <span dir=\"rtl\">יִבָּצֵר מהם</span> shall be denied them.</div></div><div class=\"sense\"><b>Pi. בִּצֵּר  בִּיצֵּר</b> <div class=\"sense\"><i>to cut off</i>, whence (cmp. <a href=\"#\" data-headword=\"גֶּדֶר I\">גדר</a>) </div><div class=\"sense\"><b>1)</b> <i>to surround, fortify</i>. Part. pass. <span dir=\"rtl\">מְבוּצָּר</span>. Y. Pes. VII, 35ᵇ bot.; Y. Shebu. VIII, beg., 38ᵇ <span dir=\"rtl\">גג מב׳</span> a roof surrounded with railings, v. <a href=\"#\" data-headword=\"בְּצוֹצְרָה\">בְּצוֹצְרָה</a>.—<span class=\"citation\">Neg. I, 5</span> <span dir=\"rtl\">מְבוּצֶּרֶת</span> an eruption surrounded with sound flesh; <span class=\"citation\">ib. X, 2</span> sq. <span dir=\"rtl\">מבוצר</span> (of the hair in the flesh affected by the eruption). <span class=\"citation\">Deut. R. s. 1</span> (ref. to <span dir=\"rtl\">עיר מצור</span> <span class=\"citation\">Ps. LX, 11</span>, a. <span dir=\"rtl\">מבצר</span> <span class=\"citation\">ib. CVIII, 11</span>) <span dir=\"rtl\">עיר שמבוצרת וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>to diminish</i>. Ib. <span dir=\"rtl\">שמצירה ומבצרה לישראל</span> (Mat. K. <span dir=\"rtl\">ומְבַצֶּרֶת</span>, <span class=\"citation\">Yalk. Ps. 779</span> <span dir=\"rtl\">מבצרא</span> ch.) the city which troubles and diminishes Israel.</div></div><div class=\"sense\"><b>Nithpa. נִתְבַּצֵּר</b> <div class=\"sense\"><i>to be railed around, be set apart</i>. <span class=\"citation\">Meg. 14ᵃ</span>; <span class=\"citation\">Snh. 110ᵃ</span>; <span class=\"citation\">Num. R. s. 18</span> <span dir=\"rtl\">מקום נ׳ להם וכ׳</span> a place was set apart for them in Gehenna; <span class=\"citation\">Koh. R. to VII, 2</span>.</div></div>","alt":[]},"4563":{"h":"בָּצֵר","r":"B01106","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בָּצַר\">preced.</a> a. <a href=\"#\" data-headword=\"בְּצַר\">next w.</a>) <i>to be diminished</i>. <span class=\"citation\">Keth. 7ᵇ</span> <span dir=\"rtl\">דבָצְרָה מיום אחד</span> who has less than one day’s (celebration of marriage with benedictions at meals).</div>","alt":[]},"4564":{"h":"בְּצַר","r":"B01107","html":"<div class=\"sense\"><b>1)</b>  (neut. v.) <i>to be cut, lessened; to be small; to want</i>. <span class=\"citation\">Ab. Zar. 9ᵃ</span> <span dir=\"rtl\">כמה בצרן</span> (Rashi <span dir=\"rtl\">בצירן</span>) how much is wanting yet? <span class=\"citation\">Targ. Prov. XIV, 28</span> <span dir=\"rtl\">בציר עמא</span> the population is diminishing.—<span class=\"citation\">Ḥull. 42ᵇ</span> <span dir=\"rtl\">בצר להו חדא</span> there is, according to him, one less (than the number stated); a. fr.</div><div class=\"sense\"><b>—2)</b>  (act. v.) <i>to diminish, lessen</i>. <span class=\"citation\">Targ. Y. Deut. XIII, 1</span>; <span class=\"citation\">IV, 2</span> (Var. <span dir=\"rtl\">תבַצְּרוּן</span> Pa.). <span class=\"citation\">Targ. Job XV, 4</span>.—<span class=\"citation\">Nidd. 65ᵃ</span> <span dir=\"rtl\">למִבְצַר לה חדא</span> to allow her one night less; a. fr.</div><div class=\"sense\"><b>Pa. בַּצַּר</b> <div class=\"sense\"><i>to cut off; to diminish, deduct</i>. <span class=\"citation\">Men. 37ᵇ</span> <span dir=\"rtl\">האי מאן דבַצְּרֵיה לגלימיה</span> he who cuts one corner of his cloak off.—<span class=\"citation\">Targ. Koh. III, 5</span>. <span class=\"citation\">Targ. Deut. IV, 2</span>, a. e., v. supra.—<span class=\"citation\">Ab. Zar. 9ᵇ</span> <span dir=\"rtl\">ונְבַצַּר וכ׳</span> we let him deduct therefrom forty eight. <span class=\"citation\">B. Mets. 103ᵇ</span> בַּצְּרִי לך I let thee have it for less.—Denom. <a href=\"#\" data-headword=\"בַּצִּירָא\">בַּצִּירָא</a> <i>one who uses the vowel letters sparingly</i>. <span class=\"citation\">Ab. Zar. 9ᵃ</span>; <span class=\"citation\">9ᵇ</span> and as a mnemonical sign (for remembering when to add and when to deduct) <span dir=\"rtl\">ספרא ב׳ וכ׳</span> the writer of Bible copies writes many words without the vowel letters (defective) which the Mishnah teacher writes <i>plene</i></div></div>","alt":["בְּצֵיר"]},"4565":{"h":"בֶּצֶר","r":"B01108","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"בָּצִיר I\">בָּצִיר</a> <i>crop</i>, trnsf. <i>means of support</i>, (<i>family-</i>) <i>trade</i>. <span class=\"citation\">Ex. R. s. 40</span>, end <span dir=\"rtl\">לעולם … מניח בִּצְרוֹ</span> one should never give up his trade; <span class=\"citation\">Pesik. R. s. 6</span>, end <span dir=\"rtl\">מחליף בְּצִירוֹ</span> (<span class=\"citation\">Arakh. 16</span> <span dir=\"rtl\">אומנותו ואומנות אבותיו</span>). Ex. R. l. c. (insert <span class=\"citation\">Job XXII, 24—25</span> as text) the Lord says, <span dir=\"rtl\">אני הוא בִצְרְכֶן … בִצְרָן וכ׳</span> I am your support, give ye never up your support (faith); but also the support of your fathers ye must not give up (labor) &amp;c. Pesik. R. l. c. thou art our God <span dir=\"rtl\">ובְצִירֵנוּ</span> and our support (ref. to <span class=\"citation\">Ps. XCV, 6</span>).</div><div class=\"sense\"><b>—2)</b>  pl. <a href=\"#\" data-headword=\"בְּצָלִים\">בְּצָרִים</a> <i>fort</i>. Ex. R. l. c. (ref. to Job l. c.; cmp. Targ.) <span dir=\"rtl\">שנעשה חומותיך</span> He will be thy fortification. [<span class=\"citation\">Yalk. Deut. 811</span>, v. <a href=\"#\" data-headword=\"בִּיצּוּר\">בִּיצּוּר</a>.]</div>","alt":[]},"4566":{"h":"בָּצְרָאָה","r":"B01109","html":"<div class=\"sense\"> &amp;c., v. <span dir=\"rtl\">בּוֹצְ׳</span></div>","alt":["בָּצְרָה"]},"4567":{"h":"*בֶּצֶת","r":"B01110","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Betseth</i>, a Phœnician border-town (perh. identical with Bassa, Neub. Géogr. p. 22). <span class=\"citation\">Y. Dem. II, 22ᵈ</span> top; <span class=\"citation\">Tosef. Shebi. IV, 9</span> (Var. <span dir=\"rtl\">כצת</span>; Hildesh. p. 34 <a href=\"#\" data-headword=\"בָּצַץ\">בצץ</a>).</div>","alt":[]},"4568":{"h":"בַּקָּא","r":"B01111","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (בקק <i>to enter into, search</i>, v. P. Sm. 573; cmp. <a href=\"#\" data-headword=\"בִּינָא III\"><span dir=\"rtl\">בִּינָא</span> III</a>, <a href=\"#\" data-headword=\"בִּינִיתָא\">בִּינִיתָא</a> a. <a href=\"#\" data-headword=\"פִּשְׁפָּשׁ\">פִּשְׁפָּשׁ</a>) <i>gnat</i>. <span class=\"citation\">Ḥull. 58ᵇ</span> <span dir=\"rtl\">לית ב׳ בר יומא</span> no gnat lives an entire day. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">תלו ליה לב׳ וכ׳</span> they suspended on the gnat’s proboscis sixty &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אמראי בקת׳ לבקא</span> Ar. (ed. <span dir=\"rtl\">אמרא ב׳ מבקא</span>) the she-gnat quarrelled with the he-gnat, v. <a href=\"#\" data-headword=\"מרי I\">מרי</a>.—Pl. <span dir=\"rtl\">בַּקֵּי</span>. <span class=\"citation\">Succ. 26ᵃ</span> <span dir=\"rtl\">משום ב׳</span> on account of the gnats. <span class=\"citation\">Sabb. 77ᵇ</span>, v. <a href=\"#\" data-headword=\"כַּשְׁכֵּשׁ\">כַּשְׁכֵּשׁ</a>.</div>","alt":["בַּקְּתָא"]},"4569":{"h":"בְּקָא","r":"B01112","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בק</span>, v. <a href=\"#\" data-headword=\"בַּקָּא\">preced.</a>; cmp. <span dir=\"rtl\">בצא</span>, a. <span dir=\"rtl\">בין</span>; v. <span dir=\"rtl\">בקר</span>, <a href=\"#\" data-headword=\"בָּקַשׁ\">בקש</a> &amp;c.) <i>to search, investigate, examine, find out</i>. Part. <a href=\"#\" data-headword=\"בָּקִי\">בָּקֵי</a>. <span class=\"citation\">Targ. Prov. XVII, 3</span> צרפא בקי Bxt. (ed. <a href=\"#\" data-headword=\"נקי\">נקי</a>). <span class=\"citation\">Ib. XXIV, 12</span> בָּאקֵי Ms. (Bxt. a. oth. <a href=\"#\" data-headword=\"בְּצָא\">בצי</a>; corrupt. <a href=\"#\" data-headword=\"באהי\">באהי</a>; h. text <span dir=\"rtl\">יבין</span>).—<span class=\"citation\">B. Mets. 84ᵇ</span> <span dir=\"rtl\">בְּקִי באבוך וכ׳</span> (<span class=\"citation\">Yalk. Prov. 964</span> <span dir=\"rtl\">בַּקְרִי</span>) find out what thy father is doing now. <span class=\"citation\">Pes. 3ᵇ</span> בקי מאי דיניה Ms. M. (ed. <span dir=\"rtl\">בדוק</span>) find out his ways and manners. <span class=\"citation\">Gitt. 69ᵇ</span> <span dir=\"rtl\">ליבקי וכ׳</span> let one search for the body of one who died on a Sabbath. <span class=\"citation\">Koh. R. to XI, 2</span> (read:) <span dir=\"rtl\">עד דאינון בקיין תרין חיואן וכ׳</span> (strike out <span dir=\"rtl\">אזלון בעיין … ונפקין</span></div>","alt":["בְּקִי"]},"4570":{"h":"בקוותא","r":"B01113","html":"<div class=\"sense\">, <span class=\"citation\">Y. Snh. VII, end, 25ᵈ</span>, read <a href=\"#\" data-headword=\"בַּקְרוּתָא I\">בַּקְרוּתָא</a>.</div>","alt":[]},"4571":{"h":"בַּקּוֹלְסָא","r":"B01114","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בַּקְלָסָא\">בַּקְלָסָא</a></div>","alt":[]},"4572":{"h":"בקורות","r":"B01115","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּקְרוּת\">בַּקְרוּת</a></div>","alt":["בקורת"]},"4573":{"h":"בִּקּוֹרֶת","r":"B01116","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּיקּוֹרֶת\">בִּיקּוֹרֶת</a></div>","alt":[]},"4574":{"h":"בְּקִי","r":"B01117","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּקָא\">בְּקָא</a></div>","alt":[]},"4575":{"h":"בָּקִי","r":"B01118","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בקא</span>) <i>expert, versed, familiar</i>. <span class=\"citation\">Targ. I Chr. XI, 11</span>.—<span class=\"citation\">Kidd. 10ᵇ</span> <span dir=\"rtl\">ב׳ בחדרי תורה</span> well acquainted with the chambers (intricacies) of the Law; <span class=\"citation\">Y. Keth. V, 29ᵈ</span> bot. <span dir=\"rtl\">ב׳ בסתרי וכ׳</span>. <span class=\"citation\">Snh. VII, 2</span> <span dir=\"rtl\">שלא היה ב&quot;ד ב׳</span> the court was not versed in the law. <span class=\"citation\">Yoma 49ᵃ</span> <span dir=\"rtl\">ב׳ ברפואות</span> an expert in medicine. <span class=\"citation\">Yeb. 102ᵃ</span> <span dir=\"rtl\">כלום אתה ב׳ בר׳ וכ׳</span> art thou acquainted with R. &amp;c.?; <span class=\"citation\">Tosef. ib. XII, 11</span> <span dir=\"rtl\">ב׳ היה לך בר׳ וכ׳</span> ed. Zuck. (read <span dir=\"rtl\">ב׳ הי׳ לך ר׳</span> as oth. ed.) was R. … well known to thee? <span class=\"citation\">Keth. 6ᵇ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"בְּקִיעִין\">בְּקִיאִין</a>, <a href=\"#\" data-headword=\"בְּדִיאֵי\">בְּקִיאֵי</a>. <span class=\"citation\">Targ. I Chr. XII, 32</span> (Var. <a href=\"#\" data-headword=\"בְּקִיעִין\">בקיעין</a>). <span class=\"citation\">Ḥull. 4ᵃ</span> <span dir=\"rtl\">אין ב׳ וכ׳</span> (the Samaritans) are not so well versed in the details of the Law as &amp;c. <span class=\"citation\">Gitt. 86ᵇ</span>. <span class=\"citation\">Kidd. 30ᵃ</span> <span dir=\"rtl\">אינהו ב׳ … אנן לא בְקִיאִינָן</span> they (the ancients) were versed in Biblical orthography (in <i>defective</i> and <i>plene</i>), we are not.—<i>Fem</i>. <a href=\"#\" data-headword=\"בְּקִיעָה\">בְּקִיאָה</a>. <span class=\"citation\">Ḥag. 5ᵃ</span>. [<span class=\"citation\">Targ. Y. II, Gen. XLIX, 12</span> בַּקְיִין בהלכה Ar., ed. <span dir=\"rtl\">כה׳</span>, incorr., Levita in Tishbi <span dir=\"rtl\">בְּקִיאין</span>; Y. I נקיין מן חלבא!]</div>","alt":["בָּקִיא"]},"4576":{"h":"בִּקְיָא","r":"B01119","html":"<div class=\"sense\"><i>vetch</i>, v. <a href=\"#\" data-headword=\"בִּיקְיָא\">בִּיקְיָא</a>.</div>","alt":["בִּקְיָיא"]},"4577":{"h":"בְּקִיעַ I","r":"B01120","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בקע</span>; cmp. <a href=\"#\" data-headword=\"בִּצְעָה\">בִּצְעָה</a>) <i>fissure, ditch</i>, esp. <i>small pond</i> for washing clothes. <span class=\"citation\">M. Kat. 8ᵇ</span> <span dir=\"rtl\">נברכת וב׳</span>, expl. as <span dir=\"rtl\">גיהא ובר גיהא</span> a large pond and a small pond. <span class=\"citation\">Tosef. B. Bath. I, 2</span>. Ib. <span class=\"citation\">M. Kat. I, 9</span> זו היא נ׳ … ב׳ Nibrekheth a. B’kia are the same; Y. ib. I, 80ᵈ <span dir=\"rtl\">כל שהוא תושב וכ׳</span> any permanent cut in the ground is called <a href=\"#\" data-headword=\"בְּקִיעַ I\">בקיע</a> (<i>fissure</i>, a grave, wash-pond &amp;c.). [Another opin. in Ar. <a href=\"#\" data-headword=\"ב׳\">ב׳</a> = <span dir=\"rtl\">אבן ב׳</span> <i>a flat stone</i> whereon washers beat their clothes; Y. l. c. <span dir=\"rtl\">כל שהוא וכ׳</span> any stone fixed in the ground is called a <i>b’kia</i>.—Ms. M. a. ed. Ven. <span dir=\"rtl\">נְקִיעַ</span>, v. <a href=\"#\" data-headword=\"נֶקַע\">נֶקַע</a>.]</div>","alt":[]},"4578":{"h":"בְּקִיעַ II","r":"B01121","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(<span dir=\"rtl\">בקע</span> = <span dir=\"rtl\">בקא</span>) = <a href=\"#\" data-headword=\"בָּקִי\">בָּקִיא</a>. <span class=\"citation\">Snh. 5ᵇ</span> <span dir=\"rtl\">ב׳ במומי</span> (Ms. M. <a href=\"#\" data-headword=\"פְּקִיעַ I\">פקיע</a>) an expert in judging bodily defects. <span class=\"citation\">B. Bath. 164ᵇ</span> <a href=\"#\" data-headword=\"בְּקִיעַ I\">בקיע</a> some ed. (Ms. M. <span dir=\"rtl\">בקי</span>, F. <a href=\"#\" data-headword=\"פְּקִיעַ I\">פקיע</a>).—Pl. <a href=\"#\" data-headword=\"בְּקִיעִין\">בְּקִיעִין</a>, <a href=\"#\" data-headword=\"בְּלִיעֵי\">בְּקִיעֵי</a>. <span class=\"citation\">Targ. I Chr. XII, 32</span> Var., v. <a href=\"#\" data-headword=\"בָּקִי\">בָּקִי</a>. <span class=\"citation\">Shebu. 42ᵃ</span> <span dir=\"rtl\">דכמה דנפישי בקיעי טפי</span> (some ed. <span dir=\"rtl\">בקיאי</span>, Ms. F. <a href=\"#\" data-headword=\"פ׳\">פ׳</a>) the majority of the experts are supposed to be better versed (than the minority).</div>","alt":[]},"4579":{"h":"בְּקִיעָא","r":"B01122","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בקע</span>) <i>that which is demolished by chopping</i>. <span class=\"citation\">Lev. R. s. 19</span>, v. <a href=\"#\" data-headword=\"*אָלִיס\">אָלִיס</a>.</div>","alt":[]},"4580":{"h":"בְּקִיעָה","r":"B01123","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בקע</span>) </div><div class=\"sense\"><b>1)</b> <i>cleaving, cleft; that which is cloven, a log.</i> Pl. <span dir=\"rtl\">בְּקִיעוֹת</span>. <span class=\"citation\">Koh. R. to II, 23</span> <span dir=\"rtl\">בקע לי שתי ב׳</span> chop for me two logs; (<span class=\"citation\">Gen. R. s. 27</span> <span dir=\"rtl\">בקעיות</span>, v. <a href=\"#\" data-headword=\"בְּקַעַת\">בְּקַעַת</a>). <span class=\"citation\">Koh. R. to X, 9</span>; <span class=\"citation\">Gen. R. s. 55</span>, end <span dir=\"rtl\">בשכר שתי ב׳ שבקע וכ׳</span> as a reward for the two pieces of wood which Abraham chopped (<span class=\"citation\">Gen. XXII, 3</span>).</div><div class=\"sense\"><b>—2)</b> <i>crossing, passing over</i>. <span class=\"citation\">Sabb. 101ᵃ</span> <span dir=\"rtl\">בְּקִיעַת דגים</span> the crossing of fish under the ship.</div>","alt":[]},"4581":{"h":"בְּקִיעִין","r":"B01124","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>B’kiin</i>, (<i>K’far</i>) <i>P’kiin</i>, modern <i>Fukin</i>, a place in Southern Palestine between Lydda and Jabneh, residence of R. Joshua. <span class=\"citation\">Y. Ḥag. I, beg. 75ᵈ</span>. <span class=\"citation\">Snh. 32ᵇ</span>; a. fr.</div>","alt":["פְּקִיעִין","(כפר)"]},"4582":{"h":"בְּקִיקָא","r":"B01125","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בקק</span>; cmp. <span dir=\"rtl\">בקע</span>, <a href=\"#\" data-headword=\"בְּקִיעָא\">בקיעא</a>) <i>a broken piece, potsherd.</i> Pl. <a href=\"#\" data-headword=\"בְּקִיעִין\">בְּקִיקִין</a>. <span class=\"citation\">Targ. Y. Ex. XII, 12</span>; <span class=\"citation\">Num. XXXIII, 4</span>.</div>","alt":[]},"4583":{"h":"בקלאנין","r":"B01126","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to I, 12</span> <span dir=\"rtl\">ב׳ בוקינוס וכ׳</span>, read <span dir=\"rtl\">קַלָּאנִין בבוק׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"קַלָּן\">קַלָּן</a>; v. <span class=\"citation\">Yalk. ib. 983</span>.</div>","alt":[]},"4584":{"h":"*בַּקְלָסָא","r":"B01127","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">בקלס</span>, <span dir=\"rtl\">בקל</span> with <a href=\"#\" data-headword=\"ס\">ס</a> intens., as <a href=\"#\" data-headword=\"בַּלְעֵס\">בלעס</a> a. <span dir=\"rtl\">בלע</span>; cmp. Syr. <span dir=\"rtl\">בוקלא</span> P. Sm. 474; √<span dir=\"rtl\">בק</span>, cmp. <a href=\"#\" data-headword=\"בְּקַעַת\">בקעת</a>) <i>club, shepherd’s crook</i>. <span class=\"citation\">Gen. R. s. 38</span> <span dir=\"rtl\">קם נסב בקלסיה</span> (or <a href=\"#\" data-headword=\"*בַּקְלָסָא\">בקלסא</a>) he stood up, took (his) crook and broke the idols, <span dir=\"rtl\">ויהב בוקלסא וכ׳</span> and placed the crook into the hand of the largest of them (Rashi <span dir=\"rtl\">בולקסא</span>, corr. acc.).—Pl. <span dir=\"rtl\">בַּקְלָסֵי</span>, <span dir=\"rtl\">(<a href=\"#\" data-headword=\"בַּקּוֹלְסָא\">בַּקּוֹלְסֵי</a>) <a href=\"#\" data-headword=\"*בַּקְלָסָא\">בּוּקְלָסֵי</a></span>. <span class=\"citation\">Zeb. 105ᵃ</span> נקיטי לה בבו׳ Rashi (ed. <span dir=\"rtl\">בבקולסי</span>; Ms. M. <span dir=\"rtl\">בקלסי</span>, Ar. s. v. <a href=\"#\" data-headword=\"קָלַס I\">קלס</a>, <span dir=\"rtl\">בקולסי</span>, Ms. R. 1 <span dir=\"rtl\">בקינסי</span>, Ms. K. <span dir=\"rtl\">בקונסי</span>) they seize it (the sacrifice to be burnt) with crooks (while standing outside).</div>","alt":["בּוּקְלָסָא"]},"4585":{"h":"בָּקַע","r":"B01128","html":"<div class=\"sense\"> , v. <a href=\"#\" data-headword=\"בְּקָא\">בְּקָא</a>) </div><div class=\"sense\"><b>1)</b> <i>to split, chop; to break through</i>. <span class=\"citation\">B. Mets. 99ᵃ</span> <span dir=\"rtl\">בָּ׳ בו</span>; (<span class=\"citation\">Kidd. 47ᵇ</span> <a href=\"#\" data-headword=\"בָּקַע\">בִּיקַּע</a>) if he chopped wood with it. <span class=\"citation\">Gen. R. s. 55</span>, end; <span class=\"citation\">Koh. R. to X, 9</span>; <span class=\"citation\">II, 23</span>, v. <a href=\"#\" data-headword=\"בְּקִיעָה\">בְּקִיעָה</a>. <span class=\"citation\">Ex. R. s. 21</span> אני בוֹקֵעַ להם וכ׳ I am going to split the sea for them; a. fr.—<span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">בקעו בחיילותיו וכ׳</span> broke through the lines of N.’s armies; <span class=\"citation\">Y. Taan. IV, 69ᵇ</span> top <span dir=\"rtl\">ברחו לתוך</span>.</div><div class=\"sense\"><b>—2)</b> <i>to cross, make a short cut, pass over</i>. <span class=\"citation\">Y. Pes. I, 27ᵇ</span> bot. <span dir=\"rtl\">חצר שהרבים בּוֹקְעִין וכ׳</span> a court which people use for crossing. <span class=\"citation\">Erub. 16ᵇ</span>; <span class=\"citation\">Sabb. 101ᵇ</span> (a low wall) <span dir=\"rtl\">שהגדיים וכ׳ ב׳</span> over which the kids pass; v. <a href=\"#\" data-headword=\"בִּקְעָה\">בִּקְעָה</a>.</div><div class=\"sense\"><b>—3)</b>  (cmp. <a href=\"#\" data-headword=\"בִּצְבֵּץ\">בִּצְבֵּץ</a>) <i>to break through the ground</i>, esp. as a legal fiction for a levitical impurity the cause of which is underground, but which affects the things above and beneath. Ohol. VI, 6 <span dir=\"rtl\">טומאה בּוֹקַעַת וכ׳</span> the impurity breaks through the ground and rises, and breaks through and goes down; a. fr.—<span class=\"citation\">Koh. R. III, 16</span> <span dir=\"rtl\">היה הדם בו׳ ועולה</span> the blood broke through and rose. <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 45</span> <span dir=\"rtl\">ב׳ את הצור</span>, <span dir=\"rtl\">ב׳ בצור</span> break through (take root in) the rock; a. fr.</div><div class=\"sense\"><b>Nif. נִבְקַע</b> <div class=\"sense\"><i>to be split, to burst open</i>. Ib. <span dir=\"rtl\">הסיפין נבקעין וכ׳</span> the door sells were burst before them. Ib. <span dir=\"rtl\">נ׳ הספל מאליו</span> the vessel went to pieces of itself. <span class=\"citation\">Gen. R. s. 55</span>, end <span dir=\"rtl\">זכה להִבָּקַע הים וכ׳</span> he was rewarded by the sea being divided before the children of Israel. <span class=\"citation\">Ḥull. 14ᵇ</span> <span dir=\"rtl\">שמא יִבָּקַע הנוד</span> the wine bottle may burst; a. fr.</div></div><div class=\"sense\"><b>Pi. בִּקַּע  בִּיקַּע</b> <div class=\"sense\"><b>1)</b> <i>to split, chop, tear</i>. <span class=\"citation\">Kidd. 47ᵇ</span>, v. supra. Y. Bets. I, 60ᵃ bot.; Y. Ab. Zar. II, 41ᶜ bot. <span dir=\"rtl\"><span dir=\"rtl\">שביקעו</span> (<span dir=\"rtl\">שבקעו</span>) <span dir=\"rtl\">להם וכ׳</span></span> of whose flocks the wolves had torn more than &amp;c. <span class=\"citation\">Bets. IV, 3</span> <span dir=\"rtl\">אין מְבַקְּעִין וכ׳</span> one must not split woods (on Holy Days) etc. <span class=\"citation\">Sifré Deut. 183</span> (ref. to <span class=\"citation\">Deut. XIX, 5</span>) <span dir=\"rtl\">מן העץ המְבַקֵּעַ</span> from the <i>splitting</i> wood (the handle), opp. <span dir=\"rtl\">העץ המִתְבַּקֵּעַ</span> the <i>split</i> wood (the tree). Tanḥ. Vayetse 9 <span dir=\"rtl\">בַּקְּעִי וכ׳</span> chop thou &amp;c.—Part. pass. <span dir=\"rtl\">מְבוּקָּע</span>. <span class=\"citation\">Ab. Zar. 65ᵇ</span> <span dir=\"rtl\">מְבוּקָּעוֹת</span> grapes burst open.</div><div class=\"sense\"><b>—2)</b> <i>to jam in, wedge</i>. <span class=\"citation\">Sabb. 67ᵇ</span> <span dir=\"rtl\">המְבַקַּעַת ביצים</span> (Rashi Var. <span dir=\"rtl\">המקבעת</span>, Ms. M. <span dir=\"rtl\">עצים</span>) one who squeezes egg-shells &amp;c. (a superstitious practice; <span class=\"citation\">Tosef. ib. VI</span> (<span class=\"citation\">VII), 18</span> <span dir=\"rtl\">הנותנת בצים … בכותל</span>).</div></div><div class=\"sense\"><b>Hif. הִבְקִיעַ</b> <div class=\"sense\"><b>1)</b> <i>to cut, clear.</i> <span class=\"citation\">Shebi. IV, 5</span> <span dir=\"rtl\">המַבְקִיעַ בזתים וכ׳</span> he who cuts olive-trees down (in the Sabbath year) must not cover the stump with ground.</div><div class=\"sense\"><b>—2)</b> <i>to lead a line crosswise</i>. Y. Kil. III, 28ᵈ top <span dir=\"rtl\">להַבְקִיעַ וכ׳</span> to plant four rows across a valley from end to end.</div></div><div class=\"sense\"><b>Hithpa. הִתְבַּקֵּעַ</b> <div class=\"sense\"><i>to be split; to burst, break</i>. <span class=\"citation\">Sifré Deut. 183</span>, v. supra.—<span class=\"citation\">Sabb. XVI, 5</span>. <span class=\"citation\">Cant. R. to VI, 4</span>.</div></div>","alt":[]},"4586":{"h":"בֶּקַע","r":"B01129","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>a split</i>,] <i>beka</i>, a<i> weight</i> and a <i>coin</i>, equal to half a Shekel. <span class=\"citation\">Gen. R. s. 84</span>; a. e.</div>","alt":[]},"4587":{"h":"בִּקְעָא","r":"B01130","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּקְעֲתָא\">בִּקְעֲתָא</a></div>","alt":[]},"4588":{"h":"בִּקְעָה","r":"B01131","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>cut, notch</i>, whence <i>valley, plane; a group of fields;</i> v. <a href=\"#\" data-headword=\"בָּאגָא\">בָּאגִא</a>; esp. <i>a short cut</i> for farm-laborers &amp;c. <span class=\"citation\">Toh. VI, 7</span>, a. e. <span dir=\"rtl\">הב׳ בימות החמה וכ׳</span> the path through the fields in summer-time (when used by field laborers) is considered as private ground with regard to Sabbath laws, as public with regard to levitical purity. <span class=\"citation\">B. Bath. 61ᵇ</span> when one sells … a field <span dir=\"rtl\">בב׳ גדולה</span> within a large group of fields (all belonging to the seller). <span class=\"citation\">Ib.</span> (in a place) where they call <span dir=\"rtl\">לשדה ש׳ ולב׳ ב׳</span> a field <i>sadeh</i> and an estate <i>bikah;</i> a. fr.—Trnsf. <i>an unguarded field, moral danger</i>. <span class=\"citation\">Erub. 6ᵃ</span>; <span class=\"citation\">100ᵇ</span>; <span class=\"citation\">Ḥull. 110ᵃ</span> רב ב׳ מצא וכ׳ Rab found an unguarded field and fenced it in, i.e. found people transgressing the law in ignorance and instituted preventive regulations.—Pl. <span dir=\"rtl\">בְּקָעוֹת</span>. <span class=\"citation\">Gen. R. s. 98</span>.—2) (constr.) <a href=\"#\" data-headword=\"בְּקַעַת\">בִּקְעַת</a> pr. n. pl. <i>Valley of</i>—, as <span dir=\"rtl\">ב׳ יזרעאל</span>, <span dir=\"rtl\">ב׳ ידים</span> &amp;c., for all of which see the respective determinants.</div>","alt":[]},"4589":{"h":"בקעי","r":"B01132","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ned. IV, beg. 38ᶜ</span>, v. <a href=\"#\" data-headword=\"בִּיקּוּעַ\">בִּיקּוּעַ</a></div>","alt":[]},"4590":{"h":"בְּקַעַת","r":"B01133","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">בקע</span>) </div><div class=\"sense\"><b>1)</b> <i>chip, piece of wood; log to be chopped</i>. <span class=\"citation\">B. Kam. 32ᵇ</span> <span dir=\"rtl\">נתזה ב׳ וכ׳</span> a chip slipped out (of the carpenter’s hand) and struck his face; Y. ib. III, end, 3ᵈ. Y. Macc. II, 31ᶜ bot. <span class=\"citation\">Y. Bets. IV, 62ᶜ</span> bot. <span dir=\"rtl\">אין מכבין את הב׳</span> you must not extinguish the log; v. <a href=\"#\" data-headword=\"כָּסַס\">כָּסַס</a>. <span class=\"citation\">Sabb. 29ᵃ</span> top; a. fr.—Pl. (cmp. pl. of <a href=\"#\" data-headword=\"כְּנֶסֶת\">כְּנֶסֶת</a>) <span dir=\"rtl\">בִּקְעִיּוֹת</span>. <span class=\"citation\">Ḥull. 37ᵇ</span> <span dir=\"rtl\">אפי׳ אוכלת ב׳</span> even if strong enough to bite wood. <span class=\"citation\">Koh. R. to III, 17</span> (a gloss expl. <span dir=\"rtl\">גזירין</span>). <span class=\"citation\">Gen. R. s. 27</span>, v. <a href=\"#\" data-headword=\"בְּקִיעָה\">בְּקִיעָה</a>.</div><div class=\"sense\"><b>—2)</b>  dial. for <a href=\"#\" data-headword=\"פְּקַעַת\">פְּקַעַת</a> q. v.</div>","alt":[]},"4591":{"h":"בְּקַעֲתָא","r":"B01134","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Num. XIX, 6</span>.</div>","alt":["בִּקְעֲ׳"]},"4592":{"h":"בַּקְעֲתָא","r":"B01135","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. Gen. XI, 2</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"בַּקְעֲתָא\">בַּקְעָתָא</a>.—<span class=\"citation\">Y. Shebi. III, 34ᶜ</span> top, v. <a href=\"#\" data-headword=\"פְּקוּעָה\">פְּקוּעָה</a>.—Constr. <a href=\"#\" data-headword=\"בְּקַעַת\">בַּקְעַת</a>, pr. n. <i>Valley of</i> … <span class=\"citation\">Gen. R. s. 10</span>; a. fr.</div>","alt":["בִּקְעֲ׳","בִּקְעָא"]},"4593":{"h":"בָּקַר","r":"B01136","html":"<div class=\"sense\"> , v. <span dir=\"rtl\">בקע</span>) <i>to enter into, to clear, split;</i> whence </div><div class=\"sense\"><b>1)</b>  (= <a href=\"#\" data-headword=\"בְּעַר I\">בער</a>) <i>to eat up</i>. Denom. <a href=\"#\" data-headword=\"בָּקָר\">בָּקָר</a> (= <a href=\"#\" data-headword=\"בְּעִיר\">בְּעִיר</a>).</div><div class=\"sense\"><b>—2)</b>  (= <a href=\"#\" data-headword=\"בְּעַר I\">בער</a>) <i>to break forth, shine</i>. Denom. <a href=\"#\" data-headword=\"בֹּקֶר\">בֹּקֶר</a>.</div><div class=\"sense\"><b>Pi. בִּיקֵּר  בִּקֵּר</b> <div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to enter into, examine, search, distinguish</i> (cmp. <a href=\"#\" data-headword=\"בִּין\">בִּין</a>). <span class=\"citation\">Keth. 106ᵃ</span> <span dir=\"rtl\">מְבַקְּרֵי מומין</span> those entrusted with the examination of sacrificial animals. Y. Bets. II, 61ᶜ top <span dir=\"rtl\">ובִיקְּרָן ממומן</span> and had them examined (and declared free) from bodily defects. <span class=\"citation\">Ḥag. 9ᵇ</span> <span dir=\"rtl\">אין אומרים בַּקְּרוּ וכ׳</span> we do not say, Examine ye a camel, a swine &amp;c. (i.e. only the deeds of distinguished persons are scrutinized); a. fr.—<i>Part. pass</i>. <span dir=\"rtl\">מְבוּקָּר</span> <i>examined and found fit</i>. Y. Ber. IV, 7ᵇ top <span dir=\"rtl\">טליים מְבוּקָּרִים</span> lambs which passed examination.</div><div class=\"sense\"><b>—2)</b> <i>to inquire after one’s health, to visit the sick</i>. <span class=\"citation\">Ned. IV, 4</span> (<span class=\"citation\">38ᵇ</span>). <span dir=\"rtl\">ונכנס לְבַקְּרוֹ</span> and comes to see him. <span class=\"citation\">Snh. 68ᵃ</span>; a. v. fr. [Ruth. R. to II, 15, v. infra.]</div></div><div class=\"sense\"><b>Hithpa. הִתְבַּקֵּר</b> <div class=\"sense\">, <i>Nithpa</i>. <a href=\"#\" data-headword=\"בָּצַר\">נִתְבַּקֵּר</a> </div><div class=\"sense\"><b>1)</b> <i>to be examined</i>. <span class=\"citation\">Gen. R. s. 81</span> <span dir=\"rtl\">פנקסו נִתְבַּקְּרָה</span> his account is examined (his sins visited); Tanḥ. Vayishlaḥ 8 <span dir=\"rtl\">מִתְבַּקֶּרֶת</span>. <span class=\"citation\">Gen. R. s. 84</span>, read with <span class=\"citation\">Yalk. Gen. 141</span> <span dir=\"rtl\">נתב׳ פנקסי</span> my account &amp;c. </div><div class=\"sense\"><b>2)</b> <i>to be visited, attended to</i>. <span class=\"citation\">Num. R. s. 18</span> as all sick persons <span dir=\"rtl\">מִתְבַּקְּרִין</span> are tended (by physicians).</div></div><div class=\"sense\"><b>Hif. הִבְקִיר</b> <div class=\"sense\"> (Y. Dial. for <a href=\"#\" data-headword=\"פָּקַר\">הִפְקִיר</a>, v. <a href=\"#\" data-headword=\"פָּקַר\">פָּקַר</a>; v. <a href=\"#\" data-headword=\"בְּקַר\">next w.</a>) <i>to give free, to resign ownership, to declare a property ownerless</i>. Y. Ned. IV, 38ᵈ; Y. Peah V, beg. 19ᵇ [read:] <span dir=\"rtl\">כיון שאדם מַבְקִיר דבר יצא מרשותו</span> as soon as one declares a thing to be free, it has gone out of his control; Y. Dem. III, 23ᵇ bot. <span dir=\"rtl\">כיון שאדם מ׳ … ויצא … הבקירו הבקר</span> as soon as one gives a thing free and it has left his possession, his act is valid; a. fr. [Ruth. R. to II, 15 <span dir=\"rtl\">מבקר</span>, <span dir=\"rtl\">מבדר</span>, prob. <span dir=\"rtl\">מבקיר</span>; v. <a href=\"#\" data-headword=\"*בָּדַר\">בָּדַר</a>.]</div></div><div class=\"sense\"><b>Hof. הוּבְקַר</b> <div class=\"sense\"><i>to be declared free, to be free</i>. Y. Peah VI, 19ᶜ top.—Part. <span dir=\"rtl\">מוּבְקָר</span> Ib. 19ᵇ bot. <span dir=\"rtl\">שדי מוּבְקֶרֶת וכ׳</span> (<span class=\"citation\">Tosef. Maasr. III, 11</span>. <span dir=\"rtl\">הרי … מופ׳</span>) my field shall be free for one day &amp;c.; a. e.</div></div>","alt":[]},"4594":{"h":"בְּקַר","r":"B01137","html":"<div class=\"sense\">—<i>Pa.</i> <a href=\"#\" data-headword=\"בַּקָּר\">בַּקַּר</a> </div><div class=\"sense\"><b>1)</b> <i>to search, examine</i>. <span class=\"citation\">Targ. O. Lev. XIII, 36</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to clear, glean</i>. <span class=\"citation\">Targ. Y. I Deut. XXIV, 20</span> (<span class=\"citation\">II</span> <span dir=\"rtl\">תתב׳</span>, read <span dir=\"rtl\">תבקרון</span>, h. text <span dir=\"rtl\">תפאר</span>).</div><div class=\"sense\"><b>—3)</b> <i>to let the herd graze</i> (cmp. <a href=\"#\" data-headword=\"בְּעַר I\">בער</a>), <i>to drive unmuzzled animals</i>. <span class=\"citation\">Targ. Y. Gen. XIII, 7</span>.</div><div class=\"sense\"><b>—4)</b> <i>to visit the sick</i>. <span class=\"citation\">Targ. Y. Ex. XVIII, 20</span>; a. e.—Y. Sabb. VI, 8ᶜ bot.; a. fr.</div><div class=\"sense\"><b>—5)</b>  (= <a href=\"#\" data-headword=\"בָּקַר\">preced.</a> Hif.) <i>to abandon, leave unclaimed, declare free</i>. <span class=\"citation\">Targ. Y. Ex. XXIII, 11</span> Ar. (some ed. <span dir=\"rtl\">ותפקד</span>, read <span dir=\"rtl\">ותפקר</span>). Y. Shebi. IX, 39ᵃ top <span dir=\"rtl\">וַאֲבַקְּרָה קומיהון</span> and I will declare it free goods in their presense. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ומְבַקְּרִין ליה</span> and declare ye it free property.</div>","alt":[]},"4595":{"h":"בֹּקֶר","r":"B01138","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"בָּקַר\">בָּקַר</a>) <i>morning, early day;</i> metaph. <i>light, salvation</i>. <span class=\"citation\">Y. Taan. I, 64ᵃ</span> top <span dir=\"rtl\">ב׳ לצדיקים וכ׳</span> a morning for the righteous, a night for the wicked. Ruth. R. to III, 13 בַּבּ׳ בעולם וכ׳ ‘in the morning’—that means in the world which is all-good. Esth. R., introd. (ref. to <span class=\"citation\">Deut. XXVIII, 67</span>) <span dir=\"rtl\">בבָקְרָהּ של בבל וכ׳</span> in the morning (ascendancy) of Babel thou shalt say, Oh that her evening (downfall) would come! <span class=\"citation\">Gen. R. s. 21</span> (ref. to <span class=\"citation\">Dan. VIII, 14</span>) <span dir=\"rtl\">לִכְשֶׁיֵּעָשֶׂה בָּקְרָן וכ׳</span> when the morning of the (persecuting) nations shall become evening, and the evening of Israel morning; Tanḥ. ed. Bub. <span class=\"citation\">B’resh. 23</span>. Mekh. Bo, s. 6 in order to define it: <span dir=\"rtl\">לבָקְרוֹ של ב׳</span> at the very break of morning; <span class=\"citation\">Y. Ber. I, 2ᶜ</span> top.—Pl. <a href=\"#\" data-headword=\"בְּתָרִים\">בְּקָרִים</a>. <span class=\"citation\">Yoma 33ᵇ</span> <span dir=\"rtl\">חלקהו לשני ב׳</span> divide the acts prescribed into two mornings, i.e. let another act be inserted between. <span class=\"citation\">Ber. 27ᵃ</span> <span dir=\"rtl\">חלקהו לשני ב׳</span> take only one half of the morning hours. <span class=\"citation\">Y. Pes. V, 31ᵈ</span> top <span dir=\"rtl\">אית לך מימר תמן בין הַבְּקָרַיִם</span> then it ought to have read there <i>ben hab-b’karaim</i> (as you read <span dir=\"rtl\">בין הערבים</span>, Du.).</div>","alt":["בּוֹקֶר"]},"4596":{"h":"בָּקָר","r":"B01139","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"בָּקַר\">בָּקַר</a>) <i>a beef;</i> (collect.) <i>oxen, cattle</i>. Sifra <span class=\"citation\">Vayikra ch. II, Par. 2</span> <span dir=\"rtl\">אין לך בבהמה אלא ב׳ וכ׳</span> under <i>b’hemah</i> for offerings (<span class=\"citation\">Lev. I, 2</span>) are meant only beeves and sheep; a. fr. <a href=\"#\" data-headword=\"בַּטִּיחַ\">בן ב׳</a> <i>young cattle, calf</i>. Ib.; a. fr.—רועי ב׳ <i>herders</i> (suspected of feeding upon other people’s fields). <span class=\"citation\">Snh. III, 2</span> <span dir=\"rtl\">נאמנין עלי שלשה ר׳ ב׳</span> (if one says) I have faith in (the arbitration of) three herders.</div>","alt":[]},"4597":{"h":"בַּקָּר","r":"B01140","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּקָר\">preced.</a>) <i>neat-herd, cow-herd; cattle-driver</i>. <span class=\"citation\">Y. Bets. V, 63ᵇ</span>, v. <a href=\"#\" data-headword=\"רֶגֶל\">רֶגֶל</a>.</div>","alt":[]},"4598":{"h":"בַּקָּרָא I","r":"B01141","html":"<div class=\"sense\"> <span class=\"citation\">B. Mets. 42ᵇ</span>.—Pl. <span dir=\"rtl\">בַּקָּרֵי</span>. <span class=\"citation\">Sot. 48ᵃ</span> <span dir=\"rtl\">זמרא דב׳</span> the song of the drivers (at ploughing).</div>","alt":[]},"4599":{"h":"*בַּקָּרָא II","r":"B01142","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">בַּקָּרִין</span> (v. <a href=\"#\" data-headword=\"בָּקַר\">בָּקַר</a>, cmp. b. h. <a href=\"#\" data-headword=\"בְּעַר I\">בַּעַר</a> a. <a href=\"#\" data-headword=\"בּוֹר II\"><span dir=\"rtl\">בּוֹר</span> I</a>) [<i>empty</i>,] <i>light-minded, thoughtless</i>. <span class=\"citation\">Targ. Jud. IX, 4</span> Ar. a. Kimḥi (ed. <span dir=\"rtl\">בסירין</span>).</div>","alt":[]},"4600":{"h":"בַּקְרָא","r":"B01143","html":"<div class=\"sense\"> c. (<span dir=\"rtl\">בקר</span>) <i>herd</i>. <span class=\"citation\">Targ. Y. Deut. VII, 13</span> <span dir=\"rtl\">בַּקְרַת תוריך</span> (h. text <span dir=\"rtl\">שגר אלפיך</span>). <span class=\"citation\">B. Mets. 84ᵃ</span> <span dir=\"rtl\">ב׳ דתורי</span> a herd of oxen, (Var. <a href=\"#\" data-headword=\"פַּדָּן\">פדנא</a>, v. Rashia. l. a. Rabb. D. S. a. l. note 2).—Pl. m. <a href=\"#\" data-headword=\"בַּלְנְרִין\">בַּקְרִין</a>, constr. <span dir=\"rtl\">בַּקְרֵי</span>. Targ. O. Deut. l. c.; Targ. ib. XXVIII, 4.—Fem. <a href=\"#\" data-headword=\"בַּקְרָא\">בַּקְרָן</a>. <span class=\"citation\">Targ. Joel I, 18</span>; <span class=\"citation\">Is. VII, 25</span>.</div>","alt":[]},"4601":{"h":"בַּקְרוּת","r":"B01144","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּקָר\">בָּקָר</a>) <i>cattle-yard, cattle-farm, stock of cattle</i>. <span class=\"citation\">M. Kat. 12ᵃ</span>; <span class=\"citation\">Tosef. ib. II, 11</span> <a href=\"#\" data-headword=\"בִּיקּוֹרֶת\">ביקורת</a> (Var. <span dir=\"rtl\">בקירות</span>, <a href=\"#\" data-headword=\"בַּקְרוּת\">בקרות</a>); <span class=\"citation\">Y. Pes. IV, 31ᵇ</span> top <a href=\"#\" data-headword=\"בקורות\">בקורת</a>. <span class=\"citation\">Y. Yeb. IV, 6ᵃ</span> bot.; <span class=\"citation\">Y. Nidd. I, 49ᵇ</span> top; <span class=\"citation\">Gen. R. s. 20</span> [read:] <span dir=\"rtl\"><span dir=\"rtl\">בקרות של בית אנטונינוס היתה עוֹבֶרֶת והרביעו</span> (<a href=\"#\" data-headword=\"שְׁוָורִים\">שוורים</a>) <span dir=\"rtl\">ממנה בַקְרוּת של בית רבי</span></span> the herd of the estate of A. passed by and (some oxen) thereof covered the herd of Rabbi’s estate; [perhaps the second <a href=\"#\" data-headword=\"בַּקְרוּת\">בקרות</a> is to be read <a href=\"#\" data-headword=\"בַּקְרוּת\">בְּקָרוֹת</a> fem. pl. of <span dir=\"rtl\">בִּקְרָה</span>; v. Var. lect. in l. c.]</div>","alt":[]},"4602":{"h":"בַּקְרוּתָא I","r":"B01145","html":"<div class=\"sense\"><span class=\"citation\">Lam. R. to I, 9</span> <span dir=\"rtl\">חד בענא וחד בב׳</span> one is employed in the fold and one in the cattle-farm. <span class=\"citation\">Y. Snh. VII, 25ᵈ</span> bot. <span dir=\"rtl\">גנב עגל מן בקוותא וכ׳</span> (corr. … <span dir=\"rtl\">מן בקר׳ ואייתיה ליה</span>) he stole a calf from the yard and brought it to him.</div>","alt":[]},"4603":{"h":"בַּקְרוּתָא II","r":"B01146","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*בַּקָּרָא II\"><span dir=\"rtl\">בַּקָּרָא</span> II</a>) <i>levity, thoughtlessness</i>. <span class=\"citation\">Targ. Jer. XXIII, 32</span>. <span class=\"citation\">Targ. I Sam. XVII, 28</span>.</div>","alt":["בַּקְרָנוּתָא"]},"4604":{"h":"בַּקְרַת","r":"B01147","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּקְרָא\">בַּקְרָא</a></div>","alt":[]},"4605":{"h":"בָּקַשׁ","r":"B01148","html":"<div class=\"sense\"> , v. <span dir=\"rtl\">בקא</span>; corresp. to ch. <a href=\"#\" data-headword=\"בעי\">בעי</a>); <i>Pi.</i> <span dir=\"rtl\">בִּיקֵּשׁ</span>, <a href=\"#\" data-headword=\"בָּקַשׁ\">בִּקֵּשׁ</a> <i>to seek, desire, beg, ask</i>. <span class=\"citation\">Kidd. 65ᵃ</span> <span dir=\"rtl\">מְבַקְּשִׁין וכ׳</span> the court begs him to give her a letter of divorce, opp. to <span dir=\"rtl\">כופין</span>. <span class=\"citation\">Ber. 12ᵇ</span> <span dir=\"rtl\">בִּקְּשׁוּ לקבוע וכ׳</span> they (the Rabbis) intended to insert the chapter about Balak &amp;c. <span class=\"citation\">Gen. R. s. 84</span> <span dir=\"rtl\">ב׳ לישב וכ׳</span> he intended to live in peace; a. fr.—ב׳ רחמים <i>to pray</i> (for mercy), v. <a href=\"#\" data-headword=\"בעי\">בעי</a>. Ber. l. c. <span class=\"citation\">B. Bath. 91ᵇ</span>; a. fr.</div><div class=\"sense\"><b>Hithpa. הִתְבַּקֵּשׁ</b> <div class=\"sense\">, <i>Nithpa</i>. <span dir=\"rtl\">נִתְבַּקֵּשׁ</span> <i>to be sought, to be hunted for</i> (by detectives); <i>to be summoned</i>. <span class=\"citation\">Taan. 29ᵃ</span> (a disguised warning given to R. Gamliel) <span dir=\"rtl\">בעל החוטם מִתְבַּקֵּשׁ</span> the well-known man is wanted; v. <a href=\"#\" data-headword=\"חוֹטָם\">חוֹטֶם</a>. <span class=\"citation\">B. Mets. 86ᵃ</span>, v. <a href=\"#\" data-headword=\"יְשִׁיבָה\">יְשִׁיבָה</a>.</div></div>","alt":[]},"4606":{"h":"בַּקָּשָׁה","r":"B01149","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"בָּקַשׁ\">preced.</a>) <i>desire, prayer</i>. <span class=\"citation\">Ned. XI, 12</span> <span dir=\"rtl\">דרך ב׳</span> in the way of a request (to give a divorce, v. <a href=\"#\" data-headword=\"בָּקַשׁ\">preced.</a>). <span class=\"citation\">Ber. 9ᵃ</span>, a. fr. <span dir=\"rtl\">אין נא אלא לשון ב׳</span> the word <a href=\"#\" data-headword=\"נָא I\">נָא</a> in the Bible means prayer (I pray &amp;c.). <span class=\"citation\">Ib. 57ᵃ</span> <span dir=\"rtl\">תלויה בַקָּשָׁתוֹ</span> his prayer is held in suspense (its fulfillment is doubtful).—בב׳ ממך <i>I pray thee</i>, v. <a href=\"#\" data-headword=\"בָּעוּ\">בָּעוּ</a>. <span class=\"citation\">Ib. 9ᵃ</span>. <span class=\"citation\">Gen. R. s. 75</span> end; a. fr.—Pl. <span dir=\"rtl\">בַּקָּשֹׁות</span></div>","alt":[]},"4607":{"h":"בִּקְתָא","r":"B01150","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <span dir=\"rtl\">בקעתא</span>, v. <a href=\"#\" data-headword=\"בָּאגָא\">בָּאגָא</a> a. <a href=\"#\" data-headword=\"בִּקְעָה\"><a href=\"#\" data-headword=\"בִּקְעָה\">בִּקְעָה</a>)</a><i>valley, short cut; group of fields</i>. <span class=\"citation\">Ber. 34ᵇ</span> bot. I consider him arrogant <span dir=\"rtl\">מאן דמצלי בב׳</span> (Ms. M. a. Ar. <span dir=\"rtl\">בפִקְתָא</span> q. v.) who prays in a valley (where people pass by). <span class=\"citation\">Keth. 54ᵃ</span>; <span class=\"citation\">103ᵃ</span> בביתי ולא בביקתי ‘in my house’ (‘as long as you will spend your widowhood in my house’—the marriage contract reads) but not in my estate, i.e. she must be content to live in her late husband’s house with his heirs, but she cannot claim a separate residence. [Comment. <span dir=\"rtl\">בקתי</span> = <span dir=\"rtl\">בי עקתי</span> house of my distress, narrow house, i.e. when there is no room for her and the heirs, she loses her claims, v. <span class=\"citation\">Sabb. 77ᵇ</span>, etymol. of <a href=\"#\" data-headword=\"ב׳\">ב׳</a> = <span dir=\"rtl\">בי עקתא</span> narrow place.]—<span dir=\"rtl\">בר בי׳</span> (<a href=\"#\" data-headword=\"בַּת I\">בת</a>) one of the same rural community; trnsf. <i>of the same class</i> or <i>category</i>;<i> neighbor</i>. <span class=\"citation\">Men. 24ᵇ</span> <span dir=\"rtl\">כולהו בני ב׳</span> they all belong together. <span class=\"citation\">Meïl. 17ᵇ</span> <span dir=\"rtl\">בני חדא ב׳</span> of the same category.—<span class=\"citation\">Yeb. 84ᵃ</span> <span dir=\"rtl\">בת בי׳</span> (ed. <a href=\"#\" data-headword=\"בּוּקְתָא\">בּוּקְתָא</a>) a parallel case stated immediately after.</div>","alt":["בִּיקְתָא"]},"4608":{"h":"בַּקְּתָא","r":"B01151","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּקָּא\">בַּקָּא</a></div>","alt":[]},"4609":{"h":"בַּר I","r":"B01152","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>empty, open</i>] </div><div class=\"sense\"><b>1)</b> <i>uncultivated ground, forest, prairie;</i> opp. <span dir=\"rtl\">יישוב</span>. <span class=\"citation\">Kil. VIII, 6</span>. <span class=\"citation\">Ḥull. 80ᵃ</span> <span dir=\"rtl\">שור הבר</span> the ox of the prairie, <i>buffalo</i>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">איל הב׳</span> forest ram. <span class=\"citation\">Y. Sabb. XIV, 14ᵇ</span> bot. <span dir=\"rtl\">חזיר של ב׳</span> wild swine.</div><div class=\"sense\"><b>—2)</b> <i>clear, visible</i>, whence <i>the outside, surface</i>, opp. <a href=\"#\" data-headword=\"תּוֹךְ I\">תוך</a>. <span class=\"citation\">Yoma 72ᵇ</span> a scholar <span dir=\"rtl\">שאין תוכו כבָרוֹ</span> whose inside is not as his outside (who is insincere); <span class=\"citation\">Ber. 28ᵃ</span>. <span class=\"citation\">Y. Pes. VII, 34ᵃ</span> bot. <span dir=\"rtl\">תוך בר</span> the inner parts of the Passover lamb must hang outside (not be put inside, v. R. Akiba in Mish. <span class=\"citation\">ib. VII, 1</span>); Mekh. Bo, 6 <span dir=\"rtl\">תוך ובר</span> (read <span dir=\"rtl\">תוכו בר</span>); <span class=\"citation\">Pes. 74ᵃ</span> R. Ish. called it <span dir=\"rtl\">תוך בר</span> Ar. s. v. <a href=\"#\" data-headword=\"תֵּךְ\">תך</a> 2 (ed. <span dir=\"rtl\">תוך תוך</span>, Var. in Rashi a. Ar. <a href=\"#\" data-headword=\"תּוּכְבְּרָא\">תוכברא</a> q. v.).</div>","alt":[]},"4610":{"h":"בַּר","r":"B01153","html":"<div class=\"sense\"><b>1)</b>  (= h. <a href=\"#\" data-headword=\"שָׂדֶה\">שָׂדֶה</a>, <a href=\"#\" data-headword=\"יַעַר\">יַעַר</a>) <i>forest, prairie</i> &amp;c. <span class=\"citation\">Targ. Ps. L, 10</span> sq. &amp;c. <span class=\"citation\">Targ. Ps. L, 10</span> sq. <span class=\"citation\">Targ. O. Gen. III, 1</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  (adj.) <i>living in the forest</i> &amp;c., <i>wild</i>. Targ. Ps. l. c. Var. <span dir=\"rtl\">תרנגול ברא</span>; <span class=\"citation\">Sabb. 78ᵃ</span> תרנגולא ב׳ Ms. M. (ed. … <a href=\"#\" data-headword=\"לַת\">לת</a>) woodcock (hen of the prairie).—</div><div class=\"sense\"><b>*3)</b> <i>peel</i>. Ib. 139ᵇ <span dir=\"rtl\">ב׳ דתומא</span> the peel of garlic; [Rashi, expl. <span dir=\"rtl\">צלע</span>, must have read <span dir=\"rtl\">אברא</span>].</div><div class=\"sense\"><b>—4)</b>  (= h. <a href=\"#\" data-headword=\"חוּץ\">חוּץ</a>) <i>outside, outdoors, street</i>. <span class=\"citation\">Targ. Gen. XXXIV, 31</span> <span dir=\"rtl\">נפקת ב׳</span> a prostitute, v. <a href=\"#\" data-headword=\"חוּץ II\"><span dir=\"rtl\">חוּץ</span> II</a>; a. fr.—<span class=\"citation\">Y. Kil. IX, 32ᵇ</span> <span dir=\"rtl\">מאן בעי לך לבר</span> who wants thee outside? (an intimation to leave the room). <span class=\"citation\">Snh. 62ᵃ</span>; <span class=\"citation\">62ᵇ</span>; <span class=\"citation\">Sabb. 106ᵃ</span>, a. e. <span dir=\"rtl\">פוק תני לברא</span> go out and teach it in the street (i.e. your tradition is rejected).—<span dir=\"rtl\">תנא ברא</span> a Tannai not recorded in the Mishnah, v. <a href=\"#\" data-headword=\"בָּרַיְיתָא\">בָּרַיְיתָא</a>. <span class=\"citation\">M. Kat. 17ᵇ</span> (Rashi: <span dir=\"rtl\">האי תנא דברייתא</span>); <span class=\"citation\">B. Bath. 93ᵇ</span> Ar. (ed. <a href=\"#\" data-headword=\"בַּתְרָא\">בתרא</a>); cmp. <a href=\"#\" data-headword=\"בָּרָאָה\">בָּרָאָה</a>.—4) (prep. a. adv.) <i>outside;</i> בר מן <i>outside of, except, without</i>. <span class=\"citation\">Targ. O. Gen. XIV, 24</span>; a. fr.—<span class=\"citation\">Ber. 38ᵇ</span> <span dir=\"rtl\">ב׳ מן דין וב׳ וכ׳</span> without this and without that, i.e. apart from these two arguments. <span class=\"citation\">Y. Erub. VII, end 24ᵈ</span> <span dir=\"rtl\">ב׳ מדעתיה</span> without his knowledge; a. fr.—<span class=\"citation\">Ḥull. 62ᵇ</span> <span dir=\"rtl\">וסימניך ב̇ר̇ מיניה</span> and thy mnemonical sign (as to <a href=\"#\" data-headword=\"צַרְדָּא\">צרדא</a> a. <span dir=\"rtl\">ב̇ר̇דא</span>, the one being forbidden, the other permitted) be: keep aloof from it <span dir=\"rtl\">(ב̇ר̇דא</span>).—Trnsf. <i>restriction</i> (everywhere except …), <i>proviso</i>. <span class=\"citation\">Succ. 45ᵇ</span>; <span class=\"citation\">Snh. 97ᵇ</span> who enter the heavenly courts <span dir=\"rtl\">בב׳</span> with certain qualifications (by special grant), <span dir=\"rtl\">בלא ב׳</span> without any restrictions.—<span dir=\"rtl\">לְבַר</span>, <span dir=\"rtl\">מִלְּבַר</span> <i>apart from, outside, exclusively</i>. <span class=\"citation\">Cant. R. to VII, 8</span> <span dir=\"rtl\">לב׳ מישראל</span> except the Israelites. <span class=\"citation\">Ḥull. 98ᵃ</span> sixty one, <span dir=\"rtl\">בהדי דידה או … לב׳ מינה</span> the one (egg) included or excluded? <span class=\"citation\">B. Bath. 90ᵇ</span> <span dir=\"rtl\">שתותא מלב׳</span> the sixth part (as an addition) is outside, i.e. to each five portions one is added, an addition of twenty percent, opp. <span dir=\"rtl\">מִלְגֵו</span>. <span class=\"citation\">B. Mets. 53ᵇ</span>, v. <a href=\"#\" data-headword=\"חוּמְשָׁא\">חוּמְשָׁא</a>.</div>","alt":["בָּר","בָּרָא"]},"4611":{"h":"בַּר II","r":"B01154","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(b. h. <a href=\"#\" data-headword=\"בַּר\">בַּר</a> poetic; <a href=\"#\" data-headword=\"ברי\">ברי</a>) <i>son, offspring</i>. <span class=\"citation\">Targ. Gen. IV, 25</span>; a. v. fr.—<span dir=\"rtl\">ב׳ שמואל</span> son of Sam.; … <span dir=\"rtl\">בְּרֵיה דר׳</span> son of … <span class=\"citation\">Ber. 3ᵃ</span>. <span class=\"citation\">Ḥull. 11ᵃ</span>; a. v. fr.—<span class=\"citation\">B. Mets. 110ᵃ</span> … <span dir=\"rtl\">בְּרָהּ דבת</span> the son of the daughter of … <span class=\"citation\">Sabb. 116ᵇ</span> <span dir=\"rtl\">במקום ברא ברתא וכ׳</span> where there is a son, the daughter cannot inherit. <span class=\"citation\">Y. Shebi. IX, 39ᵃ</span> bot. <span dir=\"rtl\">אמה דהן ילדת ב׳</span> this nan’s mother has born a son, i.e. she may be proud of him; <span class=\"citation\">Y. Ab. Zar. IV, 43ᵈ</span> <span dir=\"rtl\">אית לאימיה ב׳</span> (not <span dir=\"rtl\">ואית</span>); a. v. fr.—Pl. [<a href=\"#\" data-headword=\"*בָּרִין\">בְּרִין</a>, <a href=\"#\" data-headword=\"ברי I\">בְּרֵי</a>. <span class=\"citation\">Targ. Y. Ex. X, 9</span> (some ed.). <span class=\"citation\">Targ. Ps. CXXVII, 5</span> Ms.] <a href=\"#\" data-headword=\"בִּנְיָן\">בְּנִין</a>, <a href=\"#\" data-headword=\"בְּנֵי\">בְּנֵי</a>, <span dir=\"rtl\">בְּנַיָּא</span>. <span class=\"citation\">Targ. Gen. V, 4</span> <span dir=\"rtl\">בְּנִין וּבְנָן</span> sons and daughters; a. fr.—<span class=\"citation\">Keth. IV, 10</span> (in a marriage contract) <span dir=\"rtl\">בנין דכרין</span> male issue, opp. <span dir=\"rtl\">בְּנָן נוקבין</span>, <span class=\"citation\">ib. 11</span>.—<span class=\"citation\">Ber. 10ᵃ</span> <span dir=\"rtl\">ב׳ דמעלו</span> good children. <span class=\"citation\">Y. B. Bath. VIII, 16ᵇ</span> bot. <span dir=\"rtl\">אין הוון בנוי דהנייה</span> (read <span dir=\"rtl\">בָּנַיי</span>) if my children turn out well; a. v. fr.—<span dir=\"rtl\">בר בר</span>, <span dir=\"rtl\">בר בת</span> <i>grandson</i>. Esth. R. introd. (expl. <span dir=\"rtl\">נין ונכד</span>) <span dir=\"rtl\">בר ובר בר</span> (not <span dir=\"rtl\">וברבר</span>) son and grandson; a. fr.</div><div class=\"sense\"><b>Fem. בְּרַת</b> <div class=\"sense\"> [The meaning of <span dir=\"rtl\">בר</span> in compounds is generally the same as of <a href=\"#\" data-headword=\"בֵּן\">בן</a> a. <span dir=\"rtl\">בעל</span>, e.g. <span dir=\"rtl\">ב׳ אולפן</span> <i>a scholar</i>, <span dir=\"rtl\">ב׳ אמודאי</span> <i>a diver</i>, <span dir=\"rtl\">ב׳ שטיא</span> <i>a maniac</i>, <span dir=\"rtl\">ב׳ דעת</span> <i>a rational being</i>. <span dir=\"rtl\">בר בי רב</span>, v. <a href=\"#\" data-headword=\"בֵּי\">בֵּי</a>. For compounds which are not self-evident, see the respective determinants.]</div></div>","alt":["בְּרָא"]},"4612":{"h":"בַּר III","r":"B01155","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>clear, bright, clean, pure</i>. <span class=\"citation\">Tosef. Kil. III, 6</span> (missing in ed. Zuckerm., v. Var. a. l.) <span dir=\"rtl\">שהוא בר ובקי וכ׳</span> who is clear and well-versed in &amp;c. <span class=\"citation\">Num. R. s. 10</span> (ref. to <a href=\"#\" data-headword=\"ברי\">ברי</a> <span class=\"citation\">Prov. XXXI, 2</span>, a. <span dir=\"rtl\">בר</span> <span class=\"citation\">Ps. II, 12</span>) the Law <span dir=\"rtl\">שהיא נקראת בר</span> which is called <i>bar</i> (clear, pure, <span class=\"citation\">Ps. XIX, 9</span>).—Pl. <a href=\"#\" data-headword=\"בָּרִי\">בָּרִים</a>. Ib.</div>","alt":[]},"4613":{"h":"בַּר IV","r":"B01156","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"בָּרַר\">בָּרַר</a>) [<i>sifted</i>] <i>grain</i>. <span class=\"citation\">Ber. 55ᵃ</span> <span dir=\"rtl\">כשם שא&quot;א לבר בלא וכ׳</span> as there can be no grain without straw, so there is no dream without idle things; <span class=\"citation\">Ned. 8ᵃ</span></div>","alt":["בָּר"]},"4614":{"h":"בָּרָא I","r":"B01157","html":"<div class=\"sense\"><i>outside, forest</i> &amp;c., v. <a href=\"#\" data-headword=\"בַּר IV\"><span dir=\"rtl\">בַּר</span> I</a> ch.</div>","alt":[]},"4615":{"h":"בָּרָא II","r":"B01158","html":"<div class=\"sense\">, <a href=\"#\" data-headword=\"בַּר II\">בְּרָא</a> I <i>to create</i>, v. <a href=\"#\" data-headword=\"ברי\">ברי</a>.</div>","alt":[]},"4616":{"h":"בְּרָא II","r":"B01159","html":"<div class=\"sense\"><i>son</i>, v. <a href=\"#\" data-headword=\"בַּר II\"><span dir=\"rtl\">בַּר</span> II</a>.</div>","alt":[]},"4617":{"h":"בָּרָאָה","r":"B01160","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בַּר IV\"><span dir=\"rtl\">בַּר</span> I</a> ch.)</div><div class=\"sense\"><b>1)</b> <i>external, foreign, not belonging to</i>, opp. <a href=\"#\" data-headword=\"גַּוָּאָה\">גַּוָּאָה</a>. <span class=\"citation\">Targ. II Kings XVI, 18</span>; a. e.—<span class=\"citation\">Y. Pes. VII, beg. 34ᵃ</span> <span dir=\"rtl\">תנא ב׳</span>, v. <a href=\"#\" data-headword=\"בַּר\">בַּר</a> I ch.—<span class=\"citation\">Gen. R. s. 49</span>; <span class=\"citation\">Yalk. Gen. 83</span> (interpret. <a href=\"#\" data-headword=\"חָלִילָה\">חָלִילָה</a> <span class=\"citation\">Gen. XIII, 25</span>) <span dir=\"rtl\">(<a href=\"#\" data-headword=\"*בריה\">בריה</a>) <span dir=\"rtl\">ברייה הוא לך</span></span> it is foreign to thy nature; v. <span dir=\"rtl\">הִיצָה I</span>.—Pl. <a href=\"#\" data-headword=\"בְּרָאִי\">בָּרָאֵי</a>. <span class=\"citation\">Kidd. 33ᵃ</span> <span dir=\"rtl\">בתי ב׳</span> the outer chambers of the bath-house. <span class=\"citation\">Ḥag. 5ᵇ</span> <span dir=\"rtl\">בתי ב׳</span> the outer chambers of the heavens. <span class=\"citation\">B. Bath. 30ᵃ</span> <span dir=\"rtl\">בשוקי ב׳</span> in the market places abroad.—Fem. <a href=\"#\" data-headword=\"בָּרַיְתָא\">בָּרַיְתָא</a>, <a href=\"#\" data-headword=\"בָּרַיְיתָא\">בָּרַיְיתָא</a>. <span class=\"citation\">Targ. Ezek. XLII, 1</span>; a. e.—Y. M. Kat. III, beg. 81ᶜ; <span class=\"citation\">Y. Ned. X, 42ᵇ</span> top <span dir=\"rtl\">ארעא ב׳</span> (= h. <span dir=\"rtl\">חוץ לארץ</span>) abroad; v. <a href=\"#\" data-headword=\"אֶרֶץ\">אֶרֶץ</a>.—Pl. <a href=\"#\" data-headword=\"בַּרְקָתָא\">בַּרְיָתָא</a>, <a href=\"#\" data-headword=\"בָּרַיְיתָא\">בַּרְיָיתָא</a>. <span class=\"citation\">Targ. Prov. XXX, 4</span> <span dir=\"rtl\">ב׳ דארעא</span></div><div class=\"sense\"><b>—2)</b>  (as noun) <i>street, open place, field</i>. <span class=\"citation\">B. Bath. 40ᵇ</span> sit down <span dir=\"rtl\">בשוקי ובב׳</span> Rashi (ed. <span dir=\"rtl\">בשוקא</span>) in markets and open places (i.e. in public). <span class=\"citation\">Ḥull. 43</span>; <span class=\"citation\">47ᵃ</span>; <span class=\"citation\">58ᵇ</span> <span dir=\"rtl\">חיוי ב׳</span> the animals of the prairies, v. <a href=\"#\" data-headword=\"בַּר\">בַּר</a> I ch.—Esp. <a href=\"#\" data-headword=\"בָּרַיְיתָא\">בָּרַיְיתָא</a>, <a href=\"#\" data-headword=\"בָּרַיְתָא\">בָּרַיְתָא</a> (sub. <a href=\"#\" data-headword=\"מַתְנִיתָא\">מתניתא</a> = h. <span dir=\"rtl\">משנה החיצונה</span>) <i>Baraitha</i> (or <i>Boraitha</i>), traditions and opinions of Tannaim not embodied in the Mishnah as compiled by R. Judah han-Nasi. [A collection of such Baraithas is found in the Tosefta (<a href=\"#\" data-headword=\"תּוֹסֶפְתָּא\">תוספתא</a>) which bears the nearest resemblance to the Mishnah and is called by that name in Talm. Y.—The B. in frequently called <a href=\"#\" data-headword=\"מַתְנִיתָא\">מתניתא</a> (Ch.) in contrad. to <a href=\"#\" data-headword=\"מִשְׁנֶה I\">משנה</a> (Hebr.), v. <span class=\"citation\">Num. R. s. 18</span> (ref. to <span class=\"citation\">Cant. VI, 8</span>); <span class=\"citation\">Lev. R. s. 30</span>.]—<span class=\"citation\">Sabb. 19ᵇ</span>; <span class=\"citation\">Erub. 19ᵇ</span>; a. e. <span dir=\"rtl\">ב׳ לא שמיע׳ ליה</span> (cmp. <span class=\"citation\">Sabb. 61ᵃ</span>; <span class=\"citation\">Pes. 101ᵇ</span> <span dir=\"rtl\">מתנית׳ לא וכ׳</span>) he did not know that Boraitha. <span class=\"citation\">Ber. 19ᵃ</span>; a. fr.</div>","alt":["בָּרָיָיא","בָּרָיָה"]},"4618":{"h":"בְּרָאִי","r":"B01161","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בָּרָאָה\">preced.</a>) = <a href=\"#\" data-headword=\"אַבְרָאִי\">אַבְרָאִי</a> <i>outside</i>. <span class=\"citation\">Ab. Zar. 28ᵃ</span> <span dir=\"rtl\">מכה דב׳</span> an external wound.—(Adv.) <span class=\"citation\">Zeb. 15ᵃ</span> <span dir=\"rtl\">דקאי זר ב׳</span> the layman stands outside. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לב׳ נפיק וכ׳</span> does (the blood) run only outside (away from the altar) and not also inside (in all directions)?</div>","alt":[]},"4619":{"h":"בְּרֵאשִׁית","r":"B01162","html":"<div class=\"sense\"> (b. h.) <i>in the beginning</i>, as a cosmological term (ref. to <span class=\"citation\">Gen. I, 1</span>) <i>creation, primeval period, Nature, Universe</i>. <span class=\"citation\">Targ. Is. XXVIII, 29</span>; a. e.—מִבְּ׳ <i>from the beginning</i>. <span class=\"citation\">Ib. XLI, 4</span>.—<span dir=\"rtl\">מעשה ב׳</span> a) <i>creation</i>. <span class=\"citation\">Gen. R. s. 3</span>; a. fr.—b) <i>cosmogony</i>, contrad. to <span dir=\"rtl\">מעשה מרכבה</span> theosophy, <span class=\"citation\">Ḥag. II, 1</span>; a. fr.—<span class=\"citation\">Y. Shebi. I, beg. 33ᵃ</span> <span dir=\"rtl\">שבת ב׳</span> the Sabbath commemorative of creation, i.e. the regular weekly Sabbath, contrad. to Holy Days. [In later Hebr. <span dir=\"rtl\">שבת ב׳</span> the Sabbath on which the first section of the Pentateuch is read.]—<span class=\"citation\">Ber. IX, 2</span> <span dir=\"rtl\"><span dir=\"rtl\">ברוך עושה</span> (<a href=\"#\" data-headword=\"מַעֲשֶׂה\">מעשה</a>) <a href=\"#\" data-headword=\"ב׳\">ב׳</a></span> praised be the Author of creation—a formula of benediction for awe-inspiring natural phenomena; v. ib. a. Y. ib. 13ᶜ bot.—<span dir=\"rtl\">ששת ימי ב׳</span> from the six days of creation. <span class=\"citation\">Keth. 8ᵇ</span> <span dir=\"rtl\">נתיב הוא מש׳ וכ׳</span> this is the way (the lot of humanity) since the world existed.—<span class=\"citation\">Tosef. Maasr. III, 14</span>: a. fr.—Y. Taan. II, 65ᵃ bot. <span dir=\"rtl\">מי ב׳</span>; <span class=\"citation\">Lam. R. to III, 40</span> <span dir=\"rtl\">מימי ב׳</span> primeval waters, <i>Ocean</i> &amp;c. (v. <span class=\"citation\">Gen. I, 9</span> sq.).—ספר ב׳ <i>The Book of Genesis</i>. <span class=\"citation\">Gen. R. s. 3</span>; a. e.—ב׳ רבה <i>B’reshith Rabbah</i> (Gen. R.), name of the first book of the Midrash Rabbah.</div>","alt":[]},"4620":{"h":"ברבוי","r":"B01163","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בַּרְבַּיִי\">בַּרְבַּיִי</a></div>","alt":[]},"4621":{"h":"בַּרְבּוּרִים","r":"B01164","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּרְבַּרְיָא\">בַּרְבַּרְיָא</a></div>","alt":[]},"4622":{"h":"בְּרַבִּי","r":"B01165","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contr. of <span dir=\"rtl\">בי רבי</span>, <i>belonging to a school of an eminent teacher</i>, v. <a href=\"#\" data-headword=\"בֵּי\">בֵּי</a> 4) <i>B’rabbi, B’ribbi</i>, title of scholars, most frequently applied to disciples of R. Judah han-Nasi and his contemporaries, but also to some of his predecessors, and sometimes to the first Amoraim, v. <a href=\"#\" data-headword=\"אֲמוֹרָא\">אֲמוֹרָא</a>. <span class=\"citation\">B. Mets. 85ᵃ</span> <span dir=\"rtl\">אסמכיה ב׳</span> he gave him the title of B’rabbi (a scholar of Rabbi Judah). <span class=\"citation\">Ḥull. 137ᵃ</span> <span dir=\"rtl\">דברי ברי׳</span> (ref. to R. Yosé). <span class=\"citation\">Ib. 11ᵇ</span> <a href=\"#\" data-headword=\"בְּרַבִּי\">ברבי</a>; <span class=\"citation\">Macc. 5ᵇ</span> <span dir=\"rtl\">בריבי</span> (v. Rabb. D. S. a. l. note 100). <span class=\"citation\">Sabb. 115ᵃ</span> <span dir=\"rtl\">רבן גמליאל ברי׳</span> (<span class=\"citation\">Tosef. ib. XIII</span> (<span class=\"citation\">XIV), 2</span>; Mass. Sofrim V, 15 only <span dir=\"rtl\">ר׳ גמ׳</span>) R. Gaml. son of R. Judah han-Nasi. <span class=\"citation\">Erub. 53ᵃ</span> <span dir=\"rtl\">רבי אושעיא ברי׳</span> (Ms. M. <span dir=\"rtl\">ברב׳</span>, v. Rabb. D. S. a. l. notes 70; <span class=\"citation\">80</span>) R. O. scholar of Rabbi Jud. han-N.—<span class=\"citation\">Sifré Deut. 1</span>, end <span dir=\"rtl\">יהודה ברב׳</span> (<span class=\"citation\">Yalk. ib. 792</span> only <span dir=\"rtl\">יהודה</span>). <span class=\"citation\">Y. M. Kat. III, 82ᶜ</span> bot.; <span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">חד בר׳ אמר</span> a student (Amora) recited &amp;c. <span class=\"citation\">Y. Sot. VIII, end, 23ᵃ</span> <span dir=\"rtl\">לית רבי ב׳</span> [insert <a href=\"#\" data-headword=\"אוֹ I\">או</a>] not even a teacher or a student was exempt. [<span class=\"citation\">Snh. 17ᵇ</span> <span dir=\"rtl\">רמי בר ברבי</span>, read <a href=\"#\" data-headword=\"בְּרוֹכִי\">ברוכי</a>.]</div>","alt":["בְּרִיבִּי"]},"4623":{"h":"*בַּרְבַּיִי","r":"B01166","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (abbr. of <span dir=\"rtl\">בַּר בַּיִת</span>) <i>intimate, familiar</i>. <span class=\"citation\">Cant. R. to V, 15</span>; <span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">אזיל ומתעביד ב׳</span> (Cant. R. <a href=\"#\" data-headword=\"ברבוי\">ברבוי</a>, some ed.) he grows to be like an inmate of the house.</div>","alt":[]},"4624":{"h":"ברבר","r":"B01167","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּר\">בַּר</a><i>son</i>, a. <a href=\"#\" data-headword=\"בַּרְבָּרִי\">בַּרְבָּרִי</a>.</div>","alt":[]},"4625":{"h":"בַּרְבְּרָאָה","r":"B01168","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"בַּרְבָּרִי\">בַּרְבְּרִי</a>. . <span class=\"citation\">Targ. Ps. CXIV, 1</span>.</div>","alt":[]},"4626":{"h":"בַּרְבַּרוֹן","r":"B01169","html":"<div class=\"sense\"> (βαρβάρων, gen. pl. of βάρβαρος) <i>of the barbarians</i>. Lam. R. introd. (R. <span class=\"citation\">Josh. 2</span>) <span dir=\"rtl\">נקיטא ב׳</span> (read <span dir=\"rtl\">ניקיטא</span>, νικῆτα βαρβάρων) O conqueror of the Barbarians (Jews). <span class=\"citation\">Y. B. Mets. II, 8ᶜ</span>, v. <a href=\"#\" data-headword=\"בַּרְבְּרַי\">בַּרְבְּרַי</a>.</div>","alt":[]},"4627":{"h":"בַּרְבָּרִי","r":"B01170","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (βάρβαρος, babbler, Curt. Griech. Etym. p. 290) </div><div class=\"sense\"><b>1)</b> <i>foreigner</i> (in a contemptuous sense), <i>barbarian</i>. <span class=\"citation\">Esth. R. to II, 21</span> <span dir=\"rtl\">הב׳ הזה</span> this barbarian (Mordecai, contrad. to Cœlesyrians as Greeks); Targ. Esth. ib. <a href=\"#\" data-headword=\"*בַּכְיָין\">בכיין</a>.—Pl. <span dir=\"rtl\">בַּרְבְּרִיִּים</span>, <a href=\"#\" data-headword=\"בַּרְבָּרִי\">בַּרְבָּרִים</a>. <span class=\"citation\">Ex. R. s. 20</span>. <span class=\"citation\">Lev. R. s. 11</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>an inhabitant of Barbaria</i> (v. <a href=\"#\" data-headword=\"בַּרְבַּרְיָא\">בַּרְבַּרְיָא</a>). <span class=\"citation\">Gen. R. s. 60</span> beg. <span dir=\"rtl\">כושי אחד או ב׳ אחד</span> a Cushite or a Barbar; <span class=\"citation\">Cant. R. to II, 8</span> (for <a href=\"#\" data-headword=\"כּוּתִי I\">כותי</a> read: <a href=\"#\" data-headword=\"כּוּשִׁי\">כושי</a>). <span class=\"citation\">Y. Succ. V, 55ᵇ</span> top, v. <a href=\"#\" data-headword=\"בַּרְבְּרַי\">next w.</a></div>","alt":["בַּרְבַּר"]},"4628":{"h":"בַּרְבְּרַי","r":"B01171","html":"<div class=\"sense\"> . <span class=\"citation\">Lam. R. to I, 16</span>; <span class=\"citation\">IV, 19</span>; Esth. R. introd. <span dir=\"rtl\">עד דאת מכבש ב׳ וכ׳</span> instead of subjecting the Barbarians (Germans, Britains &amp;c.); <span class=\"citation\">Y. Succ. V, 55ᵇ</span> top (Hebr. diction).—<span class=\"citation\">Lev. R. s. 22</span> <span dir=\"rtl\">נקיטה ב׳</span>, v. <a href=\"#\" data-headword=\"בַּרְבַּרוֹן\">בַּרְבַּרוֹן</a>.</div>","alt":[]},"4629":{"h":"בַּרְבַּרְיָא","r":"B01172","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (barbaria) <i>foreign</i> (not Roman) <i>country</i>, esp. </div><div class=\"sense\"><b>1)</b> <i>Germania Barbara;</i> also <i>Britannia</i> (as hostile to Rome); </div><div class=\"sense\"><b>2)</b> <i>East African coast, Azania</i>, v. <a href=\"#\" data-headword=\"בַּרְבָּרִי\">בַּרְבָּרִי</a>. <span class=\"citation\">Targ. Y. II, Gen. X, 3</span>; <span class=\"citation\">Targ. I Chr. I, 6</span> (for <span dir=\"rtl\">תוגרמה</span>), v. <a href=\"#\" data-headword=\"גִּרְמָנִיקְיָא\">גרמניקיא</a>.—<span class=\"citation\">Yeb. 63ᵇ</span> אנשי ב׳ … מרטניא Ar. (ed. <a href=\"#\" data-headword=\"מרטנאי\">מרטנאי</a>, corr. acc.); <span class=\"citation\">Sifré Deut. 320</span> … <span dir=\"rtl\">מב׳ ומטונס וממורטניא</span>; <span class=\"citation\">Yalk. ib. 945</span> <span dir=\"rtl\">מב׳ ומבריטניא</span> those from Barbaria [,Tunes] and Mauretania [Britannia] who go naked &amp;c. (v. Brüll, Trachten d. Jud. p. 4 sq.). <span class=\"citation\">Cant. R. to II, 8</span> <span dir=\"rtl\">אחד מכם גולה לב׳ … לסמרטיה</span> (<span class=\"citation\">Yalk. ib. 586</span> … <span dir=\"rtl\">לבריטניא</span>) one of you is exiled to B., another to Sarmatia [Britannia]. <span class=\"citation\">Midr. Till. to Ps. CIX</span>.—<span class=\"citation\">Y. Shek. VI, 50ᵃ</span> top; <span class=\"citation\">Gen. R. s. 23</span>, end <span dir=\"rtl\">כיפי ב׳</span> the rocks of B. (Azania).—<span class=\"citation\">Gen. R. s. 75</span> <span dir=\"rtl\">בני ב׳ ובני גרמניא</span>.—<span class=\"citation\">Ex. R. s. 18</span> a king <span dir=\"rtl\">שהלך בנו לב׳</span> whose son went to a foreign land (conquered province). <span class=\"citation\">Koh. R. to II, 7</span> (ref. to <i>barburim</i> <span class=\"citation\">I Kings V</span>, </div><div class=\"sense\"><b>3)</b>  a bird &amp;c. <span dir=\"rtl\">היה בא מב׳ וכ׳</span> came from B. every day. [Ib.; <span class=\"citation\">Pesik. R. s. 16</span>; Pesik. Eth. Korb. p. 58ᵇ, <span dir=\"rtl\">מיני ב׳</span>, read with Ar. s. v. <a href=\"#\" data-headword=\"ברבר\">ברבר</a>: <a href=\"#\" data-headword=\"בִּיבָרְיָא\">בִּיבָרְיָא</a>.]</div>","alt":["בַּרְבַּרְיָה","בַּרְבַּרְיָיא","בַּרְבָּרִיאָה"]},"4630":{"h":"ברברית","r":"B01173","html":"<div class=\"sense\">, <span class=\"citation\">Y. M. Kat. III, 81ᵈ</span> bot. <span dir=\"rtl\">תונין בב׳</span>, prob. to be read <span dir=\"rtl\">בפַרְדֵּיסָא</span>; cmp. Bab. <span class=\"citation\">M. Kat. 17ᵃ</span></div>","alt":[]},"4631":{"h":"בַּרְגְּזָא","r":"B01174","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"גַּזָּא\">גַּזָּא</a></div>","alt":["בַּרְגַּזָּא"]},"4632":{"h":"בָּרָד","r":"B01175","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <span dir=\"rtl\">ברר</span>) [<i>bright, white</i>,] <i>hail</i> (v. Ges. H. Dict. s. v.). <span class=\"citation\">Mikv. VII, 1</span>; a. fr.—<span dir=\"rtl\">אבן הב׳</span> block of <i>ice</i> (or hail stone). Ib.; v. <a href=\"#\" data-headword=\"בַּרְדָּא I\">next w.</a></div>","alt":[]},"4633":{"h":"בַּרְדָּא I","r":"B01176","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ex. IX, 18</span>; a. fr.—<span class=\"citation\">M. Kat. 25ᵇ</span> <span dir=\"rtl\">כיפי דב׳</span> hail stones. <span class=\"citation\">Ber. 18ᵇ</span>; v. <a href=\"#\" data-headword=\"גְּזִיזָא\">גְּזִיזָא</a></div>","alt":[]},"4634":{"h":"בַּרְדָּא II","r":"B01177","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"בַּרְדָּא I\">preced.</a> a. <a href=\"#\" data-headword=\"אַשְׁלֵג\">אַשְׁלֵג</a>) <i>barda</i>, a cosmetic lotion used as a detergent, a mixture of aloes, myrtle and violet. <span class=\"citation\">Sabb. 50ᵇ</span> (Ms. M., once, a. Ar. <span dir=\"rtl\">בר אדא</span>, Alf. Ms. a. oth. <span dir=\"rtl\">בדרא</span>; v. Rabb. D. S. a. l. note).</div>","alt":[]},"4635":{"h":"בַּרְדָּא III","r":"B01178","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בַּרְדָּא II\">preced.</a>) <i>barda</i>, name of an unclean bird. <span class=\"citation\">Ḥull. 62ᵇ</span> (Ar. <span dir=\"rtl\">בר אדא</span>).</div>","alt":[]},"4636":{"h":"בַּרְדִּילָא","r":"B01179","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּרְדְּלָא\">בּוּרְדְּלָא</a></div>","alt":[]},"4637":{"h":"ברדין","r":"B01180","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. X</span>, end (ed. Zuck. <a href=\"#\" data-headword=\"גַּרְדּוֹן\">גרדין</a>), read <a href=\"#\" data-headword=\"גַּרְדּוֹן\">גַּרְדּוֹן</a>.</div>","alt":[]},"4638":{"h":"ברדינין","r":"B01181","html":"<div class=\"sense\">, <span class=\"citation\">Ex. R. s. 38</span>, end, read <a href=\"#\" data-headword=\"כַּדְכְּדוֹן\">כַּדְכְּדוֹן</a>.</div>","alt":["ברדנין"]},"4639":{"h":"בַּרְדִּיסִין","r":"B01182","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּרְדְּסִין\">בַּרְדְּסִין</a></div>","alt":[]},"4640":{"h":"בַּרְדְּלָא","r":"B01183","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. b. h. <a href=\"#\" data-headword=\"דְּלָאָה\">דְּלָיָה</a>, <span dir=\"rtl\">דְּלָיָהוּ</span>) <i>Bard’la</i>, surname of several persons. <span class=\"citation\">B. Mets. 10ᵇ</span> <span dir=\"rtl\">אבא כהן ב׳</span> (Var. <a href=\"#\" data-headword=\"כָּהֵן\">כהנא</a>; Ms. M. <span dir=\"rtl\">בר דלא</span>); <span class=\"citation\">Gen. R. s. 76</span>, end; <span class=\"citation\">Y. Gitt. VIII, 49ᶜ</span> top; (<span class=\"citation\">Y. Peah IV, 18ᵃ</span> bot. <span dir=\"rtl\">בר דליא</span>).—<span class=\"citation\">Succ. 26ᵃ</span> (Ms. M. 2 <span dir=\"rtl\">בר דלא</span>, v. Rabb. D. S. a. l. note); <span class=\"citation\">Gitt. 14ᵃ</span> <span dir=\"rtl\">רב אחא ב׳</span>. V. <a href=\"#\" data-headword=\"בַּרְדְּלָיָא\">בַּרְדְּלָיָא</a>.</div>","alt":[]},"4641":{"h":"ברדלה","r":"B01184","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּרְדְּלִיס\">בַּרְדְּלִיס</a></div>","alt":[]},"4642":{"h":"בַּרְדְּלָיָא","r":"B01185","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"בַּרְדְּלָא\">ברדלא</a>) pr. n. pl. <i>Bard’laya</i>, near Lydda (v. infra). <span class=\"citation\">Y. Erub. VI, 24ᵃ</span> top <span dir=\"rtl\">אנשי בר דליה</span> the inhabitants of B. <span class=\"citation\">Y. Shebi. II, 33ᵈ</span> bot. <span dir=\"rtl\">דברדלייה</span> of B. Y. Peah III, 17ᵈ bot. R. Jud. b. Pazi <span dir=\"rtl\">דבר דליא</span> (for which <span class=\"citation\">Y. Meg. I, 71ᵃ</span> <span dir=\"rtl\">דברזילה</span>); cmp. Y. Snh. I, 18ᶜ bot. where R. Jud. b. P. is mentioned as of Lydda. [<span class=\"citation\">Num. R. s. 13</span> <a href=\"#\" data-headword=\"בַּרְדְּלָיָא\">ברדליא</a>, some ed., v. <a href=\"#\" data-headword=\"בּוּרְדְּלָא\">בּיּרְדְּלָא</a>.]</div>","alt":["בַּרְדְּלָיָיה","בַּרְדּלָיָה"]},"4643":{"h":"בַּרְדְּלִיס","r":"B01186","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (πάρδαλις, pardalis; πάρδος, pardus; prob. of Semit. orig.; cmp. b. h. <span dir=\"rtl\">בְּרֻדִּים</span>) <i>a spotted beast</i>, whence </div><div class=\"sense\"><b>1)</b>  (v. Sm. Ant. s. vv.) <i>leopard</i> or <i>hyena</i>, usu. in connection with <a href=\"#\" data-headword=\"נָמֵר\">נָמֵר</a>. <span class=\"citation\">Snh. I, 4</span>. <span class=\"citation\">B. Kam. I, 4</span> (expl. <span class=\"citation\">ib. 16ᵃ</span> <a href=\"#\" data-headword=\"אָפָא\">אָפָא</a> q. v.). <span class=\"citation\">Bekh. 8ᵃ</span>. <span class=\"citation\">B. Mets. VII, 9</span>.</div><div class=\"sense\"><b>—2)</b>  (prob.) <i>marten</i>, or <i>mariput</i> (Rashi: <i>putois</i>); usu. in connection with <a href=\"#\" data-headword=\"חוּלְדָּה I\">חוּלְדָּה</a>. <span class=\"citation\">Pes. 9ᵇ</span>; <span class=\"citation\">Nidd. 15ᵇ</span>; <span class=\"citation\">Ab. Zar. 42ᵃ</span>; <span class=\"citation\">Tosef. Ohol. XVI, 13</span> ed. Zuck. <a href=\"#\" data-headword=\"ברדלה\">ברדלה</a>.</div>","alt":["בַּרְדְּלֵס"]},"4644":{"h":"ברדניקוס","r":"B01187","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*הִדְרָנִיקוֹס\">הדרניקוס</a></div>","alt":[]},"4645":{"h":"ברדס","r":"B01188","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בּוּרְדָּם\">בּוּרְדָּם</a></div>","alt":[]},"4646":{"h":"בַּרְדְּסִין","r":"B01189","html":"<div class=\"sense\"> (… <a href=\"#\" data-headword=\"סִים\">סִים</a>) m. pl. (a corrupt. of Brundusina, v. <a href=\"#\" data-headword=\"בַּלְדַּרְסִין\">בלדרסין</a>) <i>Brundisian cloaks</i>, thicker than <a href=\"#\" data-headword=\"בִּרְסִין\">בִּרְסִין</a> q. v. <span class=\"citation\">Kil. IX, 7</span>. Y. ib. 32ᵈ top <a href=\"#\" data-headword=\"בַּרְדִּיסִין\">בַּרְדִּיסִין</a>. <span class=\"citation\">Tosef. Kel. B. Bath. V, 11</span> <span dir=\"rtl\">ברתסין</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"ברתצין\">ברתצין</a>, <span dir=\"rtl\">ברתתצ׳</span>). V. <a href=\"#\" data-headword=\"פַּלְדֵּיס\">פַּלְדֵּיס</a>, <a href=\"#\" data-headword=\"פַּלְדֵּיסִין\">פַּלְדֵּיסִין</a>.</div>","alt":["בּוּרְדְּסִין"]},"4647":{"h":"*בַּרְדֵּק","r":"B01190","html":"<div class=\"sense\"> (Parel of <span dir=\"rtl\">בדק</span>, cmp. <span dir=\"rtl\">הרזק</span>) <i>to penetrate, go from end to end; to bolt</i>. <span class=\"citation\">Targ. Y. II, Ex. XXXVI, 33</span> <span dir=\"rtl\">לבַרְדּוּק</span> (h. text <span dir=\"rtl\">לִבְרֹחַ</span>).</div>","alt":[]},"4648":{"h":"בָּרָה","r":"B01191","html":"<div class=\"sense\"><b>1)</b>  fem. of 1) fem. of <a href=\"#\" data-headword=\"בַּר\">בָּר</a>.</div><div class=\"sense\"><b>—2)</b>  v. <a href=\"#\" data-headword=\"ברי\">ברי</a></div>","alt":[]},"4649":{"h":"בִּרְוָון","r":"B01192","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּירוָון\">בִּירְוָון</a></div>","alt":[]},"4650":{"h":"ברובה","r":"B01193","html":"<div class=\"sense\">, <span class=\"citation\">Y. Ḥall. I, 57ᶜ</span>, read <a href=\"#\" data-headword=\"כְּרוּבָּא\">כְּרוּבָּא</a>.</div>","alt":[]},"4651":{"h":"*ברווזא","r":"B01194","html":"<div class=\"sense\">, read <span dir=\"rtl\">בִּרְזוּזָא</span> m. (<a href=\"#\" data-headword=\"בְּרַז\">ברז</a>) <i>perforation</i>. <span class=\"citation\">Targ. Y. Num. XXV, 8</span> <span dir=\"rtl\">באתר ב׳</span> in the place of perforation (hole).</div>","alt":[]},"4652":{"h":"ברויירא","r":"B01195","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to III, 14</span> <span dir=\"rtl\">שמלאי דב׳</span>., v. <a href=\"#\" data-headword=\"בֵּיר\">בֵּיר</a>, <a href=\"#\" data-headword=\"בֵּיר\">בֵּירָא</a> 3).</div>","alt":[]},"4653":{"h":"*בָּרוּךְ","r":"B01196","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ברך</span>, v. <a href=\"#\" data-headword=\"בֵּי\">בֵּי</a>) <i>the neck</i> of an animal, so named from the benediction (<a href=\"#\" data-headword=\"*בָּרוּךְ\">בָּרוּךְ</a>) which precedes the ritual slaughtering.</div>","alt":["בֵּי ב׳"]},"4654":{"h":"בְּרוֹכִי","r":"B01197","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>B’rokhi</i>. <span class=\"citation\">Snh. 17ᵇ</span> רמי בר ב׳ Ms. M., Ar. a. oth. (ed. <a href=\"#\" data-headword=\"בְּרַבִּי\">ברבי</a>, corr. acc.).</div>","alt":[]},"4655":{"h":"ברולקי","r":"B01198","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בְּרוּקְלֵי\">ברוקלי</a></div>","alt":[]},"4656":{"h":"בִּרְיָן","r":"B01199","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּירוָון\">בִּירְוָון</a></div>","alt":[]},"4657":{"h":"בְּרוּנָא I","r":"B01200","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (dimin. of <a href=\"#\" data-headword=\"בַּר II\">בְּרָא</a>; cmp. <a href=\"#\" data-headword=\"אֲבוּנָא\">אֲבוּנָא</a>) <i>dear little son, darling</i>. Pesik. B’shall. p. 83ᵃ (allud. to termination <span dir=\"rtl\">נִי</span> in Rubeni &amp;c.) <span dir=\"rtl\">כאינש דאמר בְּרוּנִי סברוני סכיוני</span> as if one says, My own dear son, my features, my looks; <span class=\"citation\">Yalk. Num. 773</span>; <span class=\"citation\">Cant. R. to IV, 12</span> (corr. acc.); [Ar. s. v. <span dir=\"rtl\">ברן</span>, adds <span dir=\"rtl\">מאבוי</span> from his father (has he this).]</div>","alt":[]},"4658":{"h":"בְּרוּנָא I ²","r":"B01201","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>B’runa</i>, a Babyl. Amora. <span class=\"citation\">Ber. 9ᵇ</span>; a. fr.</div>","alt":[]},"4659":{"h":"בָּרוֹקָא I","r":"B01202","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>smaragd</i>, v. <a href=\"#\" data-headword=\"בַּרְקָן\">בַּרְקָן</a>.</div>","alt":[]},"4660":{"h":"בָּרוֹקָא II","r":"B01203","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Baroka</i>, father of R. Johanan. <span class=\"citation\">Ab. IV, 4</span>. <span class=\"citation\">Erub. VIII, 2</span>; a. v. fr.</div>","alt":["בָּרוֹקָה"]},"4661":{"h":"בָּרוֹקָא III","r":"B01204","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>morning star</i>, v. <a href=\"#\" data-headword=\"בָּרַק\">בָּרַק</a> a. <a href=\"#\" data-headword=\"בְּרַק I\"><a href=\"#\" data-headword=\"בְּרַק I\">בְּרַק</a>.</a> <span class=\"citation\">Y. Yoma III, beg. 40ᵇ</span>; Y. R. Hash. I, beg. 57ᵈ</div>","alt":["בָּרוֹקָה"]},"4662":{"h":"*בְּרוּקְלֵי","r":"B01205","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִמְבּוּרְקְלוֹן\">אִמְבּוּרְקְלוֹן</a>) <i>wrapper, cover</i>. Midr. Sam. XXII; Yalk. ib. 129 (expl. <a href=\"#\" data-headword=\"תְּרָפִים\">תרפים</a> as if <span dir=\"rtl\">טרפים</span>, v. <a href=\"#\" data-headword=\"טָרַף\">טָרַף</a>) <span dir=\"rtl\">ניקורים של ב׳</span> shreds of (horse) covers (corrupt. <a href=\"#\" data-headword=\"בדולקי\">בדולקי</a>, Mus. <a href=\"#\" data-headword=\"ברולקי\">ברולקי</a>).</div>","alt":[]},"4663":{"h":"בְּרוּקְתִּי","r":"B01206","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּרַקְתִּי\">בְּרַקְתִּי</a></div>","alt":[]},"4664":{"h":"בָּרוּר","r":"B01207","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ברר</span>) </div><div class=\"sense\"><b>1)</b> <i>clear, bright; certain, firm</i>. <span class=\"citation\">B. Bath. 147ᵃ</span> <span dir=\"rtl\">יו&quot;ט … ב׳ וכ׳</span> when the day of Pentecosts is bright, sow wheat; opp. <a href=\"#\" data-headword=\"בָּלוּל\">בָּלוּל</a>; <span class=\"citation\">Tosef. Arakh. I, 9</span>.—<span class=\"citation\">Snh. 7ᵇ</span> <span dir=\"rtl\">אם ב׳ וכ׳</span> if the case is as clear to thee as the morning, speak out (thy opinion). <span class=\"citation\">Gitt. 89ᵃ</span> <span dir=\"rtl\">דבר הב׳</span> an ascertained fact.—<span class=\"citation\">Pes. 50ᵃ</span> <span dir=\"rtl\">עולם ב׳</span> a rightly-conducted world, opp. <a href=\"#\" data-headword=\"הֲפוֹךְ\">הפוך</a>.—<span class=\"citation\">Y. Ber. II, 5ᵃ</span> <span dir=\"rtl\">יחזור … הב׳ לו</span> he must begin to re-read from the place which he is certain of having read correctly. <span class=\"citation\">Y. Maasr. I, 49ᵇ</span> <span dir=\"rtl\">חלוט ב׳</span>, v. <a href=\"#\" data-headword=\"חָלַט I\"><span dir=\"rtl\">חָלַט</span> I</a>; <span dir=\"rtl\">תבשיל ב׳</span> real boiling (about which there is no legal doubt). <span class=\"citation\">Y. Yeb. IV, 5ᶜ</span> bot. <span dir=\"rtl\">חלב ב׳</span> ascertained existence of forbidden fat. <span class=\"citation\">Y. Gitt. IX, 50ᶜ</span> bot. <span dir=\"rtl\">קיים שריר וב׳</span> (the formula) valid, firm and established. <span class=\"citation\">Y. Kidd. IV, 66ᵃ</span> top <span dir=\"rtl\">כהן ב׳</span> a priest of undoubted genealogy; a. fr.</div><div class=\"sense\"><b>—2)</b> (b. h. , <span class=\"citation\">Neh. V, 18</span>) <i>chosen, best</i>. <span class=\"citation\">Gen. R. s. 23</span> <span dir=\"rtl\">הב׳ שבהם</span> the best one among them.—Pl. <span dir=\"rtl\">בְּרוּרִים</span>, <span dir=\"rtl\">בְּרוּרִין</span>. Y. Kidd. IV, 66ᵃ bot. <span dir=\"rtl\">הב׳ שבאחיך</span> the chosen among thy brethren (whose genealogy has been established; v. supra); <span class=\"citation\">Num. R. s. 9</span>.</div>","alt":[]},"4665":{"h":"בֵּרוּר","r":"B01208","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">בֵּרוּרִין</span>, constr. <span dir=\"rtl\">בֵּרוּרֵי</span>, v. <a href=\"#\" data-headword=\"בֵּירוּר\">בֵּירוּר</a>.</div>","alt":[]},"4666":{"h":"בְּרוֹר","r":"B01209","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>B’ror Ḥayil </i>(<i>Ḥail</i>), seat of R. Johanan b. Zaccai’s college, near Jabneh. <span class=\"citation\">Snh. 32ᵇ</span> (Var. <span dir=\"rtl\">גדור ח׳</span>). <span class=\"citation\">Y. Keth. I, 25ᶜ</span>; a. fr.</div>","alt":["ב׳ חַיִל","ב׳ חֵיל"]},"4667":{"h":"בְּרוּרְיָא","r":"B01210","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"><i>B’ruryah</i>, daughter of R. Ḥanania b. T’radjon and wife of R. Meïr, reputed as a learned woman. <span class=\"citation\">Ab. Zar. 18ᵃ</span>. <span class=\"citation\">Ib. 18ᵇ</span> משום מעשה ב׳ Ms. M. (ed. <span dir=\"rtl\">ממ׳ דב׳</span>) (R. Meïr left for Babylon) in consequence of what occurred to B. (who defied her husband’s opinion regarding woman’s weakness and came very near being ensnared by a plot laid against her chastity; v. Rashi a. l.). <span class=\"citation\">Tosef. Kel. B. Mets. I, 6</span>.</div>","alt":["בְּרוּרְיָה"]},"4668":{"h":"בְּרוֹשׁ","r":"B01211","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>cypress</i>. <span class=\"citation\">R. Hash. 23ᵃ</span>; <span class=\"citation\">Taan. 25ᵇ</span>, a. e. (as a species of cedar); v. <a href=\"#\" data-headword=\"בְּרוֹת\">בְּרוֹת</a> a. <a href=\"#\" data-headword=\"בְּרָתָא\">בְּרָתָא</a>.</div>","alt":[]},"4669":{"h":"ברושייתא","r":"B01212","html":"<div class=\"sense\">, <span class=\"citation\">Gitt. 69ᵇ</span> <span dir=\"rtl\">ב׳ דשערי</span>, v. <a href=\"#\" data-headword=\"כְּרוֹשְׁיָיתָא\">כְּרוֹשְׁיָיתָא</a></div>","alt":[]},"4670":{"h":"בְּרוֹת","r":"B01213","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"בְּרוֹשׁ\">בְּרוֹשׁ</a>. Sifra Metsora, beg. <span dir=\"rtl\">שהיא של ב׳</span> that it (<span dir=\"rtl\">עץ ארז</span>, <span class=\"citation\">Lev. XIV, 49</span>) means a branch of a cypress; <span class=\"citation\">Y. Sot. II, 18ᵃ</span> top <a href=\"#\" data-headword=\"שלברית\">שלברית</a> (corr. acc.); <span class=\"citation\">Tosef. Neg. VIII, 2</span> <span dir=\"rtl\">של אברית</span> ed. Zuck. (Var. <span dir=\"rtl\">שלא ברית</span>; R. S. to <span class=\"citation\">Neg. XIV, 1</span> <a href=\"#\" data-headword=\"*אַבְרוֹת\">אַבְרוֹת</a>).</div>","alt":[]},"4671":{"h":"בְּרוֹתָא","r":"B01214","html":"<div class=\"sense\">v. <a href=\"#\" data-headword=\"בְּרָתָא\">בְּרָתָא</a></div>","alt":[]},"4672":{"h":"בָּרוּתָא","r":"B01215","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בַּר IV\"><span dir=\"rtl\">בַּר</span> I</a> ch.)<i>outside, rejected;</i> cmp. <a href=\"#\" data-headword=\"בָּרַיְיתָא\">בָּרַיְיתָא</a>. <span class=\"citation\">B. Mets. 9ᵃ</span>; a. fr. Ar. (ed. sometimes <a href=\"#\" data-headword=\"בָּדוּתָא\">בָּדוּתָא</a> q. v.).</div>","alt":[]},"4673":{"h":"בְּרַז","r":"B01216","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בר</span>, v. <span dir=\"rtl\">ברר</span>) [<i>to get through</i>,] <i>to bore, perforate, transfix</i>. <span class=\"citation\">Targ. Y. Num. XXV, 8</span>; a. e. [<span class=\"citation\">Targ. Y. Gen. XLIV, 34</span> <span dir=\"rtl\">דתִבְרַז</span>, read <span dir=\"rtl\">דתירן</span> or <span dir=\"rtl\">דתתרן</span> as <span class=\"citation\">Targ. Esth. VIII, 6</span>, v. <a href=\"#\" data-headword=\"אֲרַע I\">ארע</a> a. <a href=\"#\" data-headword=\"עָרַע\">ערע</a>.]—<span class=\"citation\">Snh. 52ᵇ</span> <span dir=\"rtl\">דבָרֵיז ליה מִיבְרַז</span> that one may put a culprit to death by piercing. <span class=\"citation\">Sabb. 146ᵃ</span>, v. <a href=\"#\" data-headword=\"*בּוּרְטְיָא\">בּוּרְטְיָא</a>. <span class=\"citation\">Snh. 56ᵃ</span>; a. fr.</div><div class=\"sense\"><b>*. אַבְרֵיז</b> <div class=\"sense\"><i>to sting</i>. <span class=\"citation\">Gitt. 84ᵃ</span> <span dir=\"rtl\">אי בעי מַבְרִיז וכ׳</span> if he chooses, he may sting himself with thorns and he will not fall asleep (Ar. <span dir=\"rtl\">מחריז</span>, v. <a href=\"#\" data-headword=\"חֲרַז\">חֲרַז</a>).</div></div>","alt":["בְּרֵיז"]},"4674":{"h":"בִּרְזָא I","r":"B01217","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּרַז\">preced.</a>) <i>bung-hole, bung</i>. <span class=\"citation\">Ab. Zar. 59ᵇ</span> דאישתקיל ברזיה Ms. M. (ed. <span dir=\"rtl\">דאישתקיל לברזא</span>) whose bung was taken out. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל דלהדי ב׳</span> all the wine facing the bung-hole (the first gush of wine). <span class=\"citation\">Ib. 60ᵃ</span> עד דב׳ Ms. M. (ed. <span dir=\"rtl\">הב׳</span>, Rashi <a href=\"#\" data-headword=\"ב׳\">ב׳</a>) to a level with &amp;c., i.e. the wine above the bung-hole. <span class=\"citation\">Sabb. 139ᵇ</span>. <span class=\"citation\">B. Bath. 98ᵃ</span> <span dir=\"rtl\">שני בב׳</span> (Ms. H. <span dir=\"rtl\">בברזָהּ</span>) changed the bung-hole (or the bung).</div>","alt":[]},"4675":{"h":"בִּרְזָא II","r":"B01218","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (בזא II; v. <a href=\"#\" data-headword=\"*אֲבִרְזִין\">אֲבִרְזִין</a>) <i>cut</i> (<i>leather</i>), <i>strap; horse-line</i>. <span class=\"citation\">Ḥag. 9ᵇ</span> <span dir=\"rtl\">כי ב׳ סומקא וכ׳</span> as a red line for a white horse (Ms. M. <span dir=\"rtl\">כוַרְדָּא</span>). [<span class=\"citation\">Ber. 59ᵃ</span> <span dir=\"rtl\">דברזא</span>, read <span dir=\"rtl\">דברדא</span>, v. <a href=\"#\" data-headword=\"גְּזִיזָא\">גְּזִיזָא</a>.]—Pl. <span dir=\"rtl\">בִּרְזֵי</span>. <span class=\"citation\">Sabb. 117ᵃ</span> <span dir=\"rtl\">שקיל ליה בב׳</span> he stripped the hide strap-wise. Cmp. <a href=\"#\" data-headword=\"בִּיזְלֵי\">בִּיזְלֵי</a>.</div>","alt":["בַּרְזָא"]},"4676":{"h":"בַּרְזֵג","r":"B01219","html":"<div class=\"sense\"> (denom. of <span dir=\"rtl\">בר זוג</span>) <i>to couple, join</i> (cmp. <span dir=\"rtl\">איתברנש</span> Syr., P. Sm. 582). <span class=\"citation\">Targ. Y. I Deut. XXXII, 4</span> <span dir=\"rtl\">מכרזג</span>, read <span dir=\"rtl\">מְבַרְזֵג</span> (Y. II <a href=\"#\" data-headword=\"זַוֵּוג\">זַוֵּוג</a>). Ib. XXXIV, 6 (Var. <span dir=\"rtl\">למזווגא</span>). <span class=\"citation\">Targ. Ps. LXVIII, 7</span> <span dir=\"rtl\">לבר זוגא</span> (read <span dir=\"rtl\">לבַרְזוּגָן</span>).</div>","alt":[]},"4677":{"h":"ברזות","r":"B01220","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בִּרְזַיִת\">בִּרְזַית</a></div>","alt":[]},"4678":{"h":"בַּרְזֵיל","r":"B01221","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּזֵּל\">בַּזֵּל</a></div>","alt":[]},"4679":{"h":"ברזילא","r":"B01222","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּרְזִילָא\">כַּרְזִילָא</a></div>","alt":[]},"4680":{"h":"*בַּרְזִילָה","r":"B01223","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Barzilah</i>, v. <a href=\"#\" data-headword=\"בַּרְדְּלָיָא\">בַּרְדְּלָיָה</a>.</div>","alt":[]},"4681":{"h":"בַּרְזִינָא","r":"B01224","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בְּרַז\">בְּרַז</a> a. <a href=\"#\" data-headword=\"בִּרְזָא I\"><span dir=\"rtl\">בִּרְזָא</span> I</a>) <i>a tap, sample of wine</i>, whence <i>barzina</i>, a liquid measure, one thirty-second of a Log (Ar.). <span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">ב׳ לזיבורא</span> a barzina (of urin) is a remedy for a hornet’s sting.</div>","alt":[]},"4682":{"h":"בִּרְזַיִת","r":"B01225","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"ברזות\">ברזות</a> b. h.) pr. n. m. <i>Birzayith</i> (<span class=\"citation\">I Chr. VII, 31</span>). <span class=\"citation\">Gen. R. s. 71</span> end (expl. = <a href=\"#\" data-headword=\"בִּרְזַיִת\">בִּיר זַיִת</a>).</div>","alt":[]},"4683":{"h":"בַּרְזִיתָא","r":"B01226","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּרַז\">ברז</a>) <i>spit</i>, v. <a href=\"#\" data-headword=\"*בּוּרְטְיָא\">בּוּרְטְיָא</a>.</div>","alt":[]},"4684":{"h":"בַּרְזֶל","r":"B01227","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>iron, iron tool</i>. <span class=\"citation\">Gen. R. s. 75</span> <span dir=\"rtl\">לובשי ב׳</span> clad in iron armor; a. fr.—צאן ב׳ <i>flock sold to payment in terms</i> under the condition that the young be divided until the payment in full has taken place. <span class=\"citation\">Bekh. II, 4</span>, v. <a href=\"#\" data-headword=\"וָלָד\">וָלָד</a>.—(<a href=\"#\" data-headword=\"נִכְסִין\">נכסי</a>) <span dir=\"rtl\">עבדי צאן ב׳</span> <i>mort-main</i>, wife’s estate held by her husband, which, in case of her death or divorce, he must restore <i>in specie</i>, being responsible whith all his landed property for loss or deterioration. <span class=\"citation\">Yeb. VII, 1</span>; a. fr.; v. <a href=\"#\" data-headword=\"נְכָסִים\">נְכָסִים</a>.</div>","alt":[]},"4685":{"h":"בַּרְזֶל ²","r":"B01228","html":"<div class=\"sense\"><span class=\"citation\">Targ. I Kings XXII, 12</span>; a. e.—<span class=\"citation\">Sabb. 66ᵇ</span> <span dir=\"rtl\">קול ב׳</span> (Ms. M. <span dir=\"rtl\">קל פ׳</span>). V. <a href=\"#\" data-headword=\"פַּרְזֶל\">פַּרְזְלָא</a></div>","alt":["בַּרְזְלָא"]},"4686":{"h":"בַּרְזָנִיתָא","r":"B01229","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּרַז\">ברז</a>) <i>boring, tapping</i>. <span class=\"citation\">B. Mets. 40ᵇ</span> טרחיה ודמי בַרְזָנִיתֵיה Ar. (ed. <span dir=\"rtl\">בַּרזַנְיָיתָא</span> pl.; v. Rabb. D. S. a. l. note 30) his (the seller’s) trouble and the value of his tapping (the sample; v. <a href=\"#\" data-headword=\"בַּרְזִינָא\">בַּרְזִינָא</a>). [Var. in Rashi <span dir=\"rtl\">כוז׳</span> his calling out, offering for sale, v. <a href=\"#\" data-headword=\"כְּרַז\">כְּרַז</a>.]</div>","alt":[]},"4687":{"h":"בָּרַח","r":"B01230","html":"<div class=\"sense\"> , v. <span dir=\"rtl\">ברר</span>) </div><div class=\"sense\"><b>1)</b> <i>to break through, pass through</i> (<span class=\"citation\">Ex. XXXVI, 33</span>). Denom. <a href=\"#\" data-headword=\"בָּרִיחַ\">בָּרִיחַ</a>.</div><div class=\"sense\"><b>—2)</b> <i>to flee</i>. <span class=\"citation\">Erub. 13ᵇ</span> <span dir=\"rtl\">הבּוֹרֵחַ מן הגדולה</span> he who flees office. <span class=\"citation\">Y. Yeb. XIII, 13ᶜ</span>, a. e. <span dir=\"rtl\">בְּרַח מן ג׳ וכ׳</span> shun three things. <span class=\"citation\">Y. Taan. IV, 69ᵇ</span> top, v. <a href=\"#\" data-headword=\"בָּקַע\">בָּקַע</a>; a. fr.</div><div class=\"sense\"><b>Hif. הִבְרִיחַ</b> <div class=\"sense\"><b>1)</b> <i>to cause to flee, drive out, exclude</i>. Y. Yeb. XV, 15ᵃ top <span dir=\"rtl\">להַבְרִיחוֹ מנכסיו</span> to force him to flee and abandon his property. Y. Gitt. V, 47ᵃ <span dir=\"rtl\">אדם מַבְרִיחַ עצמו מן השבועה</span> one will try to shirk the responsibilities of a guardian on account of the oath (which the court asks of him) but one will not do so on account of payment (to which he may eventually be subjected, v. Tosaf. to <span class=\"citation\">B. Kam. 39ᵇ</span>).</div><div class=\"sense\"><b>—2)</b> <i>to abstract, steal, defraud</i>. <span class=\"citation\">B. Kam. 113ᵃ</span> <span dir=\"rtl\">ה׳ את המכס</span> to smuggle. Y. Keth. VI, beg. 30ᶜ <span dir=\"rtl\">שלא תהא מַבְרֶחֶת משל וכ׳</span> that she should not take stealthily something which belongs to her husband.</div></div><div class=\"sense\"><b>Hof. הוּבְרַח</b> <div class=\"sense\"><i>to be chased, scattered</i>. <span class=\"citation\">Lam. R. to I, 21</span> <span dir=\"rtl\">הוּבְרְחוּ ענני וכ׳</span> the clouds of glory were withdrawn (<span class=\"citation\">R. Hash. 3ᵃ</span> <span dir=\"rtl\">נסתלקו</span>).</div></div>","alt":[]},"4688":{"h":"בְּרַח","r":"B01231","html":"<div class=\"sense\"><i>Af.</i> <span dir=\"rtl\">אַבְרַח</span> as <a href=\"#\" data-headword=\"בָּרַח\">preced.</a> Hif., <i>to withhold</i>. <span class=\"citation\">B. Kam. 88ᵇ</span> <span dir=\"rtl\">לאברוחינהו לנכסיה מניה</span> in order to withhold his property from &amp;c., i.e. to disinherit.</div><div class=\"sense\"><b>Ithpe. אִתְבְּרַח</b> <div class=\"sense\"><i>to be driven off, withheld</i>. <span class=\"citation\">Targ. Job VI, 13</span> (h. text <a href=\"#\" data-headword=\"דחי\">נדחה</a>).</div></div>","alt":[]},"4689":{"h":"בַּרְחָא","r":"B01232","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ברח</span>, v. <a href=\"#\" data-headword=\"בָּרַח\">בָּרַח</a></div><div class=\"sense\"><b>1)</b> ) [<i>one that breaks through</i>, cmp. <span class=\"citation\">Mic. II, 13</span>;] <i>leader of the flock</i> (h. <a href=\"#\" data-headword=\"עַתּוּד\">עַתּוּד</a>), <i>bell-wether, buck</i>. <span class=\"citation\">Y. B. Kam. X, end, 7ᶜ</span> if the restored sheep is as distinguishable <span dir=\"rtl\">כגון אהן ב׳</span> as the barḥa. Ib. what does <span dir=\"rtl\">כגון אהן ב׳</span> mean? Some say <a href=\"#\" data-headword=\"חוֹטֶר\">חוטרא</a> &amp;c., v. <a href=\"#\" data-headword=\"פַּנְדּוּרָה\">פַּנְדּוּרָא</a> a. <a href=\"#\" data-headword=\"מַשְׁכּוֹכִית\">מַשְׂכּוֹכִית</a>. Bab. <span class=\"citation\">B. Kam. 20ᵃ</span> top. <span class=\"citation\">Ib. 48ᵃ</span>. <span class=\"citation\">Sabb. 18ᵇ</span>. <span class=\"citation\">Ib. 152ᵃ</span> <span dir=\"rtl\">ב׳ קרחא</span> a bald buck (sneer at R. Joshua b. Karḥa; v. <a href=\"#\" data-headword=\"גַּוְזַנְיָא\">גַּוְזַנְיָא</a>).</div>","alt":[]},"4690":{"h":"*ברטיא","r":"B01233","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 33</span> <span dir=\"rtl\">הב׳</span>, read <span dir=\"rtl\">הבַּרְבַּרְיָא</span>; Alexandria <span dir=\"rtl\">שהיתה אוֹמַנְתּוֹ של כל העולם הב׳ הזה</span> which became the educator of all this world of Barbaria (northern Africa).</div>","alt":[]},"4691":{"h":"בְּרִטַנְיָא","r":"B01234","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּרִיטַנְיָא\">בְּרִיטַנְיָא</a></div>","alt":[]},"4692":{"h":"בֵּרַי","r":"B01235","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בֵּירַאי\">בֵּירַאי</a> 2).</div>","alt":["בֵּי ב׳"]},"4693":{"h":"ברי I","r":"B01236","html":"<div class=\"sense\"> , v. <span dir=\"rtl\">ברר</span>) </div><div class=\"sense\"><b>1)</b> <i>to hollow out, perforate</i>, v. Hif. a. <a href=\"#\" data-headword=\"בָּרָה\">בָּרָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>to think out, plan</i> (cmp. <a href=\"#\" data-headword=\"בָּדָא\">בָּדָא</a>, <a href=\"#\" data-headword=\"חָקַק\">חָקַק</a>); <i>to create</i>. <span class=\"citation\">Snh. 38ᵇ</span> when the Lord wanted <span dir=\"rtl\">לִבְרֹאות את וכ׳</span> to create man. <span class=\"citation\">Gen. R. s. 8</span> <span dir=\"rtl\">שב׳ … ואח&quot;כ בְּרָאוֹ</span> for He first created all the means of his support and then created him (Adam); a. v. fr.—Part. act. <a href=\"#\" data-headword=\"בּוֹרֵא\">בּוֹרֵא</a> q. v.—Part. pass. <a href=\"#\" data-headword=\"בָּרוּר\">בָּרוּא</a>, f. <span dir=\"rtl\">בְּרוּאָה</span>. <span class=\"citation\">Gen. R. s. 44</span> (ref. to <span class=\"citation\">Is. IV, 5</span> <span dir=\"rtl\">וּבָרָא</span>) <span dir=\"rtl\">כבר היא ב׳ וכ׳</span> it (the futurity) is already created and prepared.</div><div class=\"sense\"><b>Nif. נִבְרָא</b> <div class=\"sense\"><i>to be created</i>. Ib. s. 8 <span dir=\"rtl\">אל יִבָּרֵא</span> let him not be created. <span class=\"citation\">Snh. 38ᵃ</span>; a. v. fr.</div></div><div class=\"sense\"><b>Hif. הִבְרִיא</b> <div class=\"sense\"><b>1)</b>  (denom. of (denom. of <a href=\"#\" data-headword=\"בַּר\">בַּר</a>) <i>to come outside, bore, perforate</i>. <span class=\"citation\">Ḥull. 43ᵇ</span> <span dir=\"rtl\">שמא ה׳</span> lest it (the thorn found in the throat) may have perforated (the gullet); v. infra.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"בָּרִי\">בָּרִיא</a>) <i>to get well, recover; to be strong</i> or <i>stout</i> (fat). <span class=\"citation\">Meïl. 17ᵃ</span> <span dir=\"rtl\">יכחיש או יַבְרִיא</span> does he wish him to be lean (feeble) or to be strong?—Y. Peah III, 17ᵈ bot. <span dir=\"rtl\">שמא יבריא</span> for he may get well again. <span class=\"citation\">Ḥull. 33ᵃ</span> <span dir=\"rtl\">הרוצה שיַבְ׳</span> he who wants to be strong. <span class=\"citation\">Sabb. XIX, 5</span>; a. fr. [<span class=\"citation\">Ḥull. 43ᵇ</span> <span dir=\"rtl\">שמא ה׳</span> lest the wound created by perforation be healed, Rashi; v. supra.]</div></div>","alt":["בָּרָא"]},"4694":{"h":"ברי","r":"B01237","html":"<div class=\"sense\"><b>1)</b> <i>to create</i>. <span class=\"citation\">Targ. Gen. I, 1</span>; a. fr. [<span class=\"citation\">Targ. Prov. XX, 12</span> <span dir=\"rtl\">אלהא אברי</span>, prob. to be read <span dir=\"rtl\">אלהא ברא</span> as <span class=\"citation\">ib. XXII, 2</span>.]—<span class=\"citation\">Snh. 65ᵇ</span> <span dir=\"rtl\">ברו עלמא</span> they might create a world. <span class=\"citation\">Ib. 67</span> <span dir=\"rtl\">לא מצי ברי</span> he (the demon) cannot create. [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">ומיברי</span>, <span dir=\"rtl\">ומיברו</span>, v. Ithpe.]</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"ברי I\">preced.</a> Hif.) <i>to get well, strong</i> &amp;c. <span class=\"citation\">Ḥull. 93ᵇ</span> <span dir=\"rtl\">מדלא קא בַרְיִין</span> since they do not grow (develop). <span class=\"citation\">Ib. 46ᵇ</span> <span dir=\"rtl\">הדרא בַרְיָא</span> gets well again. [<span class=\"citation\">Taan. 21ᵇ</span> <span dir=\"rtl\">זיל בריא</span>, v. Af.]</div><div class=\"sense\"><b>—3)</b> <i>to cut, shape</i>. <span class=\"citation\">Targ. Is. XL, 20</span>.—</div><div class=\"sense\"><b>*4)</b>  (v. <a href=\"#\" data-headword=\"בַּר IV\"><span dir=\"rtl\">בַּר</span> I</a> ch., Pi. 2) <i>to expel, exile</i>. <span class=\"citation\">Targ. Prov. XXIV, 24</span> (h. text <span dir=\"rtl\">זעם</span>).</div><div class=\"sense\"><b>Af. אַבְרִי</b> <div class=\"sense\"><b>1)</b> <i>to strengthen, make well, make grow</i>. <span class=\"citation\">Targ. II Sam. III, 35</span> (Var. <span dir=\"rtl\">לאוֹכָלָא</span>, v. <a href=\"#\" data-headword=\"הַבְרָאָה\">הַבְרָאָה</a>). <span class=\"citation\">Succ. 44ᵇ</span>; <span class=\"citation\">M. Kat. 3ᵃ</span> <span dir=\"rtl\">אַבְרוּיֵי אילני</span> to make the trees stronger (facilitate their growth); <span class=\"citation\">Ab. Zar. 50ᵇ</span> <span dir=\"rtl\">אברויי וכ׳</span>, opp. <span dir=\"rtl\">אוקומי</span> to preserve the trees. <span class=\"citation\">Nidd. 47ᵇ</span>; <span class=\"citation\">Yeb. 97ᵃ</span> <span dir=\"rtl\">אַבְרְיוּהוּ</span> make him grow fat (feed him well). <span class=\"citation\">Taan. 21ᵇ</span> <span dir=\"rtl\">זיל אַבְרֵי נפשך</span> (ed. <span dir=\"rtl\">בריא</span>, v. Rabb. D. S. a. l.) go and strengthen thyself.</div><div class=\"sense\"><b>—2)</b> <i>to permeate, perforate</i>. <span class=\"citation\">Ḥull. 112ᵃ</span> <span dir=\"rtl\">דאבריה</span> (the blood) soaked through the bread. <span class=\"citation\">Ib. 93ᵇ</span> דץ ביה מידי דמברי ליה Ar. (ed. only <span dir=\"rtl\">דץ ביה מידי</span>) if he stuck something into it which perforated it (making a passage for the blood).</div></div><div class=\"sense\"><b>Ithpe. אִיתְבְּרִי  אִתְבְּרִיא</b> <div class=\"sense\">, contr. <a href=\"#\" data-headword=\"אִידְּרִי\">אִיבְּרִי</a>. </div><div class=\"sense\"><b>1)</b> <i>to be created</i>. <span class=\"citation\">Targ. Gen. II, 4</span>; a. fr.—<span class=\"citation\">Gen. R. s. 78</span> <span dir=\"rtl\">מן הן דאתבריין</span> (to) where they were created from. <span class=\"citation\">Cant. R. to VIII, 5</span> <span dir=\"rtl\">וכדון אִתְבְּרִיַית וכ׳</span> now thou hast been created again a new creature (having escaped a great danger).—<span class=\"citation\">Ber. 54ᵇ</span> <span dir=\"rtl\">איברי ליה וכ׳</span> a well was created (arose) before him. <span class=\"citation\">Snh. 65ᵇ</span>; <span class=\"citation\">67ᵇ</span> <span dir=\"rtl\">ומִיבְּרִי להו וכ׳</span> (not <span dir=\"rtl\">ומיברו</span>, Yalk. Ms. <span dir=\"rtl\">איברי</span>, v. Rabb. D. S. a. l. note 4) and a three years’ calf was created (arose) before them (<span class=\"citation\">Yalk. Ex. 182</span> <span dir=\"rtl\">ומַבְרֵי</span> they created).</div><div class=\"sense\"><b>—2)</b> <i>to become strong</i>. Y. Snh. VIII, 26ᶜ <span dir=\"rtl\">מכיון דאִבְּרִי ליביה עלוי וכ׳</span> since his heart (passion) became so strong over him as to do this (or <span dir=\"rtl\">דאַבְרֵי</span></div><div class=\"sense\"><b>—3)</b>  (v. <a href=\"#\" data-headword=\"בַּר IV\"><span dir=\"rtl\">בַּר</span> I</a>, <a href=\"#\" data-headword=\"בַּר\">בָּרָא</a>) <i>to grow wild</i>. <span class=\"citation\">Nidd. 50ᵇ</span> (explain. the expression <span dir=\"rtl\">תרנגול ברא</span> used by a scholar) <span dir=\"rtl\">דאיבראי ממרה</span> (= <span dir=\"rtl\">שמרדה</span>) that became too wild (uncontrollable) to her owner.</div></div>","alt":["בְּרָא"]},"4695":{"h":"ברי II","r":"B01238","html":"<div class=\"sense\"> (b. h.) <i>to cut out</i> (v. <a href=\"#\" data-headword=\"בַּר\">בָּרָא</a>). Part. pass. <a href=\"#\" data-headword=\"בָּרוּר\">בָּרוּי</a>, fem. <span dir=\"rtl\">בְּרוּיָה</span> <i>hollowed out</i>. <span class=\"citation\">Tosef. Kel. B. Kam. III, 3</span>, v. <a href=\"#\" data-headword=\"חִידּוּק\">חִידּוּק</a> a. <a href=\"#\" data-headword=\"כָּרָה\">כָּרָה</a>.</div><div class=\"sense\"><b>Hif. הִבְרָה</b> <div class=\"sense\">denom. of <a href=\"#\" data-headword=\"בָּרִי\">בָּרִי</a> , v. <a href=\"#\" data-headword=\"ברי I\"><span dir=\"rtl\">ברי</span> I</a> Hif.) <i>to strengthen, to offer refreshment</i>, esp. to mourners on coming from the funeral. <span class=\"citation\">M. Kat. III, 7</span> <span dir=\"rtl\">ואין מַבְרִין</span> and no mourner’s meal is offered (during the festive week). <span class=\"citation\">Snh. II, 3</span>. <span class=\"citation\">Ib. 20ᵃ</span>, v. <a href=\"#\" data-headword=\"כָּרָה\">כָּרָה</a>; a. fr. V. <a href=\"#\" data-headword=\"הַבְרָאָה\">הַבְרָאָה</a>. [Y. Sabb. VII, 10ᵃ top <span dir=\"rtl\">המברה בחרשים</span> read <span dir=\"rtl\">המבְהֶה</span>, v. <a href=\"#\" data-headword=\"בהי\">בהי</a> h.]</div></div>","alt":["בָּרָה"]},"4696":{"h":"בָּרִי","r":"B01239","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"בַּר\">בָּרָא</a>) </div><div class=\"sense\"><b>1)</b> <i>in natural condition</i>, whence (cmp. <a href=\"#\" data-headword=\"אֵיתָן\">אֵיתָן</a>) <i>healthy, strong, stout, fat</i>. <span class=\"citation\">B. Bath. 147ᵇ</span> sq. (opp. sick). <span class=\"citation\">Y. Naz. VI, 55ᵇ</span> top (opp. <a href=\"#\" data-headword=\"תַּשׁ\">תש</a>, of tender build); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>sound, sure, evident</i>. <span class=\"citation\">Y. Succ. I, 52ᵇ</span> top; <span class=\"citation\">Y. Pes. II, 29ᵇ</span> bot. <span dir=\"rtl\">דבר ב׳ שלא וכ׳</span> it is sure that he did not &amp;c.—ב׳ לי I am sure. <span class=\"citation\">Ḥull. 10ᵃ</span>; a. fr.—ב׳ ושמא ‘sure’ and ‘perhaps’, the plea of two litigants, one asserting a certainty, the other pleading ignorance or offering a possible alternative. <span class=\"citation\">Keth. 12ᵇ</span>; <span class=\"citation\">B. Mets. 37ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>sound, firm</i>. <span class=\"citation\">Cant. R. to III, 4</span> honey <span dir=\"rtl\">ב׳ כאבן</span> as solid as a stone; a. fr.—Pl. <span dir=\"rtl\">בְּרִיאִים</span>. <span class=\"citation\">Lev. R. s. 17</span> <span dir=\"rtl\">ב׳ כאולם</span> as sound as the Temple hall.—<span class=\"citation\">Ḥull. 84ᵃ</span> <span dir=\"rtl\">ממשפחת ב׳</span> of a healthy, stout family; a. fr.—Fem. <a href=\"#\" data-headword=\"בְּרִיאָה\">בְּרִיאָה</a>. <span class=\"citation\">Kidd. 71ᵇ</span> בבל ב׳ Babylon is sound (as to purity of descent). <span class=\"citation\">Erub. 62ᵃ</span> <span dir=\"rtl\">שכירות ב׳</span> a sound (legitimate) lease, opp. <span dir=\"rtl\">רעועה</span> rickety; a. fr.—<span class=\"citation\">Y. Erub. I, 19ᵃ</span> <a href=\"#\" data-headword=\"בְּרִיָּיה\">בְּרִיָּיה</a> a strong, solid rafter.—Pl. <a href=\"#\" data-headword=\"בְּרִיאוּת\">בְּרִיאוֹת</a>, <a href=\"#\" data-headword=\"בְּרִיּוּת\">בְּרִיּיוֹת</a>. Ib. top <span dir=\"rtl\">ברויות</span> ed. Krot. (corr. acc.).</div>","alt":["בָּרִיא"]},"4697":{"h":"בְּרִי","r":"B01240","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Koh. X, 6</span>.—<span class=\"citation\">Taan. 29ᵇ</span> <span dir=\"rtl\">דב׳ מזליה</span> when his (the Israelite’s) luck is good, opp. <span dir=\"rtl\">ריע מ׳</span> bad luck.—<span class=\"citation\">Yoma 57ᵃ</span> top <span dir=\"rtl\">השתא ברי וכ׳</span> now it is sure ye are unclean (rejected by the Lord).—Pl. <span dir=\"rtl\">בְּרִיֵי</span>. <span class=\"citation\">Keth. 60ᵇ</span> sq. <a href=\"#\" data-headword=\"בְּרַק II\">בני ב׳</a> strong children.—Fem. <a href=\"#\" data-headword=\"בָּרְיָא\">בַּרְיָא</a>, <a href=\"#\" data-headword=\"בָּרְיָיא\">בַּרְיָיא</a>. <span class=\"citation\">Targ. Y. Ex. IV, 7</span>.</div>","alt":["בְּרִיא"]},"4698":{"h":"בָּרְיָא","r":"B01241","html":"<div class=\"sense\"><i>Creator</i>, v. <a href=\"#\" data-headword=\"בָּרְיָיא\">בָּרְיָיא</a>.</div>","alt":[]},"4699":{"h":"בְּרִיאָה","r":"B01242","html":"<div class=\"sense\"> (b. h.) f. (<a href=\"#\" data-headword=\"בָּרָא I\">ברא</a>) <i>creation, formation</i>. <span class=\"citation\">Gen. R. s. 1</span>; <span class=\"citation\">Lev. R. s. 36</span> <span dir=\"rtl\">לב׳ שמים וכ׳</span> as to creation (plan), the heavens were the first; as to finishing (execution) &amp;c. <span class=\"citation\">Gen. R. s. 7</span>, end <span dir=\"rtl\">בְּרִיָּיתוֹ של עולם</span> the creation of the world. <span class=\"citation\">Gen. R. s. 17</span> man looks <span dir=\"rtl\">למקום ברייתו</span> to where he was created from (the earth), woman … <span dir=\"rtl\">למקום בְּרִיָּיתָהּ</span> to where she was made from (the rib); a. fr.—<span class=\"citation\">Mikv. VI, 7</span> <span dir=\"rtl\">כל שהוא מבְּרִיַּית המיים</span> whatever originates in the water (aquatic plants or animals).—<span class=\"citation\">Macc. 17ᵃ</span>, a. fr. <span dir=\"rtl\">חיטה אחת כברייתה</span> one wheat grain in its natural condition, <span dir=\"rtl\">נמלה כברייתה</span> an ant in its natural condition (though small). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בריית נשמה</span> the natural condition of an animated being.—<span class=\"citation\">Nidd. III, 7</span> <span dir=\"rtl\">בריית הזכר</span> the formation of a male embryo. <span class=\"citation\">B. Kam. 94ᵇ</span> <span dir=\"rtl\">חוזר לברייתו</span> is changed into its original condition.</div>","alt":["בְּרִיָּיה"]},"4700":{"h":"בְּרִיאוּת","r":"B01243","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּרִי\">בָּרִי</a>) <i>health, strength, fleshiness</i>. <span class=\"citation\">Esth. R. to I, 3</span>.</div>","alt":["בְּרִיּוּת"]},"4701":{"h":"בְּרִיאוּתָא","r":"B01244","html":"<div class=\"sense\"><span class=\"citation\">Nidd. 47ᵇ</span> <span dir=\"rtl\">מחמת בריאותֵה</span> (or read … <a href=\"#\" data-headword=\"תָּא\">תא</a>) on account of (his) obesity. <span class=\"citation\">Bekh. 45ᵇ</span> <span dir=\"rtl\">ב׳ אתחלא וכ׳</span> it is (unusual) strength which happened to rest in the left hand (and left-handedness is therefore no defect), opp. <a href=\"#\" data-headword=\"כְּחִישׁוּתָא\">כחישותא</a> weakness.</div>","alt":["בְּרִיּוּתָא","בְּרִיּיוּתָא"]},"4702":{"h":"בְּרִיבִּי","r":"B01245","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּרַבִּי\">בְּרַבִּי</a></div>","alt":[]},"4703":{"h":"בִּרְיָה","r":"B01246","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בָּרָא I\">ברא</a>) <i>creature; human being;</i> (freq. masc.) <i>man</i>. <span class=\"citation\">Tosef. Kil. I, 9</span> <a href=\"#\" data-headword=\"בִּירְיָא I\">ביריא</a>. <span class=\"citation\">Ber. 17ᵃ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"בְּרִיּוּת\">בְּרִיּוֹת</a>. <span class=\"citation\">Ḥull. 127ᵃ</span> <span dir=\"rtl\">ב׳ גְּדֵלוֹת בים</span> creatures living in the Sea.—<span dir=\"rtl\">הַבְּ׳</span> (often m.) <i>people, mankind</i>. <span class=\"citation\">Yoma 86ᵃ</span>; a. fr.</div>","alt":["בִּירְיָה","בִּירְיָא"]},"4704":{"h":"בָּרָיָה","r":"B01247","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּרָאָה\">בָּרָאָה</a></div>","alt":[]},"4705":{"h":"*בריה","r":"B01248","html":"<div class=\"sense\">, <span class=\"citation\">Y. Kil. IX, 32ᵈ</span> top, v. <a href=\"#\" data-headword=\"בִּירְיָא II\"><span dir=\"rtl\">בִּירְיָא</span> II</a></div>","alt":[]},"4706":{"h":"בִּרְיוֹן","r":"B01249","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"בִּירָה\">בִּירָה</a>) <i>palace-soldier, castle-guard, keeper</i>. <span class=\"citation\">Ex. R. s. 30</span> <span dir=\"rtl\">משל לב׳ וכ׳</span> this is to be compared to a palace-soldier who was drunk &amp;c.; <span class=\"citation\">Yalk. Esth. 1056</span> <span dir=\"rtl\">ללבריון</span> (read <span dir=\"rtl\">לב׳</span>).—Pl. <span dir=\"rtl\">בִּרְיוֹנִים</span>, <span dir=\"rtl\">בִּירְ׳</span>. Ex. R. l. c. <span dir=\"rtl\">ב׳ שלו וכ׳</span> his palace-guard sneered at his purple cloak.—<span dir=\"rtl\">בִּרְיוֹנוֹת</span>. Mekh. B’shall., Amalek 1, <span dir=\"rtl\">העמידו עליו ב׳ קשים</span> they appointed over him cruel guards; Tanḥ. ib. 25 <span dir=\"rtl\">עמדו עליו בריונים וכ׳</span> (read <span dir=\"rtl\">העמידו</span>); <span class=\"citation\">Y. Kidd. I, 61ᵃ</span> bot. <span dir=\"rtl\">בורניות</span> (corr. acc.). Cmp. <a href=\"#\" data-headword=\"בִּירָנִית\">בִּירָנִית</a>.</div>","alt":["בִּירְיוֹן"]},"4707":{"h":"בַּרְיוֹנָא","r":"B01250","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בַּר II\">בְּרָא</a> Ithpe. 3, cmp. <a href=\"#\" data-headword=\"בַּרְיוּתָא\">בַּרְיוּתָא</a>) <i>rebel, outlaw, highway-man</i>.—Pl. <a href=\"#\" data-headword=\"בַּרְיוֹנָא\">בַּרְיוֹנֵי</a>, <a href=\"#\" data-headword=\"בִּדּוּר\">בִּי׳</a>. <span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">הנהו ב׳</span> those rebels (the war party during the last siege of Jerusalem by the Romans). Ib. Abba Sikra <span dir=\"rtl\">ריש ב׳</span> chief of the rebels.—<span class=\"citation\">Ber. 10ᵃ</span> <span dir=\"rtl\">הנהו ב׳ דהוו וכ׳</span> there were some highway-men living in the neighborhood of &amp;c. <span class=\"citation\">Taan. 23ᵇ</span> <span dir=\"rtl\">א&quot;נ הנהו בי׳ וכ׳</span> ed. (omitted in Ms. M. a. oth.). <span class=\"citation\">Ib. 24ᵃ</span> הנך ב׳ Ms. M. (ed. <span dir=\"rtl\">בני מאתיה</span>, v. Rabb. D. S. l. note 2). <span class=\"citation\">Snh. 37ᵃ</span> <span dir=\"rtl\">בַּרְייוֹ׳</span>; a. fr.</div>","alt":["בִּירְיוֹנָא"]},"4708":{"h":"בְּרִיּוּת","r":"B01251","html":"<div class=\"sense\"><i>health</i>, v. <a href=\"#\" data-headword=\"בְּרִיאוּת\">בְּרִיאוּת</a>; <a href=\"#\" data-headword=\"בְּרִיאוּתָא\">בְּרִיּוּתָא</a>, v. <a href=\"#\" data-headword=\"בְּרִיאוּתָא\">בְּרִיאוּתָא</a>.</div>","alt":[]},"4709":{"h":"בַּרְיוּתָא","r":"B01252","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בַּרְיוֹנָא\">בַּרְיוֹנָא</a>) <i>rebellion, defiance of the law</i>. <span class=\"citation\">Sot. 19ᵇ</span>; <span class=\"citation\">20ᵃ</span> <span dir=\"rtl\">מחמת ב׳</span> (refusal to drink the searching water) in defiance, opp. <a href=\"#\" data-headword=\"רְתִיתָא\">רתיתא</a>, <a href=\"#\" data-headword=\"בִּיעֲתוּתָא\">ביעתותא</a>. *[<span class=\"citation\">Targ. Prov. XXV, 20</span>, prob. to be read <a href=\"#\" data-headword=\"בְּדִיחוּתָא\">בְּדִיחוּתָא</a>; ed. Lag. <a href=\"#\" data-headword=\"כַּרְיוּתָא\">כַּרְיוּתָא</a>. The entire verse is a corrupt combination of two versions.]</div>","alt":[]},"4710":{"h":"בְּרֵיז","r":"B01253","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּרַז\">בְּרַז</a></div>","alt":[]},"4711":{"h":"בָּרֵיז","r":"B01254","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּרַז\">ברז</a>) <i>channel, stream</i>. <span class=\"citation\">Targ. I Sam. XIV, 26</span> (h. text <span dir=\"rtl\">הלך</span>).</div>","alt":[]},"4712":{"h":"בָּרִיחַ","r":"B01255","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>bolt</i>.—Pl. <span dir=\"rtl\">בְּרִיחִים</span>, <span dir=\"rtl\">בְּרִיחִין</span>. <span class=\"citation\">Ex. R. s. 52</span>; <span class=\"citation\">Yalk. ib. 417</span>.</div>","alt":[]},"4713":{"h":"בְּרִיחָה","r":"B01256","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ברח</span>) <i>flight</i>. <span class=\"citation\">Gen. R. s. 74</span>; a. e.</div>","alt":[]},"4714":{"h":"בריחי","r":"B01257","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 21ᵃ</span>; <span class=\"citation\">145ᵇ</span> <i>sick persons</i>, v. <a href=\"#\" data-headword=\"כְּרִיהָא\">כְּרִיהָא</a>.</div>","alt":[]},"4715":{"h":"בְּרִיטַנְיָא","r":"B01258","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Britannia, Great Britain</i>. <span class=\"citation\">Yalk. Deut. 945</span>. Ib. Cant. 586, v. <a href=\"#\" data-headword=\"בַּרְבַּרְיָא\">בַּרְבַּרְיָא</a>.</div>","alt":[]},"4716":{"h":"בָּרְיָיא","r":"B01259","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>Creator, God</i>. <span class=\"citation\">Targ. Prov. XVII, 5</span> <span dir=\"rtl\">בָּרְיֵהּ</span> his Maker; a. e.—<span class=\"citation\">Y. Ber. I, 2ᵈ</span> <span dir=\"rtl\">איקריה דבָרְיִי</span> the honor of my Maker. <span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">מה אנא מובד סברי מן בריי</span> why should I give up my hope in my Creator? <span class=\"citation\">Y. Hor. III, beg. 47ᵃ</span> <span dir=\"rtl\">דמי לבָרְיֵיכוֹן</span> is like that of your Maker, v. <a href=\"#\" data-headword=\"דּוּגְמָא\">דּוּגְמָא</a>; <span class=\"citation\">Y. Snh. II, 20ᵃ</span> top <span dir=\"rtl\">לבירייתכון</span> (corr. acc.). <span class=\"citation\">Lev. R. s. 15</span> <span dir=\"rtl\">ובוֹרְיָיךְ קאים לך</span> and thy Maker will assist thee; a. fr.</div>","alt":["בּוֹרְיָא"]},"4717":{"h":"בָּרָיָיא","r":"B01260","html":"<div class=\"sense\"><i>external</i>, v. <a href=\"#\" data-headword=\"בָּרָאָה\">בָּרָאָה</a>.</div>","alt":[]},"4718":{"h":"בְּרִיָּיה","r":"B01261","html":"<div class=\"sense\"><i>creation</i>, v. <a href=\"#\" data-headword=\"בְּרִיאָה\">בְּרִיאָה</a>.</div>","alt":[]},"4719":{"h":"בִּרְיָיה","r":"B01262","html":"<div class=\"sense\"><i>creature</i>, v. <a href=\"#\" data-headword=\"בִּרְיָה\">בִּרְיָה</a>.</div>","alt":[]},"4720":{"h":"בָּרָיָיה","r":"B01263","html":"<div class=\"sense\"><i>foreign, strange</i>, v. <a href=\"#\" data-headword=\"בָּרָאָה\">בָּרָאָה</a>.</div>","alt":[]},"4721":{"h":"בָּרַיְיתָא","r":"B01264","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּרָאָה\">בָּרָאָה</a></div>","alt":[]},"4722":{"h":"בִּרְיְיתָא","r":"B01265","html":"<div class=\"sense\"><i>, </i> pl. <a href=\"#\" data-headword=\"בִּרְיְיתָא\">בִּרְיָיתָא</a>, v. <a href=\"#\" data-headword=\"בִּרְיְתָא\">בִּרְיְתָא</a>.</div>","alt":[]},"4723":{"h":"בְּרִיכָא","r":"B01266","html":"<div class=\"sense\"><i>shoot</i>, v. <a href=\"#\" data-headword=\"בֶּרֶךְ ²\">בִּרְכָּא</a>.</div>","alt":[]},"4724":{"h":"בְּרִיכָה","r":"B01267","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ברך</span>) </div><div class=\"sense\"><b>1)</b> <i>bending the knee</i>. <span class=\"citation\">Gen. R. s. 39</span>; <span class=\"citation\">Y. Ber. I, 3ᶜ</span> bot. (diff. fr. <a href=\"#\" data-headword=\"כְּרִיעָה\">כריעה</a>). Ib. 3ᵈ top <span dir=\"rtl\">לך ב׳</span> unto thee bending is due; a. e.</div><div class=\"sense\"><b>—2)</b>  (denomin. of <a href=\"#\" data-headword=\"בֶּרֶךְ\">בֶּרֶךְ</a>) <i>knee, young shoot.</i> Orlah I, 5 if a tree has been dying <span dir=\"rtl\">ובו ב׳ וכ׳</span> but there is a shoot on it …: the old stem is again like a young shoot (with ref. to the fruits of the first years, v. <a href=\"#\" data-headword=\"עָרְלָה\">עָרְלָה</a>). <span class=\"citation\">R. Hash. 15ᵇ</span>; <span class=\"citation\">Tosef. Shebi. IV, 20</span> ed. Zuck. <span dir=\"rtl\">אילן העושה ב׳ אחת</span> (ed. <span dir=\"rtl\">ברך</span>) a tree which shoots only once a year (its fruits growing all at once), opp. <span dir=\"rtl\">שתי בריכות</span> (expl. R. Hash. l. c. <span dir=\"rtl\">כעין שתי ב׳</span>) two crops, i.e. early and late fruits.</div><div class=\"sense\"><b>—3)</b>  (from the position of the hatching bird) <i>brood</i>, esp. of doves. <span class=\"citation\">B. Bath. V, 3</span>; <span class=\"citation\">Bets. 10ᵃ</span> <span dir=\"rtl\">ב׳ ראשונה</span> the first brood of the year.—Pl. <span dir=\"rtl\">בְּרִיכוֹת</span>. R. Hash. l. c.; Tosef. Shebi. l. c. <span class=\"citation\">Yeb. 63ᵃ</span> <span dir=\"rtl\">בִּרְכּוֹת</span>, v. <a href=\"#\" data-headword=\"בָּרַךְ\">בָּרַךְ</a> Hif.</div>","alt":[]},"4725":{"h":"בְּרֵיכָה","r":"B01268","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>pond, lake.</i> <span class=\"citation\">Mikv. VI, 11</span> <span dir=\"rtl\">אחד משלש … לב׳</span> one three hundred and twentieth part of the bathing pond. <span class=\"citation\">Gen. R. s. 39</span> (ref. to <a href=\"#\" data-headword=\"בְּרָכָה\">בְּרָכָה</a> <span class=\"citation\">Gen. XII, 12</span>) <span dir=\"rtl\">קרי ביה ב׳ וכ׳</span> read <i>b’rekhah</i>, a pond, as the pond cleanses the unclean (by immersion) &amp;c.; <span class=\"citation\">Num. R. s. 11</span>; a. fr.—Pl. <span dir=\"rtl\">בְּרֵיכוֹת</span>, <span dir=\"rtl\">בְּרֵכ׳</span>. <span class=\"citation\">Makhsh. II, 3</span>.—Cmp. <a href=\"#\" data-headword=\"נִבְרֶכֶת\">נִבְרֶכֶת</a>.</div>","alt":["בְּרֵכָה"]},"4726":{"h":"*בריכסון","r":"B01269","html":"<div class=\"sense\">, read <span dir=\"rtl\">בְּרִיכְסִין</span> (= ἔβρεξεν fr. βρέχω; ἐ rejected) <i>it rained</i>. <span class=\"citation\">Y. Shebu. III, 34ᵈ</span> bot. if seeing that it has rained, one says <span dir=\"rtl\">קורי פלי ב׳</span>, (κύριε πολὺ ἔβρεξεν) ‘By God, it has rained much’—this is a vain oath; <span class=\"citation\">Y. Ned. III, 38ᵃ</span> top <span dir=\"rtl\">בלי קורי בריקשון</span> (corr. acc.); <span class=\"citation\">Pesik. R. s. 22</span> <span dir=\"rtl\">כלי קרי אברוכסים</span> (corr. acc., read <span dir=\"rtl\">איבריכסין</span> ἔβρεξεν).</div>","alt":[]},"4727":{"h":"בְּרֵיכְתָא","r":"B01270","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"בְּרֵיכָה\">בְּרֵיכָה</a>. <span class=\"citation\">Targ. Is. XXII, 9</span>; a. e.</div>","alt":[]},"4728":{"h":"*בָּרִין","r":"B01271","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ram Barin</i>, a border town of Northern Palestine (district of Tyre; perh. <i>Kefr Bureim</i>, Neub. Géogr. p. 23). <span class=\"citation\">Y. Dem. II, 22ᵈ</span> top; <span class=\"citation\">Tosef. Shebi. IV, 10</span> <a href=\"#\" data-headword=\"רמכוך\">רמכוך</a>, Var. <span dir=\"rtl\">רומברך</span>. Y. l. c. <span dir=\"rtl\">עד כדון</span> for which R. S. to <span class=\"citation\">Dem. II, 1</span> <a href=\"#\" data-headword=\"בּוּרָן\">בּוּרָן</a> (prob. the same).</div>","alt":["רם ב׳"]},"4729":{"h":"בְּרֵיק","r":"B01272","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּרַק I\">בְּרַק</a></div>","alt":[]},"4730":{"h":"בריקא","r":"B01273","html":"<div class=\"sense\">, v. <span dir=\"rtl\">בורדיקא׳</span></div>","alt":["בריקה"]},"4731":{"h":"בריקשון","r":"B01274","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בריכסון\">בריכסון</a></div>","alt":[]},"4732":{"h":"בָּרִיר","r":"B01275","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>clear, pure, certain; polished, bright</i>. <span class=\"citation\">Targ. Ps. XVIII, 27</span> (h. text <a href=\"#\" data-headword=\"נָבַר\">נָבָר</a>). <span class=\"citation\">Targ. Y. Ex. XXII, 2</span> (Var. <a href=\"#\" data-headword=\"בָּרוּר\">בָּרוּר</a>); a. fr.—Pl. <span dir=\"rtl\">בְּרִירִין</span>, <a href=\"#\" data-headword=\"בָּרִיר\">בְּרִירָן</a>. <span class=\"citation\">Targ. Y. I Deut. VIII, 9</span>, <span class=\"citation\">Targ. Y. II, Deut. VIII, 9</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>chosen, peculiar</i>. Ibid. XXIX, 12.</div>","alt":["בְּרִיר","בְּרִירָא","בְּרִירָא","בְּרִירָה"]},"4733":{"h":"בְּרִירָה","r":"B01276","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ברר</span>) <i>sifting, assorting</i>. <span class=\"citation\">Y. Sabb. VII, 10ᵇ</span> top [read:] <span dir=\"rtl\">כל מה שהותר מכלל ב׳ וכ׳</span> what is allowed on Holy Days as coming under the category of sifting, is not always allowed … on the Sabbath; <span class=\"citation\">Y. Bets. I, 60ᵈ</span> (usually <span dir=\"rtl\">משום בורר</span>).</div>","alt":[]},"4734":{"h":"בְּרֵירָה","r":"B01277","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ברר</span>) <i>choosing, choice</i>, esp. as a dialectic term, <i>B’rerah, subsequent selection, retrospective designation</i>, i.e. the legal effect resulting from an actual selection or disposal of things previously undefined as to their purpose, e.g. a letter of divorce must be written, with special intention, for the persons concerned; now, “if one says to a scribe, ‘Write for me a letter of divorce for one of my wives whom I may choose to divorce’, none of them can be divorced with it” (<span class=\"citation\">Gitt. III, 1</span>), upon which the remark is made (ib. 24ᵇ) <span dir=\"rtl\">הא קא משמע לן דאין ב׳</span> this rule of the Mishnah implies the adoption of the principle that subsequent disposal does not react on the original status of the letter of divorce, so as to say that this subsequent selection is equal to a defined intention at the time when the deed was to be written. [The question of B’rerah, i.e. whether a subsequent disposal has or has not a retrospective legal effect, is widely spread in the Talmud, referring both to judicial as well as to ritual cases.] <span class=\"citation\">Yoma 55ᵇ</span> ר׳ … לית ליה ב׳ R. Judah rejects the principle of B’rerah; <span class=\"citation\">Y. Shek. VI, 50ᵇ</span> <span dir=\"rtl\">אי אמרינן ב׳ וכ׳</span> if we adopt the principle of B., let four Zuz (the value of one offering) be taken out of the bag and thrown into the water, and the balance of the money be permitted for use. <span class=\"citation\">Ḥull. 14ᵇ</span>; a. fr.</div>","alt":[]},"4735":{"h":"בָּרִירוּ","r":"B01278","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּרִירוּתָא\">בְּרִירוּתָא</a></div>","alt":[]},"4736":{"h":"בְּרִירוּת","r":"B01279","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ברר</span>) <i>clearness, pureness, innocence</i>. <span class=\"citation\">Y. Taan. III, 67ᵃ</span> <span dir=\"rtl\">ב׳ כפיך</span> innocence of thy hands (expl. <i>bor</i>, <span class=\"citation\">Job XXII, 30</span>).</div>","alt":[]},"4737":{"h":"בְּרִירוּתָא","r":"B01280","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Ex. XXIV, 10</span> (<i>brightness</i>, h. text <span dir=\"rtl\">טהר</span>); a. e.—<span class=\"citation\">Targ. Prov. XVI, 15</span> ed. Lag. (Var. <a href=\"#\" data-headword=\"ביריאתא\">ביריאתא</a>).</div>","alt":["בָּרִירוּ"]},"4738":{"h":"*בריש","r":"B01281","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַרְדָּא II\"><span dir=\"rtl\">אַרְדָּא</span> II</a>. <span class=\"citation\">Gitt. 14ᵇ</span></div>","alt":["פילי ב׳"]},"4739":{"h":"בְּרִית","r":"B01282","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> prop. <i>circle, ring, chain</i>, hence <i>oath</i> (of fidelity), <i>solemn injunction; covenant treatise</i>. [<span dir=\"rtl\">כרת ב׳</span> to cut a ring out; to make a covenant; <span dir=\"rtl\">בא בב׳</span> to enter into the ring, to promise fidelity; <span dir=\"rtl\">הפר ב׳</span> to break the ring, to break one’s oath &amp;c.] <span class=\"citation\">Sabb. 137ᵇ</span>; <span dir=\"rtl\">בריתו של אברהם אבינו</span> (sign of) the covenant of Abraham, <i>circumcision.</i> <span class=\"citation\">Ab. III, 11</span>; a. fr. <span class=\"citation\">Y. Peah VIII, 21ᵃ</span> <span dir=\"rtl\">מפני ב׳ של א&quot;א</span> on account of the covenant of Abraham (for the sake of human dignity). <span class=\"citation\">Num. R. s. 18</span>, a. fr. <span dir=\"rtl\">ב׳ כרותה לשפתים</span> a law is made for the lips, i.e. words are ominous (ref. to <span dir=\"rtl\">לא נעלה</span>, <span class=\"citation\">Num. XVI, 12</span>). <span class=\"citation\">Gen. R. s. 34</span>, v. <a href=\"#\" data-headword=\"אָוִיר\">אָוִיר</a>; a. fr.—הַבְּ׳ וכ׳ <i>by the covenant</i> (an oath), <i>indeed</i>. <span class=\"citation\">Tosef. Ḥall. I, 6</span> <span dir=\"rtl\">ב׳ וכ׳</span> (Var. <span dir=\"rtl\">הב׳</span>); <span class=\"citation\">Pes. 38ᵇ</span> indeed, those are the very words &amp;c.; (some explain) indeed?, are those the very &amp;c. (is it a tradition for which no reason needs to be given)?; Y. Peah V, 19ᵇ bot. <span dir=\"rtl\">הב׳</span>.—Pl. <span dir=\"rtl\">בְּרִיתוֹת</span>. <span class=\"citation\">Ber. 48ᵇ</span> sq. <span dir=\"rtl\">שלש ב׳</span> three covenants (three times the word <i>b’rith</i>, <span class=\"citation\">Deut. XXVIII, 69</span>; <span class=\"citation\">XXIX, 8</span>). <span class=\"citation\">Tosef. Sot. VIII, 10</span>; <span class=\"citation\">11</span> ב׳ Var. (ed. Zuck. <a href=\"#\" data-headword=\"כְּרִיתוּת\">כְּרִיתוֹת</a>); <span class=\"citation\">Sot. 37ᵇ</span>; a. fr.</div>","alt":[]},"4740":{"h":"בֵּרִית","r":"B01283","html":"<div class=\"sense\"><i>a ring, band</i>, v. <a href=\"#\" data-headword=\"בֵּירִית\">בֵּירִית</a>. [<span class=\"citation\">Y. M. Kat. I, 80ᵇ</span> top, v. <a href=\"#\" data-headword=\"כְּרִית\">כְּרִית</a>.]</div>","alt":[]},"4741":{"h":"בִּרְיְתָא","r":"B01284","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"בִּרְיָה\">בִּרְיָה</a> <i>creature</i>. <span class=\"citation\">Targ. Is. XXIX, 16</span>; a. fr. <span class=\"citation\">Targ. Ezek. I, 9</span>; <span class=\"citation\">11</span> בִּרְיָא <i>each</i> (h. text <a href=\"#\" data-headword=\"אִישׁ\">איש</a>).—Pl. <a href=\"#\" data-headword=\"בִּרְיְתָא\">בִּרְיָתָא</a>, <a href=\"#\" data-headword=\"ביריאתא\">בִּירְיָאתָא</a>, <span dir=\"rtl\">בִּירְ׳</span>. <span class=\"citation\">Ib. 13</span> sq. (h. text <a href=\"#\" data-headword=\"חַיּוּת\">חַיּוֹת</a>); a. fr. <span class=\"citation\">Gen. R. s. 60</span> <span dir=\"rtl\">הדא דב׳ אמרין</span> that is what people say. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד כותאי 1) <span dir=\"rtl\">מפליא בב׳</span> makes sport of men (interpreting dreams to suit himself).</div><div class=\"sense\"><b>—2)</b> <i>natural state</i>, v. <a href=\"#\" data-headword=\"בְּרִיָּיה\">בְּרִיָּיה</a>. <span class=\"citation\">B. Kam. 93ᵇ</span></div>","alt":["בִּרְיָא","בי׳"]},"4742":{"h":"בָּרַיְתָא","r":"B01285","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בָּרָאָה\">בָּרָאָה</a></div>","alt":[]},"4743":{"h":"בריתא","r":"B01286","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. II, Num. XXIV, 6</span> כב׳ Ar., v. <a href=\"#\" data-headword=\"בְּרָתָא\">בְּרָתָא</a> end.</div>","alt":[]},"4744":{"h":"בָּרַךְ","r":"B01287","html":"<div class=\"sense\"><b>1)</b> <i>to cave out</i>. Denom. <a href=\"#\" data-headword=\"בְּרֵיכָה\">בְּרֵכָה</a>, <a href=\"#\" data-headword=\"בֶּרֶךְ\">בֶּרֶךְ</a>; cmp. <a href=\"#\" data-headword=\"בּוּרְכָּא\">בּוּרְכָּא</a>, <a href=\"#\" data-headword=\"בּוּרְכְּתָא\">בּוּרְכְּתָא</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">ברר</span>) <i>to select, point out</i> (cmp. esp. <span class=\"citation\">Gen. II, 3</span>) whence <i>to bless</i> (Pi.).—Part. pass. <a href=\"#\" data-headword=\"*בָּרוּךְ\">בָּרוּךְ</a> <i>chosen, blessed, praised</i>. <span dir=\"rtl\">הקדוש ב׳ הוא</span> (abbr. <span dir=\"rtl\">הקב&quot;ה</span>) the Holy One, blessed be He. <span class=\"citation\">Pes. 118ᵃ</span>; a. v. fr. <span class=\"citation\">Ib. 104ᵇ</span>, a. fr. <span dir=\"rtl\">פותח בב׳ וכ׳</span> he (who prays) opens the benediction with <i>barukh</i> and closes with <i>barukh</i> (i.e. <span dir=\"rtl\">ברוך אתה ה׳</span>). <span class=\"citation\">Tosef. Sot. I, 10</span> <span dir=\"rtl\">ב׳ בכלל</span>, v. <a href=\"#\" data-headword=\"כְּלָל\">כְּלָל</a>; a. fr.</div><div class=\"sense\"><b>Pi. בֵּרַךְ  בֵּירַךְ</b> <div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to praise, bless</i>, esp. <i>to recite the due benediction</i>. <span class=\"citation\">Ber. VI, 1</span>. <span class=\"citation\">Ib. 5</span> <span dir=\"rtl\">בי׳ על היין</span> having recited the blessing over wine &amp;c. <span class=\"citation\">Pes. X, 9</span> <span dir=\"rtl\">ב׳ ברכת הפסח</span> having recited the blessing over the Paschal lamb. <span class=\"citation\">Ib. 5</span> <span dir=\"rtl\">אנחנו חייבים … לְבָרֵךְ</span> we are bound to … praise &amp;c.; a. v. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">נקב</span>) <i>to blaspheme</i>. <span class=\"citation\">Snh. 56ᵃ</span> <span dir=\"rtl\">עד שֶיְבָרֵךְ שם בשם</span> until he blasphemes the Lord by His name. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שבי׳ את השם בכינוי</span> who blasphemed the Lord by an attribute.—Part. Pu. <span dir=\"rtl\">מְבוֹרָךְ</span> <i>blessed, praiseworthy</i>. <span class=\"citation\">Ber. VII, 3</span>; a. fr.</div><div class=\"sense\"><b>—3)</b>  *<i>to cut through, to clear virgin ground</i> or <i>forest</i>. <span class=\"citation\">Tosef. Shebi. III, 20</span> ed. Zuck. (Var. <span dir=\"rtl\">מגדר</span>); Y. ib. IV, 35ᵇ bot. <span dir=\"rtl\">מבדין</span>; Y. Sabb. VII, 10ᵃ top <span dir=\"rtl\">המברה</span>, v. <a href=\"#\" data-headword=\"בהי\">בהי</a> h. [<span class=\"citation\">Tosef. Shebi. I, 6</span> <span dir=\"rtl\">מבורכות</span>, v. infra.]</div></div><div class=\"sense\"><b>Hithpa. הִתְבָּרֵךְ</b> <div class=\"sense\">, <i>Nithpa</i>. <span dir=\"rtl\">נִתְבָּרֵךְ</span> <i>to be blessed</i> (<i>praised</i>); <i>to be increased</i> (v. <a href=\"#\" data-headword=\"בְּרָכָה\">בְּרָכָה</a>). Y. Ber. IX, 14ᵃ top <span dir=\"rtl\">ויִתְבָּרַךְ</span> and be blessed. Y. M. Kat. I, beg. 80ᵃ if the waters were scanty <span dir=\"rtl\">ונִתְבָּרְכוּ</span> and grew plentiful. <span class=\"citation\">Yeb. 63ᵃ</span>; a. fr.</div></div><div class=\"sense\"><b>Hif. הִבְרִיךְ</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"בֶּרֶךְ\">בֶּרֶךְ</a> or <a href=\"#\" data-headword=\"בְּרִיכָה\">בְּרִיכָה</a>) <i>to form a knee, to engraft;</i> esp. <i>to bend a vine by drawing it into the ground and making it grow forth as an independent plant, to sink.</i> <span class=\"citation\">Shebi. II, 6</span>; <span class=\"citation\">R. Hash. 10ᵇ</span>; a. fr.—<span class=\"citation\">Tosef. Shebi. I, 6</span> <span dir=\"rtl\">אם היו מוּבְרָכוֹת</span> (incorr. <span dir=\"rtl\">מבורכ׳</span>) if they have been sunk before New Year &amp;c.—<span class=\"citation\">Yeb. 63ᵃ</span> (allud. to <span class=\"citation\">Gen. XII, 3</span>) <span dir=\"rtl\">שתי ברכית טובות יש לי להַבְרִיךְ בך</span> two good shoots (proselytes) have I to engraft on thee, Ruth and &amp;c. (<span class=\"citation\">B. Kam. 38ᵇ</span> … <span dir=\"rtl\">פרידות וכ׳</span>).</div></div>","alt":[]},"4745":{"h":"בְּרַךְ","r":"B01288","html":"<div class=\"sense\"> Part. Peil <a href=\"#\" data-headword=\"בְּרַךְ\">בְּרִיךְ</a> <i>blessed</i>. <span class=\"citation\">Targ. Gen. IX, 26</span>; a. fr.—<span class=\"citation\">Sabb. 67ᵃ</span>, a. fr. <span dir=\"rtl\">קודשא ב׳ הוא</span> the Holiness (Holy One), blessed be He. <span class=\"citation\">Cant. R. to. IV, 4</span>; <span class=\"citation\">Gen. R. s. 32</span> <span dir=\"rtl\">הדין טורא בְּרִיכָא</span> this blessed mount (Gerizim, revered by the Samaritans; <span class=\"citation\">Deut. R. s. 3</span> <span dir=\"rtl\">קדיש</span>).</div><div class=\"sense\"><b>Pa. בָּרֵיךְ  בָּרִיךְ</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"בָּרַךְ\">preced.</a> Pi. </div><div class=\"sense\"><b>1)</b> <i>to bless</i> &amp;c. <span class=\"citation\">Targ. Deut. VIII, 10</span>; a. fr.—Esp. <i>to say grace after meal</i>. <span class=\"citation\">Ber. 46ᵃ</span> <span dir=\"rtl\">כי מטי לְבָרוּכֵי וכ׳</span> when it was time to say grace, he said, Will you please, say grace for us. Y. ib. VI, 10ᵇ <span dir=\"rtl\">מהו למיבָרְכָה בסופה</span> what benediction must be said after it? Ib. bot. <span dir=\"rtl\">לא אנא חכים מברכא</span> I do not know how to say grace after it.—Part. pass. <span dir=\"rtl\">מְבָרַךְ</span>. <span class=\"citation\">Targ. Y. II, Gen. XLIX, 2</span>.</div><div class=\"sense\"><b>—2)</b> <i>to blaspheme</i>. <span class=\"citation\">Targ. Job II, 9</span>.—<span class=\"citation\">Snh. 56ᵃ</span> <span dir=\"rtl\">לישנא דברוכי</span> in the sense of blaspheming.</div></div><div class=\"sense\"><b>Ithpe. אִתְבָּרֵיךְ</b> <div class=\"sense\"> as <a href=\"#\" data-headword=\"בָּרַךְ\">preced.</a> Hithpa. <span class=\"citation\">Targ. Gen. XII, 3</span>; a. fr.</div></div>","alt":["בְּרֵיךְ"]},"4746":{"h":"בֶּרֶךְ","r":"B01289","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"בְּרַךְ\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>knee</i>. <span class=\"citation\">Y. Ber. I, 3ᵈ</span> top.</div><div class=\"sense\"><b>—2)</b> <i>a knee-shaped pole</i>. <span class=\"citation\">Taan. 25ᵇ</span> <span dir=\"rtl\">כמלא ב׳ חמחרישה</span> (Var. <a href=\"#\" data-headword=\"כּוּךְ\">כוך</a>, v. Rabb. D. S. a. l.) (until the rain penetrates) as far as the knee of the plough enters the soil; Ohol. XVII, 1 <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בו׳</a>. <span class=\"citation\">Kel. XXI, 2</span> <a href=\"#\" data-headword=\"בַּצּוֹרְתָא\">בו׳</a>. [<span class=\"citation\">Tosef. Shebi. IV, 20</span> <span dir=\"rtl\">ברך</span>, v. <a href=\"#\" data-headword=\"בְּרִיכָה\">בְּרִיכָה</a>.]—<i>Du.</i> <span dir=\"rtl\">בִּרְכַּיִם</span>. <span class=\"citation\">Ber. 34ᵇ</span>; <span class=\"citation\">Meg. 22ᵇ</span>; <span class=\"citation\">Shebu. 16ᵇ</span> <span dir=\"rtl\">כריעה על ב׳</span> the word <span dir=\"rtl\">כרע</span> means falling on one’s knees. [<span dir=\"rtl\">בִּרְכּוֹת</span>, v. <a href=\"#\" data-headword=\"בְּרִיכָה\">בְּרִיכָה</a>.]</div>","alt":["(בּוֹרֶךְ)"]},"4747":{"h":"בֶּרֶךְ ²","r":"B01290","html":"<div class=\"sense\"><b>1)</b> <i>knee</i>. <span class=\"citation\">Targ. Is. XLV, 23</span>.—Pl. <a href=\"#\" data-headword=\"בֶּרֶךְ ²\">בִּרְכַּיָא</a>, <a href=\"#\" data-headword=\"*בִּנְכֵּי\">בִּרְכֵּי</a>, <a href=\"#\" data-headword=\"בִּדּוּר\">בִּי׳</a>. <span class=\"citation\">Targ. Jud. VII, 6</span>; a. e.—<span class=\"citation\">Ber. 6ᵃ</span> <span dir=\"rtl\">הנהו ב׳ וכ׳</span> those fatigued knees (of scholars) must be ascribed to them (the demons). <span class=\"citation\">Pes. 108ᵃ</span>, v. <a href=\"#\" data-headword=\"זְגָא\">זְגָא</a>.</div><div class=\"sense\"><b>—2)</b>  = h. <a href=\"#\" data-headword=\"בְּרִיכָה\">בְּרִיכָה</a>. Pl. <span dir=\"rtl\">בִּירְכֵּי</span> <i>shoots, branches</i>. <span class=\"citation\">Tam. 30ᵃ</span> top (Var. in Rashi <span dir=\"rtl\">בְּרִיכֵי</span>, Ar. <span dir=\"rtl\">בורכי</span>).</div>","alt":["בִּרְכָּא","בִּירְכָּא"]},"4748":{"h":"בִּרְכָא","r":"B01291","html":"<div class=\"sense\">, f. ch. = h., <i>blessing, plenty</i>. <span class=\"citation\">Targ. Is. XIX, 24</span>.—<a href=\"#\" data-headword=\"בִּרְכָא\">בִּרְכָאן</a> plenty for us, <i>we have enough with</i>. <span class=\"citation\">Gen. R. s. 78</span> <span dir=\"rtl\">אית במאתן ב׳</span> we have enough with two hundred fables; <span class=\"citation\">Yalk. ib. 133</span> <a href=\"#\" data-headword=\"בִּרְכָא\">בִּרְכָן</a>.—Pl. <a href=\"#\" data-headword=\"בִּרְכָא\">בִּרְכָן</a>, <a href=\"#\" data-headword=\"בִּדּוּר\">בִּי׳</a>; <span class=\"citation\">Targ. O. Gen. XXVII, 12</span> (Y. <span dir=\"rtl\">בִּרְכָאָן</span>; ib. 13 <a href=\"#\" data-headword=\"בִּירְכָא\">בִּירְכַן</a>). [בִּרְכַיָּא <span class=\"citation\">Targ. O. Deut. XXVIII, 2</span>, some ed.] V. <a href=\"#\" data-headword=\"בִּרְכְתָא\">בִּרְכְתָא</a>.</div>","alt":["בִּירְכָא"]},"4749":{"h":"בְּרָכָה","r":"B01292","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>blessing, bestowal of prosperity, good wishes, choice, plenty</i>. <span class=\"citation\">Keth. 5ᵃ</span> <span dir=\"rtl\">הואיל … ב׳ לדגים</span> because on it the blessing was given to the fish (<span class=\"citation\">Gen. I, 22</span>, to be fruitful). Y. ib. I, beg. 24ᵈ <span dir=\"rtl\">אין כתיב ב׳ וכ׳</span> the blessing (<span class=\"citation\">Gen. II, 3</span>) refers not to man but to the day.—<span class=\"citation\">Erub. 63ᵇ</span>, a. fr. <span dir=\"rtl\">תבא עליו ב׳</span> blessing rest upon him (he acts rightly). <span class=\"citation\">Keth. 103ᵃ</span>; <span class=\"citation\">B. Bath. 144ᵇ</span> <span dir=\"rtl\">בִּרְכַת הבית ברובה</span> the blessing of a house consists in the number of inmates (every member of a household contributes to its comfort); <span class=\"citation\">Tosef. Keth. XII, 3</span> <span dir=\"rtl\">ב׳ הבית מרובה</span>. <span class=\"citation\">B. Mets. 42ᵃ</span> <span dir=\"rtl\">אין הב׳ מצוייה וכ׳</span> blessing (unexpected supply, miraculous increase) will not take place in things which are weighed &amp;c.; <span class=\"citation\">Taan. 8ᵇ</span>; a. fr.—<span class=\"citation\">Pes. 50ᵇ</span>, a. fr. <span dir=\"rtl\">אינו רואה סימן ב׳ לעולם</span> will never see a sign of prosperity; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>benediction, prayer to be recited on certain occasions</i>. <span class=\"citation\">Ber. 35ᵃ</span> man must not taste anything <span dir=\"rtl\">בלא ב׳</span> without a blessing. <span class=\"citation\">Ib. 40ᵇ</span> <span dir=\"rtl\">כל ב׳ שאין וכ׳</span> a benediction in which the Name of the Lord is not invoked, is no benediction; a. fr.—Pl. <span dir=\"rtl\">בְּרָכוֹת</span>. 1) <i>blessings, benedictions</i>. Ib. 45ᵇ; a. v. fr.—<span class=\"citation\">Sabb. 115ᵇ</span> <span dir=\"rtl\">כותבי ב׳</span> those who write out the formulas of prayer.—2) <i>B’rakhoth</i>, the first treatise of the Mishnah, Talmud, a. Tosefta.—Compounds: <span dir=\"rtl\">בִּרְכַת אבלים</span> the prayer for consolation inserted in the mourners’ grace after meal. <span class=\"citation\">Keth. 8ᵇ</span>; a. fr.—<span dir=\"rtl\">ב׳ ארוסין</span> benediction preceding betrothal, v. <a href=\"#\" data-headword=\"אֵרוּסִין\">אֵרוּסִין</a> <span class=\"citation\">Ib. 7ᵇ</span>.—<span dir=\"rtl\">ב׳ הארץ</span> that portion of the grace after meal which refers to Palestine. <span class=\"citation\">Ib. 8ᵇ</span>.—<span dir=\"rtl\">ב׳ הזבח</span> the benediction before partaking of the festive offering (<a href=\"#\" data-headword=\"חֲגִיגָה\">חֲגִיגָה</a>) which accompanies the Paschal lamb. <span class=\"citation\">Pes. X, 9</span> (<span class=\"citation\">120ᵃ</span>).—<span dir=\"rtl\">ב׳ הזימון</span> the appeal to the partakers of a meal to say grace, <i>common prayer</i>. <span class=\"citation\">Ber. 45ᵇ</span>.—<span dir=\"rtl\">ב׳ חתנים</span> benediction on performing the marriage ceremony, also inserted in the grace after wedding meals during seven days. <span class=\"citation\">Keth. 8ᵇ</span>.—<span dir=\"rtl\">ב׳ כהנים</span> the priestly benediction (<span class=\"citation\">Num. VI, 24—26</span>). <span class=\"citation\">Sot. VII, 6</span>.—<span dir=\"rtl\">ב׳ המזון</span> grace after meal. Keth. l. c.—<span dir=\"rtl\">ב׳ המצוות</span> benediction on performing a divine command (of a symbolic nature). Ib. 7ᵇ.—<span dir=\"rtl\">ב׳ רחבה</span> benediction of consolation pronounced in open air on the mourners’ return from burial (v. <a href=\"#\" data-headword=\"הַבְרָאָה\">הַבְרָאָה</a>). Ib. 8ᵇ.—<span dir=\"rtl\">ב׳ התורה</span> benediction before and after reading the Law. <span class=\"citation\">Y. Ber. I, 3ᶜ</span>.—[For other compounds see the respective determinants.]</div><div class=\"sense\"><b>—3)</b> <i>blasphemy</i>. <span dir=\"rtl\">בִּרְכַת השם</span>. <span class=\"citation\">Snh. 56ᵃ</span> sq.; (<span class=\"citation\">Tosef. Ab. Zar. VIII</span> (<span class=\"citation\">IX), 4</span> <span dir=\"rtl\">קיללת</span>).</div>","alt":[]},"4750":{"h":"ברכוייד","r":"B01293","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kil. III, 12</span>, read <a href=\"#\" data-headword=\"*בּוּכַּרְיָא\">בּוּכַּרְיָא</a> or <a href=\"#\" data-headword=\"*בּוּכַּרְיָא\">בּוּכַּרְיָיא</a>.</div>","alt":["ברכוייר","בורכייד"]},"4751":{"h":"בִּרְכַּיָּיר","r":"B01294","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">בֵּיר כַּיָּיר</span>, v. <a href=\"#\" data-headword=\"בֵּירִית\">בֵּירִית</a> a. <a href=\"#\" data-headword=\"כּוּר I\"><a href=\"#\" data-headword=\"כּוּר I\">כּוּר</a>)</a><i>the stove-setter’s knee-band, the brick-layer’s cushion</i> (on which he kneels at work). <span class=\"citation\">Kel. XXVI, 3</span> (Talm. ed. <span dir=\"rtl\">בור׳</span>).</div>","alt":["בּוּרְכַּיָיר"]},"4752":{"h":"ברכר","r":"B01295","html":"<div class=\"sense\">, <span class=\"citation\">Y. Peah VII, 20ᵃ</span>, v. <a href=\"#\" data-headword=\"*כַּרְכָּר\">כַּרְכָּר</a></div>","alt":["ברכרה"]},"4753":{"h":"בְּרֵכַת","r":"B01296","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"בְּרֵיכָה\">בְּרֵכָה</a>. <span class=\"citation\">Tosef. Mikv. IV, 8</span>.</div>","alt":[]},"4754":{"h":"בִּרְכְתָא","r":"B01297","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. Gen. XXVII, 36</span>; a. fr.—<span class=\"citation\">Ber. 51ᵇ</span> <span dir=\"rtl\">כסא דב׳</span> (= h. <span dir=\"rtl\">כוס של ברכה</span>) the cup for the grace after meal. <span class=\"citation\">Ḥag. 5ᵇ</span> <span dir=\"rtl\">איכו השתא מנעתן מהאי בי׳</span> how near thou camest depriving us of this blessing; a. fr.—Pl. <a href=\"#\" data-headword=\"בִּרְכְתָא\">בִּרְכָתָא</a>, <a href=\"#\" data-headword=\"בִּדּוּר\">בִּי׳</a>. <span class=\"citation\">Targ. Deut. XXVIII, 2</span>; a. fr.</div>","alt":["בִּירְכְתָא"]},"4755":{"h":"בְּרַכְתָּא","r":"B01298","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>B’rakhta</i>. <span class=\"citation\">Y. Ber. VI, 10ᵇ</span> bot.; cmp., however, <a href=\"#\" data-headword=\"מַבְרַכְתָּא\">מַבְרַכְתָּא</a>.</div>","alt":[]},"4756":{"h":"בְּרַם","r":"B01299","html":"<div class=\"sense\"> conj. (ברם <i>to split</i>, √<span dir=\"rtl\">בר</span>, cmp. <span dir=\"rtl\">פרם</span>, v. <a href=\"#\" data-headword=\"בּוּרְמָא\">בּוֹרְמָא</a>) </div><div class=\"sense\"><b>1)</b> <i>besides</i>. <span class=\"citation\">Targ. Y. Ex. XXXVI, 7</span>.</div><div class=\"sense\"><b>—2)</b> <i>however.</i> <span class=\"citation\">Dan. IV, 12</span>; <span class=\"citation\">V, 17</span>.—<span class=\"citation\">Targ. Ps. LVIII, 3</span>; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>only, but</i>. <span class=\"citation\">Targ. Gen. VII, 23</span>. <span class=\"citation\">Targ. Lam. III, 3</span> (h. text <a href=\"#\" data-headword=\"אַךְ I\">אַךְ</a>). <span class=\"citation\">Targ. Ps. LVIII, 2</span> <span dir=\"rtl\">הב׳ בקושטא</span> is it only in truth (indeed)?—<span class=\"citation\">Sabb. 63ᵇ</span>; <span class=\"citation\">Erub. 16ᵇ</span>, a. fr. <span dir=\"rtl\">ב׳ כך אמרו</span> but in fact they said this. <span class=\"citation\">B. Mets. 114ᵃ</span>.—3) interj. <i>truly!, surely!</i> <span class=\"citation\">Sabb. 13ᵇ</span>; <span class=\"citation\">Ḥag. 13ᵃ</span>; <span class=\"citation\">Men. 45ᵇ</span> <span dir=\"rtl\">ב׳ זכור וכ׳</span> truly! this man be remembered for blessing!—[<span class=\"citation\">Ḥull. 112ᵃ</span> <span dir=\"rtl\">דאברים</span> some ed., read: <span dir=\"rtl\">דאבריה</span>, v. <a href=\"#\" data-headword=\"בַּר II\">בְּרָא</a>.]</div>","alt":[]},"4757":{"h":"*ברמור","r":"B01300","html":"<div class=\"sense\">, El. Wil. in <span class=\"citation\">Tosef. Kil. III, 12</span>, for <a href=\"#\" data-headword=\"ברכוייד\">ברכוייר</a>.</div>","alt":[]},"4758":{"h":"*ברנטין","r":"B01301","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Ezek. 356</span>, v. <span dir=\"rtl\">לברטין</span></div>","alt":[]},"4759":{"h":"בַּרְנֵישׁ","r":"B01302","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּרְנֵשׁ\">בַּרְנֵשׁ</a></div>","alt":[]},"4760":{"h":"ברנקיא","r":"B01303","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Is. III, 22</span> Ar., ed. <a href=\"#\" data-headword=\"*לְבוּרְנִיקַיָּא\">לבורניקיא</a> q. v.</div>","alt":[]},"4761":{"h":"בַּרְנֵשׁ","r":"B01304","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Barnesh</i>, in Babylon, prob. the modern <i>Khar-Birnus</i>, near Helle (Neub. Géogr. p. 345), having in its vicinity a Synagogue named after Daniel. <span class=\"citation\">Erub. 21ᵃ</span>. <span class=\"citation\">B. Mets. 73ᵇ</span></div>","alt":["בַּרְנֵישׁ"]},"4762":{"h":"*ברס","r":"B01305","html":"<div class=\"sense\">, Af. <span dir=\"rtl\">אַבְרִיס</span> <i>to bray</i> (used of the wild ass when hungry). <span class=\"citation\">Targ. Job VI, 5</span> (Ms. <span dir=\"rtl\">מַכְרִיס</span>, perh. a denom. of <a href=\"#\" data-headword=\"כֶּרֶס\">כֶּרֶס</a> <i>stomach, appetite</i>).</div>","alt":[]},"4763":{"h":"בִּרְסִין","r":"B01306","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (birrus, βίῤῥος, v. <a href=\"#\" data-headword=\"בִּירוֹס\">בִּירוֹס</a>; formed with a geographical termination, cmp. <a href=\"#\" data-headword=\"בַּרְדְּסִין\">בִּרְדְּסִין</a>) <i>birrus</i>, a cloak of thick woolen material. <span class=\"citation\">Kil. IX, 7</span> (Ms. M. a. Ar. <span dir=\"rtl\">בד׳</span>); Y. ib. 32ᵈ top <a href=\"#\" data-headword=\"בּוּרְסִים\">בּוּרְסִין</a>; expl. <a href=\"#\" data-headword=\"*בריה\">בריה</a>, v. <a href=\"#\" data-headword=\"בִּירְיָא II\"><span dir=\"rtl\">בִּירְיָא</span> II</a>. <span class=\"citation\">Sifré Deut. 234</span> <a href=\"#\" data-headword=\"סדסים\">סדסים</a> read as <span class=\"citation\">Yalk. ib. 933</span> <span dir=\"rtl\">בורס׳</span>.</div>","alt":["(בִּרְסִים)"]},"4764":{"h":"*בַּרְסָם","r":"B01307","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Parel of <span dir=\"rtl\">בסם</span>, cmp. <a href=\"#\" data-headword=\"בַּלְסָם\">בַּלְסָם</a>) <i>a dripping like balsam</i>, whence <i>catarrh of the head</i>. <span class=\"citation\">Ḥull. 105ᵇ</span> קשי לב׳ Ar. (ed. <span dir=\"rtl\">לכ׳</span>, Mus. <a href=\"#\" data-headword=\"כרסום\">כרסום</a>) is liable to produce catarrh; <span dir=\"rtl\">לב׳ דחמרא וכ׳</span> a remedy for a catarrh contracted from drinking the foam of wine, is beer; for thet from beer &amp;c.—<span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">לב׳</span> a remedy for &amp;c. [Ar.: <i>pleurisy</i>. Pers. <span dir=\"rtl\">ברסאם</span>, v. Fl. to Levy Talm. Dict. I, p. 228ᵇ.]</div>","alt":[]},"4765":{"h":"ברסנה","r":"B01308","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּרְסָנָא\">כַּרְסָנָא</a></div>","alt":[]},"4766":{"h":"בָּרַץ","r":"B01309","html":"<div class=\"sense\"> (√<span dir=\"rtl\">בר</span>; cmp. <a href=\"#\" data-headword=\"בְּרַז\">ברז</a>, v. P. Sm. 618) <i>to break through</i>.</div><div class=\"sense\"><b>Pi. בֵּרֵץ</b> <div class=\"sense\"><i>to cut through</i> from end to end. Part. Pu. <span dir=\"rtl\">מְבוֹרָץ</span>. <span class=\"citation\">Tosef. Kil. III, 10</span> <span dir=\"rtl\">חריץ המב׳</span> a ditch which is cut through, going from end to end of the vineyard (Mish. <span class=\"citation\">ib. V, 3</span> <a href=\"#\" data-headword=\"מְפוּלָּשׁ\">מפולש</a>). <span class=\"citation\">Men. I, 2</span> <span dir=\"rtl\">קמצו מב׳</span> the priest’s grasp of the meal offering must be coming forth on both sides.</div></div>","alt":[]},"4767":{"h":"בְּרַץ","r":"B01310","html":"<div class=\"sense\">; <i>Pa.</i> בָּרֵץ <i>to bore</i>. <span class=\"citation\">Ab. Zar. 59ᵇ</span> ובִירְצוּהָ עד דשייפא Ar. (ed. <span dir=\"rtl\">ובָרצוה</span>) and bore into the keg, until it is emptied (Rashi: bend it towards the bung-hole).</div>","alt":[]},"4768":{"h":"בַּרְצוּץ","r":"B01311","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּרַץ\">preced.</a>, cmp. P. Sm. 618 s. v. <span dir=\"rtl\">ברץ</span>, a. Ges. H. Dict. s. v. <span dir=\"rtl\">פאר</span>) <i>the crown of the turban</i>. <span class=\"citation\">Targ. Y. Ex. XXXIX, 28</span> (h. text <a href=\"#\" data-headword=\"פָּארֵי I\">פארי</a>).</div>","alt":[]},"4769":{"h":"בַּרְצִיתָא","r":"B01312","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Be-Bartsitha</i>. <span class=\"citation\">M. Kat. 4ᵇ</span> <span dir=\"rtl\">לבי ב׳</span> early ed. (late ed. <span dir=\"rtl\">לבני בר ציתאי</span>, Ms. M. <span dir=\"rtl\">בר צרתא</span>, v. Rabb. D. S. a. l.).</div>","alt":["בֵּי ב׳"]},"4770":{"h":"בָּרַק","r":"B01313","html":"<div class=\"sense\"> , v. <span dir=\"rtl\">ברר</span>) <i>to be bright, shine, flash</i>. <span class=\"citation\">B. Bath. 97ᵇ</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"יַיִן\">יין</a>) <a href=\"#\" data-headword=\"בּוֹרֵיק\">בּוֹרֵק</a></span> white effervescent wine (not fully fermented; Var. <span dir=\"rtl\">בּוֹדֵק</span> searching in the bowels, i.e. causing diarrhœa, v. <a href=\"#\" data-headword=\"בָּדַק\">בָּדַק</a>); <span class=\"citation\">Tosef. Men. IX, 9</span> <span dir=\"rtl\">הַבּוֹרֵיק</span> (sub. <a href=\"#\" data-headword=\"יַיִן\">יין</a>) the effervescent (wine), v. <a href=\"#\" data-headword=\"בָּארַג\">בָּארַג</a>; <span class=\"citation\">Yoma 28ᵇ</span> top, v. <a href=\"#\" data-headword=\"בְּרַק I\">next w.</a> <span class=\"citation\">Tosef. Ter. VII, 16</span> [read:] <span dir=\"rtl\">ב׳ והניחו</span> if it was effervescent when he left it.</div><div class=\"sense\"><b>Hif. הִבְרִיק</b> <div class=\"sense\"><b>1)</b>  (cmp. (cmp. <span dir=\"rtl\">ברץ ברח</span>) <i>to cut through from end to end</i>. Y. Kil. V, 29ᵈ bot. <span dir=\"rtl\">עד שיהא מַבְרִיק כדי וכ׳</span> until it (the ditch in the vineyard) passes through from end to end, wide enough for man and his tilling cattle.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"בָּרָק\">בָּרָק</a>) <i>to be affected by lightning, get blind</i> (or <i>get vermin</i>). <span class=\"citation\">B. Mets. VI, 3</span>, expl. <span class=\"citation\">ib. 78ᵃ</span> <a href=\"#\" data-headword=\"אַבְזָקַת\">אבזקת</a> a. <a href=\"#\" data-headword=\"נְהוֹרִיתָא I\">נהוריתא</a>.</div></div>","alt":[]},"4771":{"h":"בְּרַק I","r":"B01314","html":"<div class=\"sense\">, <i>to shine, rise</i>. <span class=\"citation\">Y. Yoma III, beg. 40ᵇ</span>; Y. R. Hash. II, beg. 57ᵈ what is <a href=\"#\" data-headword=\"בּוֹרְקַי I\">בורקי</a> (Mish. <span class=\"citation\">Yoma III, 1</span>)? It means <a href=\"#\" data-headword=\"בָּרֶקֶת\">בָּרֶקֶת</a>, the rising light, as people say in Babylonia <span dir=\"rtl\">(<span dir=\"rtl\">בְּרַק ברוקא</span>) <span dir=\"rtl\">בְּרוּק ברוקה</span></span> the sparkling (star) shines, meaning <span dir=\"rtl\">אנהר מנהורא</span> the light-giver (morning star) gives light. [Bab. <span class=\"citation\">Yoma 28ᵇ</span> (hebr.) <span dir=\"rtl\">בָּרַק ברקאי</span>.] <span class=\"citation\">Ber. 59ᵃ</span> (expl. <span dir=\"rtl\">רעמים</span>) <span dir=\"rtl\">ברקא תקיפא דבריק בעננא וכ׳</span> an intense lightning which flashes through the cloud and breaks pieces of hailstone, (Var. v. Rabb. D. S. a. l.).</div><div class=\"sense\"><b>Af. אַבְרֵיק</b> <div class=\"sense\"><i>to send forth lightning</i> (fulminare). <span class=\"citation\">Targ. Ps. CXLIV, 6</span>.—Targ. II Esth. III, 8 <span dir=\"rtl\">מבריקין עיניהון</span> their eyes sparkling (in defiance). [<span class=\"citation\">Ḥull. 112ᵃ</span> <span dir=\"rtl\">דאבריק</span> some ed., read <span dir=\"rtl\">דאבריה</span>, v. <a href=\"#\" data-headword=\"בַּר II\">בְּרָא</a>.]</div></div>","alt":["בְּרֵיק"]},"4772":{"h":"בָּרָק","r":"B01315","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"בְּרַק I\">preced.</a>) <i>lightning</i>. <span class=\"citation\">Lev. R. s. 31</span>.—Pl. <span dir=\"rtl\">בְּרָקִים</span>. <span class=\"citation\">Ber. IX, 2</span>; a. fr.</div>","alt":[]},"4773":{"h":"בְּרַק II","r":"B01316","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>B’ne B’rak</i> (<span class=\"citation\">Josh. XIX, 45</span>, modern <i>Ibn Ibrak</i>) near Japho, seat of R. Akiba’s college. <span class=\"citation\">Snh. 32ᵇ</span>. <span class=\"citation\">Lev. R. s. 21</span>. <span class=\"citation\">Tosef. Sabb. III (IV), 3</span>.</div>","alt":["בְּנֵי ב׳"]},"4774":{"h":"בְּרַק III","r":"B01317","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"בָּרָק\">בָּרָק</a>. <span class=\"citation\">Targ. Deut. XXXII, 41</span> (Y. II <a href=\"#\" data-headword=\"בְּרַק III\">בְּרָקָא</a>); a. fr.—<span class=\"citation\">Ber. 59ᵃ</span> <span dir=\"rtl\">ב׳ יחידאה</span> a single flash (for vers. v. Rabb. D. S. a. l.); a. fr.—Pl. <a href=\"#\" data-headword=\"בְּרַקִּין\">בְּרָקִין</a>, <a href=\"#\" data-headword=\"בַּרְקִית\">בַּרְקִין</a>, <a href=\"#\" data-headword=\"בַּרְקָנַיָּא\">בַּרְקַיָּא</a>, <span dir=\"rtl\">בַּרְקֵי</span>. <span class=\"citation\">Targ. Ps. XVIII, 15</span>; a. fr. [Y. R. Hash. II, beg. <span dir=\"rtl\">ברק ברקא</span>, read <a href=\"#\" data-headword=\"בַּרְקַאי I\">בַּרְקַאי</a>.] Ber. l. c. <span dir=\"rtl\">וברקיא ירוקתא</span> some ed. (read <span dir=\"rtl\">ירוקרקי</span> as Ms. M.). Ib. <span dir=\"rtl\">דבריק ברקי ומנהמי וכ׳</span> (read <span dir=\"rtl\">דברוק</span></div><div class=\"sense\"><b>—2)</b> <i>white cataract</i> (v. <a href=\"#\" data-headword=\"בָּרַק\">בָּרַק</a> Hif.), cmp. <a href=\"#\" data-headword=\"בַּרְקִית\">בַּרְקִית</a>. <span class=\"citation\">Bekh. 38ᵇ</span> <span dir=\"rtl\">וסימנך ברקא</span> and thy sign (by which to remember which of the two affections of the eye is considered a blemish) take <i>barka</i> (meaning <i>white</i> and <i>cataract</i>, and like the cataract is the floating white spot in the eye a disqualifying blemish). V. <a href=\"#\" data-headword=\"בַּרְקָא II\">next w.</a></div>","alt":["בַּרְקָא I"]},"4775":{"h":"בַּרְקָא II","r":"B01318","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּרַק I\">ברק</a>) </div><div class=\"sense\"><b>1)</b>  (adj.) <i>shining, white</i>. <span class=\"citation\">Snh. 98ᵃ</span> <span dir=\"rtl\">סוסיא ב׳</span> a white horse, v. <a href=\"#\" data-headword=\"בָּארַג\">בָּארַג</a>.—Pl. <span dir=\"rtl\">בַּרְקֵי</span>. <span class=\"citation\">Y. B. Bath. VIII, 16ᵇ</span> top; <span class=\"citation\">Y. Kidd. I, 60ᶜ</span> bot. he let him ride <span dir=\"rtl\">אתרי ריכשי ב׳</span> on two white steeds (i.e. the donator gave him a doubly fortified document; another opin.: he made him ride on two …, which run in different directions, i.e. the document is invalid; v. explan. ibid., cmp. <span class=\"citation\">B. Bath. 152ᵃ</span>, <span class=\"citation\">Keth. 55ᵃ</span>. <span class=\"citation\">Gitt. 69ᵃ</span> <span dir=\"rtl\">שודרא ב׳</span> a string of white hair. <span class=\"citation\">Sabb. 67ᵃ</span>; <span class=\"citation\">Ab. Zar. 28ᵇ</span> <span dir=\"rtl\">נירא ב׳</span> a white thread (of hair).</div><div class=\"sense\"><b>—2)</b>  (as a noun) <i>something white, white thread</i>. Ib. <span dir=\"rtl\">וליתוב ב׳ וכ׳</span> and let him put a white thread around one end. Ib. <span dir=\"rtl\">פתילי ב׳</span> Ms. M. (ed. <span dir=\"rtl\">פתילתא ביקרא</span>, corr. acc.) strings of white stuff.</div>","alt":[]},"4776":{"h":"*בַּרְקָא III","r":"B01319","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בָּרַק\">בָּרַק</a> Hif.) <i>a compartment near the house with windows on all sides, a kind of piazza</i>. <span class=\"citation\">Erub. 15ᵃ</span> (Rashi Ms. M. <a href=\"#\" data-headword=\"בִּדְקָא\">בדקא</a>). <span class=\"citation\">B. Bath. 61ᵃ</span> ב׳ חלילא Ms. M. a. oth. (ed. <a href=\"#\" data-headword=\"בִּדְקָא\">בדקא</a>; expl. <a href=\"#\" data-headword=\"יָצִיעַ I\">יציע</a>) a piazza open all around.</div>","alt":[]},"4777":{"h":"בַּרְקַאי I","r":"B01320","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>morning star</i>. <span class=\"citation\">Yoma III, 1</span>; <span class=\"citation\">28ᵇ</span>; v. <a href=\"#\" data-headword=\"בְּרַק I\">בְּרַק</a>. [Y. ed. <a href=\"#\" data-headword=\"בּוֹרְקַי I\">בּוֹרְקַי</a> q. v.]</div>","alt":[]},"4778":{"h":"בַּרְקַאי II","r":"B01321","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוֹרְקַי II\"><span dir=\"rtl\">בּוֹרְקַי</span> II</a>.</div><div class=\"sense\"><b>—2)</b>  כְּפַר ב׳ <i>K’far Barkai</i>, in Palestine; cmp. <span dir=\"rtl\">בורגתא</span>. <span class=\"citation\">Pes. 57ᵃ</span>; <span class=\"citation\">57ᵇ</span></div>","alt":[]},"4779":{"h":"ברקום","r":"B01322","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 98</span>, read <a href=\"#\" data-headword=\"לִיבְדְּקוֹס\">לִיבְדְּקוֹס</a>.—<span class=\"citation\">Targ. Cant. II, 1</span>, read <a href=\"#\" data-headword=\"נַרְקֵיס\">נַרְקִיס</a>.</div>","alt":[]},"4780":{"h":"בַּרְקוּרְיָאנִי","r":"B01323","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (disguise of Herculiani, cmp. <a href=\"#\" data-headword=\"דוּרְמוֹס\">דּוּרְמוֹס</a>) <i>Herculiani</i>, a cohort of pretorians named after Diocletian (Heraclius). <span class=\"citation\">Esth. R. to I, 3</span> <span dir=\"rtl\">יכולני וכ׳</span> (read <span dir=\"rtl\">יוֹבְיָינִי</span>); some ed. <span dir=\"rtl\">בר קוריאני</span> (in two words) Joviani and Herculiani. v. Sachs Beitr. I, 113 sq., ref. to Amm. Marc. XXII, 3, 2.</div>","alt":[]},"4781":{"h":"בַּרְקוּת","r":"B01324","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בַּרְקִית\">בַּרְקִית</a></div>","alt":[]},"4782":{"h":"בְּרַקִּין","r":"B01325","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַבְרְקִין\">אַבְרְקִין</a></div>","alt":[]},"4783":{"h":"בַּרְקִירְיָא","r":"B01326","html":"<div class=\"sense\"> p. n. m. <i>Barkirya</i>, an Amora. Y. Kil. IX, 32ᵈ top; <span class=\"citation\">Y. Keth. XII, 35ᵇ</span> bot. <span dir=\"rtl\">בר קריא</span>.</div>","alt":[]},"4784":{"h":"בַּרְקִית","r":"B01327","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּרַק I\">ברק</a>, v. <a href=\"#\" data-headword=\"בְּרַק III\"><span dir=\"rtl\">בַּרְקָא</span> I</a>) <i>cataract of the eye</i>. <span class=\"citation\">Sabb. 78ᵃ</span> <span dir=\"rtl\">שכן כוחלין לב׳</span> for they paint the eye with blood as a remedy for a cataract. <span class=\"citation\">Tosef. ib. VI</span> (<span class=\"citation\">VII), 7</span> <a href=\"#\" data-headword=\"בַּרְקוּת\">ברקוּת</a> (Var. <span dir=\"rtl\">ברקי׳</span>). V. <a href=\"#\" data-headword=\"בְּרַקְתִּי\">בְּרַקְתִּי</a>.</div>","alt":[]},"4785":{"h":"בַּרְקָן","r":"B01328","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"בַּרְקָתָא\">בַּרְקְתָא</a></div>","alt":[]},"4786":{"h":"בַּרְקָנַיָּא","r":"B01329","html":"<div class=\"sense\"> ch. = <a href=\"#\" data-headword=\"בַּרְקָנִים\">next w.</a> <span class=\"citation\">Targ. Jud. VIII, 7</span>; <span class=\"citation\">16</span>.</div>","alt":[]},"4787":{"h":"בַּרְקָנִים","r":"B01330","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (b. h.) <i>thistles</i>. <span class=\"citation\">Yoma 69ᵃ</span> (quot. fr. Meg. Taan. ch. IX) they dragged them <span dir=\"rtl\">על הקוצים ועל הב׳</span> over thorns and thistles.</div>","alt":[]},"4788":{"h":"בָּרֶקֶת","r":"B01331","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּרַק I\">ברק</a>) <i>morning star</i> (in b. h. <i>a jewel</i>, v. <a href=\"#\" data-headword=\"בַּרְקָתָא\">next w.</a>). <span class=\"citation\">Y. Yoma III, beg. 40ᵃ</span>; Y. R. Hash. II, beg. 57ᵈ, expl. <a href=\"#\" data-headword=\"בּוֹרְקַי I\">בּוֹרְקַי</a>; v. <a href=\"#\" data-headword=\"בְּרַק I\"><span dir=\"rtl\">בְּרַק</span> I</a>.</div>","alt":[]},"4789":{"h":"בַּרְקָתָא","r":"B01332","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = b. h. <a href=\"#\" data-headword=\"בָּרֶקֶת\">בָּרֶקֶת</a>, <i>a jewel</i>, prob. <i>smaragd</i>. <span class=\"citation\">Targ. Ex. XXVIII, 17</span>; a. e. <span class=\"citation\">Targ. Ezek. XXVIII, 13</span>. <span class=\"citation\">Targ. Cant. V, 14</span> (ed. Vien. <a href=\"#\" data-headword=\"בַּרְקָן\">בִּרְקַן</a>, corr. acc.); a. e.—<span class=\"citation\">Targ. Y. Num. II, 3</span> <a href=\"#\" data-headword=\"בַּרְקָתָא\">ברוקא</a>.</div>","alt":["בַּרְקָן","בָּרוֹקָא"]},"4790":{"h":"בַּרְקָתָא ²","r":"B01333","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בּוּרְגָּתָה\">בּוּרְגָּתָה</a></div>","alt":[]},"4791":{"h":"בְּרַקְתִּי","r":"B01334","html":"<div class=\"sense\"> f. ch. = h. <a href=\"#\" data-headword=\"בַּרְקִית\">בַּרְקִית</a>. <span class=\"citation\">Pes. 111ᵇ</span> קשה לב׳ Ar. (ed. <span dir=\"rtl\">לבְרוּקְתִּי</span>) is liable to produce a cataract. <span class=\"citation\">Gitt. 69ᵃ</span> top <span dir=\"rtl\">לברוק׳</span></div>","alt":[]},"4792":{"h":"בָּרַר","r":"B01335","html":"<div class=\"sense\"> [<i>to clear, clean; to place outside</i>, whence] </div><div class=\"sense\"><b>1)</b> <i>to make clear, prove, ascertain</i>. <span class=\"citation\">Keth. 46ᵃ</span> (interpret. <span class=\"citation\">Deut. XXII, 17</span>) <span dir=\"rtl\">ובוֹרְרִין את הדבר וכ׳</span> and they make the fact as clear (bright) as a new garment.—Part. pass. <a href=\"#\" data-headword=\"בָּרוּר\">בָּרוּר</a> q. v.</div><div class=\"sense\"><b>—2)</b> <i>to single out, select, sift, assort.</i> <span class=\"citation\">Maasr. II, 6</span> <span dir=\"rtl\">שאָבוֹר לי</span> which I may select for me. Ib. <span dir=\"rtl\">בּוֹרֵר ואוכל</span> he has a right to pick out and eat (one after the other). <span class=\"citation\">Kil. II, 1</span> <span dir=\"rtl\">יָבוֹר</span> he must take it out entirely. <span class=\"citation\">Sabb. VII, 2</span> <span dir=\"rtl\">הבּוֹרֵר</span> he who sifts (a labor forbidden on the Sabbath). Y. ib. VII, 10ᵃ, a. fr. <span dir=\"rtl\">משום בורר</span> (is guilty) because it comes under the class of sifting. Bab. ib. 74ᵃ <span dir=\"rtl\">בורר ואוכל וכ׳</span> he may take out singly and eat, take out singly and put it down (rejecting it) <span dir=\"rtl\">ולא יִבְרוֹר</span> but he must not assort (v. discussion ibid.). <span class=\"citation\">Gitt. V, 9</span> <span dir=\"rtl\">לא תָבוֹר</span> she must not help her to sift the grain. <span class=\"citation\">Snh. 45ᵃ</span> <span dir=\"rtl\">בְּרוֹר לו וכ׳</span> choose for the convict the most gentle method of execution; <span class=\"citation\">Sot. 8ᵇ</span>, a. fr.—<span class=\"citation\">Snh. III, 1</span> <span dir=\"rtl\">זה בורר וכ׳</span> each party chooses one judge, and the two judges <span dir=\"rtl\">בּוֹרְרִין וכ׳</span> elect a third.</div><div class=\"sense\"><b>Pi. בֵּרַר  בֵּירַר</b> <div class=\"sense\"><b>1)</b> <i>to prove, ascertain</i>. <span class=\"citation\">Snh. 23ᵇ</span> <span dir=\"rtl\">צריך לבָרֵר</span> the claimant must offer clear evidence. <span class=\"citation\">Kerith. 24ᵃ</span> <span dir=\"rtl\">לב׳ עוון</span> to ascertain whether or not the woman was guilty; <span class=\"citation\">Num. R. s. 9</span>, v. <a href=\"#\" data-headword=\"בָּעַר\">בָּעַר</a>. Y. Kidd. III, 63ᵈ, v. <a href=\"#\" data-headword=\"סִימְפּוֹן\">סִימְפּוֹן</a>. <span class=\"citation\">Lev. R. s. 11</span>; v. <i>Nithpa.</i></div><div class=\"sense\"><b>—2)</b> <i>to sift, select</i>. Y. Ber. IX, 13ᶜ top <span dir=\"rtl\">דש זרה ובי׳</span> he threshed, winnowed and sifted. Y. Ned. I, beg. 51ᵃ <span dir=\"rtl\">לשונות שביררו להן וכ׳</span> the terms (for oaths, vows &amp;c.) which the Mishnahs have selected (as substitutes for the real expressions of oaths &amp;c.); Bab. <span class=\"citation\">Ned. 10ᵇ</span> <span dir=\"rtl\">שבדו</span>, v. <a href=\"#\" data-headword=\"בָּדָא\">בָּדָא</a>. [<span class=\"citation\">Esth. R. to I, 22</span> [read:] <span dir=\"rtl\">בירר להם בלשון … רומי מלשון יוני</span> interpreted for them (the Bible) in Latin &amp;c., v. <a href=\"#\" data-headword=\"בָּדָא\">בָּדָא</a>. The passage is defective; cmp. Y. Meg. I, 71ᶜ top.] [Y. Snh. X, 28ᵃ <span dir=\"rtl\">בחרו להם ביררו הברזל וכ׳</span>, read <a href=\"#\" data-headword=\"בְּרִיּוּת\">בְּרִיּוּת</a>, they selected (as similes for the Law) the soundness of the iron and the fixedness of the tree; cmp. <span class=\"citation\">Num. R. s. 14</span>; <span class=\"citation\">Koh. R. to XII, 11</span>.]</div></div><div class=\"sense\"><b>Hof. הוּבְרָר</b> <div class=\"sense\"><i>to be cleared up, to be decided</i> (between two alternatives); v. <a href=\"#\" data-headword=\"בְּרֵירָה\">בְּרֵירָה</a>. <span class=\"citation\">Bets. 4ᵃ</span> (a hen is bought either for consumption or for breeding) <span dir=\"rtl\">נשחטה הובְרָרָה וכ׳</span> by its being killed, it appears that it was originally intended for slaughtering; <span class=\"citation\">Ḥull. 14ᵃ</span></div></div><div class=\"sense\"><b>Nif. נִבְרָר</b> <div class=\"sense\"><i>to be selected</i>. Tanḥ. Sh’laḥ. 4 <span dir=\"rtl\">נִבְרְרוּ צדיקים</span> they were righteous at the time they were selected.</div></div><div class=\"sense\"><b>Nithpa. נִתְבָּרֵר</b> <div class=\"sense\"><b>1)</b> <i>to desire clearness, to seek evidence, search for truth</i>. <span class=\"citation\">Lev. R. s. 11</span> (ref. to <span class=\"citation\">II Sam. XXII, 26</span> sq.) <span dir=\"rtl\">בשעה שנ׳ על עסקיו הק&quot;בה בירר לו וכ׳</span> when he desired to be enlightened about his affairs (asking, ‘Whereby shall I know, <span class=\"citation\">Gen. XV, 8</span>), the Lord enlightened him &amp;c. (ib. 13). Ib. <span dir=\"rtl\">בשעה שנ׳ וכ׳</span> (with ref. to Moses); <span class=\"citation\">Midr. Till. to Ps. XVIII, 26</span> sq.</div><div class=\"sense\"><b>—2)</b> <i>to be confirmed, established</i>. Tanḥ. T’tsavveh 9, end [read:] <span dir=\"rtl\">נִתְבָּרְרָה כהונה בידם</span> through them the priesthood became established. Pesik. Dibré p. 115ᵇ [read as:] <span class=\"citation\">Yalk. Jer. 258</span> <span dir=\"rtl\">לא נ׳ … עד שעמד וכ׳</span> their prophecies were not fulfilled until Jer. arose.</div></div>","alt":[]},"4793":{"h":"בְּרַר","r":"B01336","html":"<div class=\"sense\"><i>Pa.</i> <a href=\"#\" data-headword=\"בָּרִיר\">בָּרֵיר</a> same. <span class=\"citation\">Targ. I Chr. XXI, 13</span>. <span class=\"citation\">Targ. Is. I, 25</span>; a. e.—<span class=\"citation\">Bekh. 57ᵃ</span> <span dir=\"rtl\">לִיבְרוֹר חד וכ׳</span> let him take out (for destruction) one lamb as an equivalent of the dog; v. <a href=\"#\" data-headword=\"בְּרֵירָה\">בְּרֵירָה</a>; <span class=\"citation\">Y. Shek. VI, 50ᵇ</span> <span dir=\"rtl\">נברור וכ׳</span></div><div class=\"sense\"><b>Ithpe. אִתְבְּרִיר</b> <div class=\"sense\"><i>to be clear, pure</i>. <span class=\"citation\">Targ. Job XXV, 5</span>.</div></div>","alt":[]},"4794":{"h":"בְּרָרָא","r":"B01337","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ברר</span>) </div><div class=\"sense\"><b>1)</b> <i>pureness, unalloyed metal</i>. <span class=\"citation\">Y. Shek. VI, 50ᵇ</span>; <span class=\"citation\">Y. Yoma IV, 41ᵈ</span> top <span dir=\"rtl\">עד דלא יקום על בְּרָרֵיה וכ׳</span> as long as the gold ore is not reduced to its pure state, it looses much in the smelting process; but when once brought to its pure state, nothing is lost.</div><div class=\"sense\"><b>—2)</b> <i>clearness, truth</i>. <span class=\"citation\">Y. Yeb. VIII, 9ᵇ</span> top; XV, 15ᵃ <span dir=\"rtl\">דו משים</span> (<span dir=\"rtl\">מקים</span>) … <span dir=\"rtl\">על ב׳</span> because he based the matter on truth (gave a clear decision).</div>","alt":[]},"4795":{"h":"*ברשאן","r":"B01338","html":"<div class=\"sense\">, Ar. (s. v. <span dir=\"rtl\">בר</span>) <span dir=\"rtl\">בר שאן</span>, <i>in ecstacy</i>(?); <i>naked</i>(?). <span class=\"citation\">Targ. I Sam. XIX, 25</span> (v. Rashi a. l.; h. text <span dir=\"rtl\">ערום</span>; Var. lect. <a href=\"#\" data-headword=\"בֵּישָׁן\">ביישן</a>).</div>","alt":["בִּרְשָׁן"]},"4796":{"h":"בְּרַת I","r":"B01339","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"בַּר II\"><span dir=\"rtl\">בַּר</span> II</a>) <i>daughter, child, issue; young tree</i>. <span class=\"citation\">Targ. Gen. XXX, 21</span>; a. fr.—<span class=\"citation\">B. Bath. 141ᵃ</span> <span dir=\"rtl\">ב׳ נמי וכ׳</span> the Lord did not suffer Abraham to be even without a daughter. <span class=\"citation\">M. Kat. 9ᵇ</span> ב׳ אוכמתא Ms. M., v. <a href=\"#\" data-headword=\"אוּכָּם\">אוּכָּם</a>. Y. B. Mets. III, 8ᶜ bot. <span dir=\"rtl\">ב׳ נוקבה</span> female issue. <span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">ב׳ פחין</span> a mean woman.—<span dir=\"rtl\">ב׳ קלא</span> = <span dir=\"rtl\">בַּת קוֹל</span>.—<span dir=\"rtl\">ב׳ שבע</span> a species of <i>figs</i>. <span class=\"citation\">Gen. R. s. 15</span>, end (h. <span dir=\"rtl\">בנות שבע</span>). Y. B. Bath. II, end, 13ᶜ <span dir=\"rtl\">ב׳ שובעין חיורין</span> white figs; a. fr. [For other compounds, v. respective determinants.]—Pl. <a href=\"#\" data-headword=\"בְּנָן\">בְּנָן</a>, <a href=\"#\" data-headword=\"בְּנָאתָן\">בְּנָאתָן</a>, <a href=\"#\" data-headword=\"בְּנָתָא\">בְּנָתָן</a>. [<span class=\"citation\">Targ. Y. Ex. X, 9</span> <span dir=\"rtl\">בְּרַתָנָא</span> our daughters.] <span class=\"citation\">Targ. Gen. V, 4</span>; a. fr.—<span class=\"citation\">Keth. IV, 11</span> <span dir=\"rtl\">ב׳ נוקבין</span>, v. <a href=\"#\" data-headword=\"בַּר II\"><span dir=\"rtl\">בַּר</span> II</a>. <span class=\"citation\">Kidd. 71ᵇ</span> <span dir=\"rtl\">בְּנָתִין</span> our daughters. <span class=\"citation\">B. Bath. 141ᵃ</span> לדידי בנתן וכ׳ I prefer daughters &amp;c.; a. fr.—[<span class=\"citation\">Y. Peah VII, 20ᵃ</span> bot. <span dir=\"rtl\">ב׳ דחרובתא</span>; <span class=\"citation\">Y. Sot. I, 17ᵇ</span> top <a href=\"#\" data-headword=\"אוּרְתָּא\">אורתא</a>, v. <a href=\"#\" data-headword=\"כְּוַורְתָּא\">כְּוַרְתָּא</a>.]</div>","alt":["בְּרַתָּא"]},"4797":{"h":"בְּרַת II","r":"B01340","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>B’rath Ḥavran</i> (or <i>Horan</i>) prob. ident. with Beth-Horon, v. <a href=\"#\" data-headword=\"חוֹרוֹן\">חוֹרוֹן</a>. <span class=\"citation\">Y. M. Kat. I, 80ᵇ</span> bot.; <span class=\"citation\">Y. Shek. I, 46ᵃ</span>; <span class=\"citation\">Y. Ab. Zar. III, 42ᶜ</span> top; <span class=\"citation\">Y. Sot. IX, 23ᶜ</span> top.</div>","alt":["ב׳ חווּרן"]},"4798":{"h":"בְּרַתָּא","r":"B01341","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"בְּרַת I\"><span dir=\"rtl\">בְּרַת</span> I</a></div>","alt":[]},"4799":{"h":"בְּרָתָא","r":"B01342","html":"<div class=\"sense\"> c. (= h. <a href=\"#\" data-headword=\"בְּרוֹשׁ\">בְּרוֹשׁ</a>; <a href=\"#\" data-headword=\"בַּר II\">ברת</a> or <a href=\"#\" data-headword=\"ברי\">ברי</a>, v. pl. <a href=\"#\" data-headword=\"בִּירוָון\">בִּרְוַן</a>; √<span dir=\"rtl\">בר</span>, v. <span dir=\"rtl\">ברר</span>) [<i>the chosen</i> or <i>strong</i>,] <i>cypress</i>, or <i>pine-tree</i>. Targ. II Esth. II, 7 (transl. of <span class=\"citation\">Is. LV, 13</span>). <span class=\"citation\">Y. Keth. VII, end, 31ᵈ</span>; <span class=\"citation\">Gen. R. s. 15</span>; <span class=\"citation\">B. Bath. 80ᵇ</span> בראתא Ms. M. (ed. <a href=\"#\" data-headword=\"בְּרָתֵי\">בְּרָתֵי</a> pl.; for oth. var. v. Rabb. D. S. a. l.); <span class=\"citation\">R. Hash. 23ᵃ</span> (transl. <a href=\"#\" data-headword=\"בְּרוֹשׁ\">ברוש</a>). [<span class=\"citation\">Y. Peah VIII, 20ᵈ</span> bot. <span dir=\"rtl\">לְהָן אֲהָן צררא סמך הדא ב׳</span> what has this pebble to do near this cypress?—an evasive answer or a rebuke; prob. to be read <a href=\"#\" data-headword=\"בֵּירְתָא\">בִּירְתָא</a>.]—Pl. <span dir=\"rtl\">בְּרָתִין</span>, <a href=\"#\" data-headword=\"בְּרָתֵי\">בְּרָתֵי</a>, <a href=\"#\" data-headword=\"בַּר II\">בְּרָא׳</a>. <span class=\"citation\">Targ. Cant. I, 17</span>. <span class=\"citation\">Targ. Ps. CIV, 17</span>; a. e.—(Fem.) <a href=\"#\" data-headword=\"בִּירוָון\">בִּרְוַן</a>, <a href=\"#\" data-headword=\"בִּירוָון\">בִּירְוַן</a>, <a href=\"#\" data-headword=\"בִּרְוָון\">בִּרְוָון</a>. <span class=\"citation\">Targ. Is. XLI, 19</span>; a. fr. [Ar. ed. Koh. <a href=\"#\" data-headword=\"בִּירְתִין\">בִּירְתִין</a>, <span class=\"citation\">Targ. II Sam. VI, 5</span>.—<span class=\"citation\">Targ. Y. II, Num. XXIV, 6</span> <span dir=\"rtl\">בכריותיה</span> ed., <a href=\"#\" data-headword=\"כַּבָּרִיתָא\">כבריתא</a> Ar., read <span dir=\"rtl\">כבְרָתַיָּא</span>.]</div>","alt":["בְּרוֹתָא","בְּרָאתָא"]}};
